/* 面试知识库：内容由当前目录的简历、总结.md 与 av.md 整理。 */
const TOPICS = [
  {id:'adaptivevuls', name:'AdaptiveVuls', icon:'shield', color:'#b7f34a', desc:'核心方法、OES、证据门与实验'},
  {id:'harness', name:'Workflow-Harness', icon:'workflow', color:'#6eb8ff', desc:'Runner、Session 与运行时工程'},
  {id:'security', name:'安全知识', icon:'lock', color:'#ff7d7d', desc:'Web/API、内存安全、漏洞分析'},
  {id:'agent', name:'Agent 与 LLM', icon:'bot', color:'#bca4ff', desc:'模型基础、RAG、Memory 与编排'},
  {id:'backend', name:'后端与数据库', icon:'database', color:'#ffbc66', desc:'MySQL、Redis、可靠性与系统设计'},
  {id:'os', name:'操作系统', icon:'cpu', color:'#65d8c2', desc:'进程、内存、I/O 与容器'},
  {id:'network', name:'计算机网络', icon:'network', color:'#72b8ff', desc:'TCP、HTTP、TLS 与连接管理'},
  {id:'computer', name:'计算机组成', icon:'chip', color:'#ff8ebf', desc:'Cache、流水线与内存模型'},
  {id:'algorithm', name:'数据结构算法', icon:'code', color:'#d5d85b', desc:'高频结构、模板与手写题'}
];

let _qid = 0;
const q = (category, subcategory, question, shortAnswer, fullAnswer, followUps, relatedProject, difficulty='中等', tags=[], priority='常规') => ({
  id:`q${String(++_qid).padStart(3,'0')}`, category, subcategory, question, shortAnswer, fullAnswer, followUps, relatedProject, difficulty, tags, priority
});

const QUESTIONS = [
  q('adaptivevuls','项目定位','请按照最新简历，用一分钟介绍 AdaptiveVuls。','这是一个基于 Workflow-Harness 的长程开放式漏洞调查智能体：Thin Runtime 管完整 Coding Agent 的运行边界，外部状态与证据反馈持续调整仓库级多方向搜索。',`<p><strong>先讲相关工作缺口：</strong>传统 SAST/Fuzzing 擅长已知规则或稳定 Oracle，许多 LLM 漏洞检测与验证工作从给定代码单元、漏洞类型或冻结候选出发；当漏洞类型、位置和候选路径均未知时，在线证据怎样持续调整仓库级多方向搜索，研究相对不足。</p><p><strong>再讲四项机制：</strong>Multi-Runner & Thin Runtime 统一适配 Codex、Claude Code、OpenCode，管理 Session、Workspace、Artifact、预算、权限和恢复，但不接管 Agent 原生搜索循环；Long-Horizon State & Context 使用 Native Persistent Session + External Persistent State，并通过 Bootstrap / Delta Context Injection 保持连续性；Evidence-driven Investigation 让 Savepoint 改变 Direction 与 Portfolio；Context Isolation & Verification 用 Fresh Re-Survey 和 Fresh Reviewer 分别隔离搜索路径依赖和正式结论偏差。</p><p><strong>最后讲结果与边界：</strong>项目在 9 个真实系统中产出 21 个安全发现，其中 11 个获厂商确认修复，获得 1 个 CVE 和 3 个 CNVD。这说明系统具有真实产出，但不能单独证明普遍优于强原生 Coding Agent。</p>`,['为什么 Runtime 叫 Thin？','Bootstrap 与 Delta Injection 分别是什么？','Fresh Re-Survey 与 Fresh Reviewer 差在哪？'],'默认按“相关工作→研究空缺→四项机制→真实结果→证据边界”回答；不把 Coding Agent 运行失败当作唯一研究动机。','简单',['最新包装','Thin Runtime','项目介绍','60秒'], '必背'),
  q('adaptivevuls','问题定义','什么是“调查状态—下一步行动错配”？','当前证据状态已经变化，但 Agent 仍沿用不适合的行动策略，导致过早终止、无效深挖或结论膨胀。',`<p>开放式调查没有预定义任务终点，行动是否正确依赖当前 Case 的科学状态。例如机制 M 已复现，但攻击者控制 C 与边界 B 仍未知，此时继续重复同类 PoC 就是证据膨胀；首次复现失败若源于环境缺失，却直接关闭 Case，则是失败归因与行动不匹配。</p><ul><li><strong>过早停止：</strong>只有局部 Observation 就放弃可证伪方向。</li><li><strong>单点深陷：</strong>低信息增益动作不断重复。</li><li><strong>失败即放弃：</strong>未区分触发形状、环境问题与真阴性。</li><li><strong>结论膨胀：</strong>Mechanism reproduced 被写成 Boundary/Impact 已证明。</li></ul><p>AV 把“该做什么”变为 OES、Obligation 和 Portfolio 状态的函数，而非仅依赖当前聊天上下文。</p>`,['如何度量错配？','举一个真实失败轨迹。','怎样证明不是模型能力不足？'],'可以用基线轨迹中四类失败模式引出方法设计。','困难',['失败模式','高压','方法论'],'高压'),
  q('adaptivevuls','科学对象','Observation、Frontier、Case、Evidence 分别是什么，如何关联？','Observation 是有来源的局部事实；Frontier 是高召回安全关系问题；Case 是可证伪命题；Evidence 是 Artifact 对指定 Case Claim 的有方向更新。',`<p><strong>Observation</strong> 描述“材料显示了什么”，必须有 provenance；<strong>Frontier</strong> 把若干 Observation 组织成尚模糊的开放问题，不要求完整攻击模型；<strong>Case</strong> 需要 Grounded、Security-Relevant、Falsifiable、Alternative-Aware、Scoped，是可长期修订的调查对象；<strong>Artifact</strong> 是源码、脚本、trace 等原始材料，只有经过审查并针对某项 Claim 产生支持或反驳作用时，才成为 <strong>Evidence</strong>。</p><p>典型链路：源码事实 → Observation → “这里是否跨越权限边界”的 Frontier → 形成带竞争解释的 Case → 获取 Artifact → Reviewer 限定证据覆盖范围 → 更新 OES。</p>`,['每个 grep 结果都要持久化吗？','Frontier 完成是否代表攻击面覆盖？','Case admission 的最低门槛是什么？'],'这是讲清 AV 数据模型的关键题。','困难',['OES','科学对象','深挖'],'深挖'),
  q('adaptivevuls','证据模型','为什么 Mechanism reproduced 不等于 Vulnerability Report？','机制发生只支持 M；报告还需要攻击者控制、目标安全边界、增量影响、责任归属与适用范围等证据。',`<p>AV 把安全结论拆成 C/M/B/I/Own/S：</p><ul><li><strong>C Control：</strong>攻击者能控制什么、入口是否可达；</li><li><strong>M Mechanism：</strong>目标行为是否发生及条件；</li><li><strong>B Boundary：</strong>目标拥有或承诺的安全属性是否被破坏；</li><li><strong>I Impact：</strong>增加了什么攻击能力或安全损失；</li><li><strong>Own Ownership：</strong>责任属于目标、调用者、部署还是依赖；</li><li><strong>S Scope：</strong>版本、配置、入口和环境。</li></ul><p>一个 crash 或 PoC 常只覆盖 M；如果输入本就来自可信管理员，C 不成立；如果接口明确允许该行为，B 不成立；如果攻击者没有新增能力，I 被夸大。Report Gate 应检查必要 Claim 和 Scope，而不是检查“是否有 PoC”。</p>`,['Crash 与可利用漏洞是什么关系？','如何表示 refuting evidence？','哪个 Claim 最容易被忽略？'],'可联系厂商确认前的边界验证与负面结论。','困难',['CMBIOwnS','证据门','必背'],'必背'),
  q('adaptivevuls','OES','Operational Evidence State（OES）是什么？','OES 是 Case 当前可执行的科学状态，由 Claim 状态、竞争解释和主动证据义务组成。',`<p>形式上可表达为 <code>OES_t(c)=&lt;Q_t(c), Alt_t(c), Obligations_t(c)&gt;</code>。Q 保存 C/M/B/I/Own/S 的状态、范围、支持/反驳 Artifact 与 residual unknown；Alt 保存支持性解释、最强替代漏洞解释和最强非漏洞解释；Obligations 指定下一步必须区分什么。</p><p>OES 的价值不是“多几个字段”，而是成为控制面输入：Reviewer 只允许证据更新其实际覆盖的 Claim；Runtime 根据未解决义务、信息增益与 Portfolio 冲突重新选行动。它比自然语言总结更可审计，也比固定状态机更能容纳 Case 演化。</p>`,['OES 和普通任务状态有什么区别？','谁能更新 OES？','OES 太重会不会影响效率？'],'项目答辩中建议画三元组与闭环。','困难',['OES','状态管理','高压'],'高压'),
  q('adaptivevuls','Case 生命周期','什么时候做 Local OES Update、Case Revision 或 Branch？','同一命题内证据变化做局部更新；核心攻击者/边界/根因/责任等实质改变做 Revision；出现可独立验证的兄弟命题时 Branch。',`<p>三者解决“保持连续性”与“避免偷换命题”的冲突。</p><ul><li><strong>Local Update：</strong>同一安全命题下 Claim 状态或 Scope 被补充，例如 M 从 unknown 到 supported。</li><li><strong>Revision：</strong>仍是同一调查脉络，但 Frame 的实质内容改变，例如根因从反序列化改为调用方权限检查缺失；保留 Case ID，增加 R1→R2。</li><li><strong>Branch：</strong>新证据同时支持另一个可独立证伪、可能有不同处置的命题，生成 sibling Case/Frontier，避免一个 Case 无限吸收所有问题。</li></ul><p>判断关键不是文本相似度，而是证据义务、责任和最终处置是否可独立。</p>`,['Revision 会不会污染历史结论？','Case ID 为什么要稳定？','如何处理合并？'],'AV 强调 Case 是长期对象而不是一次 Worker 调用。','困难',['Case','Revision','Branch'],'深挖'),
  q('adaptivevuls','角色设计','Case Investigator 与 Fresh Reviewer 为什么要分开？','Investigator 需要局部连续记忆提高调查效率；Reviewer 需要新鲜上下文限制确认偏差和 Claim 膨胀。',`<p>Investigator 在 goal-scoped sticky session 中保留构建命令、失败实验、仓库导航与临时假设，适合连续获取证据。但同一上下文也会形成路径依赖：模型容易为自己之前的假设辩护。</p><p>Fresh Reviewer 不继承未经审查的会话叙事，只读取 Canonical State、Artifact 和明确的 Review Package，判断“这份材料实际证明什么”，提出 Reviewed Delta、Revision、Branch 或有界处置。Runtime 再校验合法迁移并原子提交。</p><p>分离的是<strong>取证与裁决的认知角色</strong>，不是简单为了并行或“多 Agent 投票”。</p>`,['Fresh 会丢失必要上下文吗？','Reviewer 是否能直接写 Canonical State？','为什么不用多数投票？'],'与 Session/Resume 设计直接关联。','困难',['Reviewer','Session','架构'],'深挖'),
  q('adaptivevuls','控制策略','State → Action Control 如何避免固定流水线？','Runtime 从 Canonical State 构建 Eligible Action Board，Fresh Controller 只在合法候选中给出基于当前科学状态的下一步选择；它不使用固定评分算法，也不分配时间或 Token。',`<p>Action Board 至少包含 <code>refresh_discovery</code>、<code>explore_frontier</code>、<code>form_case</code>、<code>investigate_case</code> 和 <code>acquire_deciding_artifact</code>。Evidence Checkpoint 后的 Fresh Review 是协议延续，不是 Controller 可跳过的候选任务。</p><p>每次 Reviewed Delta 提交后，Runtime 更新 OES、Revision、Obligation、Negative Knowledge 和 derived objects，再重建 Board；Fresh Controller 读取新状态做下一次选择。AV 不规定信息增益数值函数、固定优先级或预算打分，只要求选择来自 Board 并给出科学理由。</p>`,['Board 为空是否表示审计完成？','Active Obligation 是否总优先于 Frontier？','为什么 Controller 每次 Fresh？'],'V1.43 中这条链用于记录“证据更新→状态变化→下一行动”，但面试开场先使用简历中的“证据缺口驱动下一步”表达。','困难',['Action Board','Portfolio','V1.43'],'高压'),
  q('adaptivevuls','终态','AV 中 Report、Refuted、Expected Behavior、Caller Misuse、Park 有什么区别？','它们是证据边界不同的有界处置：报告确认目标漏洞；其余分别表示命题被反驳、行为符合契约、责任在调用方，或当前缺少高价值行动但未作科学否定。',`<p>负面结论也必须有门槛。<strong>Refuted</strong> 需要决定性证据反驳核心命题；<strong>Expected Behavior</strong> 需要可靠契约或设计依据；<strong>Caller Misuse</strong> 需要 Ownership 证据说明目标已履责；<strong>Park</strong> 只是 operational disposition，表示当前受阻、价值低或无可行动作，不能被统计成“非漏洞”。</p><p><strong>Report</strong> 则要求 Claim coverage、反例处理、Scope 和 Ownership 达到报告门。区分 Scientific Disposition 与 Operational State，能防止“暂时做不下去”被误写为真阴性。</p>`,['负面闭合为何也需要 Reviewer？','Park 何时重开？','Expected Behavior 会不会仍有安全风险？'],'适合回答“如何减少误报和漏报”。','困难',['Disposition','Report Gate','负面闭合'],'深挖'),
  q('adaptivevuls','实验','如何设计实验验证 AV，而不是只展示几个成功案例？','用公平基线、预算匹配、多次运行和组件消融，分别评估目标认知、证据复核、错误关闭、正确结论与成本，而不是只比较最终漏洞数量。',`<p>控制目标版本、模型、Runner、工具权限和统一外部运行边界；至少比较 Native Coding Agent、Skill/Batch-and-Confirm 与 Full AV，并使用多随机种子保存完整轨迹。</p><ul><li><strong>方向质量：</strong>目标认知和漏洞知识是否形成更有价值、可验证的调查方向。</li><li><strong>证据约束：</strong>Fresh Review 是否减少证据不足升级、错误 Scope/Impact/Ownership 和错误关闭。</li><li><strong>行动改变：</strong>新证据是否真实改变漏洞假设、证据缺口和下一步，而不只是多写状态字段。</li><li><strong>成本与覆盖：</strong>在相同 Token、墙钟或调用资源下比较正确结果、遗漏、重复行动和单位成功成本。</li></ul><p>9 个系统、21 个发现、11 个厂商确认、1 个 CVE 和 3 个 CNVD 是真实外部产出，但不是方法相对基线的因果证明。</p>`,['如何证明 Fresh Review 不是多花一次模型预算？','没有完整 Ground Truth 怎么办？','Skill 和 Full AV 怎样做消融？'],'以最新简历的真实成果作为外部信号，以 V1.43 的公平前瞻实验回答方法收益。','困难',['实验设计','对照实验','V1.43'],'高压'),

  q('harness','定位','Workflow-Harness 的本质是什么？与 AdaptiveVuls 的边界在哪里？','Harness 是编排现成 Coding Agent 的通用运行框架；AV 是在它之上定义目标认知、调查方向、证据缺口和结论收口方式的安全领域方法。',`<p>Workflow-Harness 不重新实现模型调用、tool loop 或代码编辑能力，而是通过统一 <code>agent()</code> 接口与 Runner Adapter 调用 Codex、Claude Code、OpenCode 等完整 Agent。按照最新简历，它负责代码化 Workflow、Fresh/Resume 会话、隔离 Workspace、显式上下文、运行产物、预算、异常恢复和审计轨迹。</p><p>AdaptiveVuls 则回答安全调查问题：怎样理解目标架构和攻击面、形成调查方向与漏洞候选、识别当前证据缺口，以及怎样让 Fresh Reviewer 把候选收口为报告、否定、收窄或暂存。Harness 的预算是运行与实验控制；V1.43 不把剩余时间、Token 或轮数写进 Investigator 的科学 Packet。</p>`,['Harness 能否用于非安全任务？','AV 是否绑定某个 Runner？','预算管理和方法内部无预算是否矛盾？'],'先按最新简历区分“通用运行底座”和“安全调查方法”，再在追问时解释 V1.43 的科学状态。','中等',['Harness','最新简历','边界'],'必背'),
  q('harness','Adapter','统一 agent() 与 Runner Adapter 应如何设计？','agent() 暴露稳定领域参数，Adapter 把它翻译成不同 CLI/SDK 的启动、恢复、流式事件、取消与结果协议。',`<p>上层接口至少接收 runner、workspace、prompt/input、session policy、timeout、budget 与 artifact paths，并返回统一的 run id、status、events、session handle、usage 和 outputs。</p><p>Adapter 负责命令行参数、环境变量、stdout/stderr 解析、退出码映射、原生 session id 捕获、resume 命令、取消信号与版本能力差异。能力不一致时不要假装完全统一，应通过 capability descriptor 显式暴露，例如是否支持 resume、structured output、MCP、token usage。</p><p>设计重点是：稳定契约、错误分类、幂等 run identity、原始日志不丢失，以及 Adapter 不承载 AV 的安全判定逻辑。</p>`,['CLI 输出格式变化怎么办？','Adapter 的测试策略？','如何支持新 Runner？'],'可结合 Python subprocess、流式 stdout 与 Schema 校验。','困难',['Adapter','agent接口','工程'],'深挖'),
  q('harness','会话','Manifest、显式状态、Session 和 Resume 是什么关系？','Manifest/结构化文件是跨运行的科学与控制状态；Session/Resume 是 Runner 内的隐式工作记忆，两者互补但前者权威。',`<p>Manifest 记录 run 配置、任务输入、产物引用、状态版本和审计信息；阶段提示与结构化账本保存可校验的显式记忆。Runner 原生 Session 保留对话上下文、仓库导航、失败命令等隐式记忆，Resume 提高连续任务效率。</p><p>但 Session 不能成为唯一真值：它可能丢失、截断、不可跨 Runner，且包含未经审查的推断。恢复时应先从 Manifest/Canonical State 重建权威上下文，再选择性 Resume；跨 Runner 迁移时通过结构化 handoff，而不是复制整段聊天记录。</p>`,['Session 丢失如何恢复？','何时必须 Fresh Session？','上下文压缩放在哪里？'],'与 AV 的“Session Memory ≠ Canonical State”一致。','困难',['Manifest','Session','Resume'],'必背'),
  q('harness','动态工作流','Dynamic Workflow 到底动态在哪里？','代码化骨架稳定，但分支、循环、Agent/Session 选择和终止由运行状态与结构化产物在运行时决定。',`<p>“动态”不是让 LLM 任意生成下一步，更不是把所有流程硬编码成固定 DAG。Workflow 可以声明条件、循环、并行、回退和 session policy，运行时读取结构化结果决定：继续同一 Investigator、启用 Fresh Reviewer、切换 Runner、分支新 Case、重试环境失败或停止。</p><p>需要区分两层动态性：Harness 提供<strong>通用控制流动态</strong>；AV 定义<strong>证据条件驱动的领域决策</strong>。这样既保留可审计性，又避免自然语言 Agent 自己既执行又裁决。</p>`,['与 LangGraph 有何区别？','为何不用 YAML DAG？','动态决策如何可复现？'],'建议给一个 if/loop + Reviewed Delta 的具体流程。','困难',['Dynamic Workflow','控制流','高压'],'高压'),
  q('harness','可靠性','如何区分 Agent Failure、Runner Failure 与 Environment Failure？','按责任域分类：Agent 产出不满足任务契约；Runner 启动、协议或会话层失败；环境则是构建、依赖、权限和目标基础设施问题。',`<p><strong>Agent Failure</strong> 如未按 Schema 输出、无证据结论、重复低价值动作；可以重提示、Fresh Review 或改变计划。<strong>Runner Failure</strong> 如 CLI 崩溃、session id 丢失、流解析失败；适合 Adapter 级重试、降级或切换实现。<strong>Environment Failure</strong> 如依赖下载失败、编译器缺失、端口冲突；应修复环境、记录可复现条件，不应当作漏洞假设被反驳。</p><p>错误必须携带 stage、retryable、owner、raw cause 和 artifacts。若不分类，统一 retry 会浪费预算，统一 abort 又会导致“复现失败即放弃”。</p>`,['超时属于哪一类？','如何决定可重试？','失败分类会不会重叠？'],'项目中的失败归因机制可落到这套工程分类。','中等',['错误分类','可靠性','重试'],'深挖'),
  q('harness','并发隔离','多 Agent 并发时如何管理 Workspace 与结果合并？','每个写任务使用独立 worktree/目录和明确租约，读任务可共享只读快照；结果以 Artifact/Delta 合并，不直接竞争写 Canonical State。',`<p>并发 Worker 共享一个仓库会产生文件覆盖、Git index 冲突、端口/缓存冲突和难以归因的输出。调度器为 run 分配唯一 workspace、环境变量和 artifact directory，可用 Git Worktree 保持共同基线并隔离改动。</p><p>Canonical State 采用单写者或 compare-and-swap 版本提交；Worker 只提交提案和引用。合并前校验 base revision、Schema、artifact hash 与冲突。还要管理资源配额、文件锁、任务租约和心跳，Worker 崩溃后租约到期可恢复。</p>`,['只读分析也要 worktree 吗？','如何处理共享构建缓存？','两个 Case 修改同一文件怎么办？'],'对应简历中的 Workspace、Git Worktree 与并行任务。','困难',['并发','Workspace','Git Worktree'],'深挖'),

  q('security','Web/API','认证和授权有什么区别？IDOR/BOLA 为什么属于授权问题？','认证确认“你是谁”，授权判断“你能对哪个资源做什么”；IDOR/BOLA 是服务端未校验主体与对象/动作关系。',`<p>仅验证 Token 合法只能完成认证。安全授权应在服务端基于 subject、action、resource、tenant 与上下文执行策略。IDOR/BOLA 常发生在接口直接使用用户可控对象 ID 查询/修改资源，却只检查“已登录”。</p><p>测试时不要只换数字 ID：还要覆盖横向越权、纵向越权、批量接口、嵌套资源、导出接口和异步任务。修复要集中式 policy enforcement、默认拒绝、查询中绑定 tenant/owner，并对高风险动作做审计；UUID 只能降低枚举性，不替代授权。</p>`,['RBAC 与 ABAC 的区别？','前端隐藏按钮有用吗？','GraphQL 中如何防 BOLA？'],'可用 C→M→B→I 链路分析是否形成目标责任。','中等',['授权','IDOR','BOLA'],'必背'),
  q('security','Web/API','SQL 注入的根因、验证方式和正确修复是什么？','不可信数据被解释为 SQL 语法；用参数化查询分离代码与数据，并限制账户权限，不能只靠黑名单转义。',`<p>Source 是请求参数、Header、消息或持久化的二次污染数据；Sink 是字符串拼接后进入数据库执行。验证应优先构造最小、无破坏性差异：布尔条件、时间差或错误信息，并确认实际查询路径和数据库类型。</p><p>参数化查询适用于值，但表名、排序字段等结构位置需白名单映射。存储过程和 ORM 并非天然安全，原生拼接仍会注入。纵深措施包括最小权限、错误隐藏、WAF 监控，但不能代替代码修复。修复后做正反用例和相邻调用点回归。</p>`,['预编译为什么有效？','LIKE 与 IN 如何参数化？','二阶注入是什么？'],'用 Source-Sink-Sanitizer-Constraint 框架回答。','中等',['SQL注入','参数化','Source Sink'],'必背'),
  q('security','Web/API','SSRF 应如何分析？只禁止 127.0.0.1 是否足够？','分析攻击者可控 URL 到服务端网络请求的完整解析与重定向链；单点字符串黑名单无法覆盖 DNS、IPv6、重定向和编码变体。',`<p>SSRF 的价值来自服务端网络身份与可达性。检查 scheme、userinfo、host、port、DNS 解析、代理、重定向、协议走私以及响应是否回显。风险包括访问云元数据、内网管理面、Unix/其他协议、盲 SSRF 探测。</p><p>优先使用目标 allowlist；解析后校验规范化 IP，拒绝 loopback、link-local、private、保留地址，并在每次重定向和 DNS 解析后重验，防 DNS rebinding。网络层 egress policy 与元数据服务鉴权是纵深防御。注意 URL parser 与 HTTP client 的解析差异。</p>`,['DNS rebinding 怎么发生？','盲 SSRF 如何验证？','302 重定向为何危险？'],'适合展示安全边界和默认配置可达性分析。','困难',['SSRF','URL解析','网络边界'],'深挖'),
  q('security','Web/API','反序列化漏洞成立需要哪些条件？','攻击者能控制序列化数据、目标会实例化或触发危险语义、存在可达 gadget/回调，并跨越了目标承诺的信任边界。',`<p>不能看到 <code>pickle.loads</code> 就直接报告。先确认数据来源和完整性保护；再确认反序列化格式是否允许类型/方法执行；追踪 gadget chain、魔术方法或状态恢复回调；最后分析运行权限和攻击者新增能力。</p><p>修复优先改用数据型格式与显式 Schema，禁用多态类型，做签名认证和版本约束，并减少进程权限。签名只能防篡改，若签名密钥或合法生产端受攻击仍需考虑。验证应使用安全 PoC 证明受控副作用，而非无必要执行危险命令。</p>`,['JSON 是否绝对安全？','签名后的 pickle 安全吗？','如何发现 gadget chain？'],'可直接套用 AV 的 C/M/B/I/Own/S 防止机制膨胀。','困难',['反序列化','gadget','边界'],'高压'),
  q('security','Web/API','文件上传漏洞应该从哪些层面验证？','同时验证内容、扩展名、MIME、解析器、存储位置、访问权限与后续处理，核心是上传数据是否进入可执行或高权限解析边界。',`<p>攻击面不只是“上传 WebShell”。常见路径包括双扩展和大小写绕过、Content-Type 信任、图像/压缩包解析漏洞、路径穿越覆盖文件、SVG XSS、压缩炸弹、公开对象存储泄露以及异步处理命令注入。</p><p>修复采用随机服务端文件名、目录隔离、不可执行挂载、内容嗅探/重编码、尺寸和解压限额、鉴权下载、恶意文件扫描。校验应基于解析后的真实类型，且上传服务与业务处理进程最小权限。</p>`,['为什么只改文件名不够？','压缩包如何安全解压？','预签名上传如何授权？'],'可联系路径遍历和异步任务边界。','中等',['文件上传','路径遍历','解析器'],'常规'),
  q('security','内存安全','Use-After-Free 的成因、表现与验证方法是什么？','对象释放后仍存在悬空引用并被读写或调用；验证需证明生命周期错误、可控重用和实际安全影响，而不只是一条 crash。',`<p>UAF 常源于别名、异步回调、容器失效、引用计数竞争或错误所有权。释放后 allocator 可能把同一块内存分配给攻击者可影响的新对象，旧指针访问就可能造成数据泄露、任意写或控制流劫持。</p><p>ASan 可通过 redzone/quarantine 捕获释放后访问并给出分配、释放和访问栈；但复现依赖分配布局。修复应明确所有权，用 RAII/智能指针、取消回调、同步生命周期或 generation handle，不能简单置空一个别名。评估可利用性还需看可控性、稳定性、缓解措施和进程权限。</p>`,['shared_ptr 能否彻底避免 UAF？','并发 UAF 怎么定位？','ASan 为什么改变堆布局？'],'回答 Crash≠Vulnerability 的典型题。','困难',['UAF','ASan','生命周期'],'必背'),
  q('security','内存安全','ASan、MSan、UBSan 分别检测什么，有哪些局限？','ASan 查越界和 UAF，MSan 查未初始化读取，UBSan 查多类未定义行为；它们是动态检测器，需要触发路径且会引入开销和布局变化。',`<p>ASan 用 shadow memory、redzone 和 quarantine；MSan 跟踪字节的初始化/传播，通常要求依赖也被插桩；UBSan 在整数溢出、错位访问、非法 shift、vptr 等点插检查。它们能提供高质量诊断，却不能证明未触发路径安全，也不直接证明可利用性。</p><p>生产中还可了解 HWASan、CFI 与 fuzzing 结合。测试时保存编译选项、符号化环境和最小输入；修复后既跑原 PoC，也扩大回归语料，避免仅压掉 crash。</p>`,['为什么 MSan 最难部署？','ASan 有假阴性吗？','Sanitizer 能否一起开？'],'属于“动态验证、漏洞复现与 PoC 构造”的扩展知识；最新简历没有单独列出具体 Sanitizer 名称。','中等',['Sanitizer','ASan','MSan','UBSan'],'必背'),
  q('security','漏洞分析','如何系统分析一条 Source→Sink 数据流？','确定攻击者可控 Source、危险 Sink、传播路径、转换与 Sanitizer，并逐项验证约束、可达性、边界和影响。',`<p>先给 Source 标注主体、入口、编码和可控粒度；再确认 Sink 的危险语义。沿调用链记录数据传播、别名、跨过程/异步/持久化路径。对每个 Sanitizer 检查是否与最终解释器匹配、顺序是否正确、是否存在规范化差异与旁路。</p><p>随后验证 path constraint、认证授权、默认配置和错误路径。最小 PoC 只证明必要机制，再补边界、影响与 Scope。修复后做 differential test：旧版本触发、修复版本阻断，同时正常输入不回归。</p>`,['静态分析为何误报高？','隐式流怎么处理？','Source 可控性如何分级？'],'可联系 CodeQL/Joern、AST 与数据流分析技能。','中等',['数据流','Source Sink','静态分析'],'必背'),
  q('security','竞态','TOCTOU 是什么？常见修复思路是什么？','检查与使用之间共享状态可被改变，导致使用时假设失效；修复应让检查与操作原子化或基于不可变句柄。',`<p>经典例子是先检查路径权限再打开文件，攻击者在间隙替换符号链接。业务系统也有余额检查后并发扣款、库存超卖、一次性 Token 并发复用。</p><p>文件系统中使用 <code>openat</code>、<code>O_NOFOLLOW</code>、目录 fd 和打开后 <code>fstat</code>，避免按字符串路径二次解析。数据库中使用事务、行锁、唯一约束、原子条件更新或 CAS。分布式系统需要幂等键与权威存储约束；仅在应用层“先查再写”通常不够。</p>`,['悲观锁和乐观锁怎么选？','原子 rename 有什么保证？','如何稳定复现竞态？'],'可联系并发 Worker 与任务租约。','困难',['TOCTOU','竞态','原子性'],'深挖'),

  q('agent','基础概念','LLM、Agent、Coding Agent 与 Harness 有什么区别？','LLM 生成/推理；Agent 围绕目标进行感知、决策和工具行动；Coding Agent 专注代码环境；Harness 在 Agent 外部负责编排、状态、资源与审计。',`<p>LLM 本身通常是一次输入输出映射；Agent 加入 tool loop、观察和停止策略；Coding Agent 进一步具备仓库检索、编辑、终端、测试和 diff 能力。Harness 不等于 Agent：它可以调用多个完整 Agent，决定 session、workspace、预算、错误恢复和跨步骤数据流。</p><p>边界并非绝对，某些 SDK 也带 session 或 workflow。但面试时要按“谁拥有模型调用循环、谁拥有跨调用控制状态”说明架构，而不是只背名词。</p>`,['MCP 属于哪一层？','Agent 和 Workflow 谁做规划？','为什么不直接调模型 API？'],'与个人“安全 × Agent 工程”定位直接相关。','简单',['LLM','Agent','Harness'],'必背'),
  q('agent','范式','ReAct、Planner-Executor 与 Supervisor-Worker 如何比较？','ReAct 逐步推理行动；Planner-Executor 分离高层计划与执行；Supervisor-Worker 用协调者分派多个专门执行单元，各自在适应性、成本和一致性上取舍。',`<p>ReAct 对局部交互灵活，但长任务容易漂移。Planner-Executor 让计划可见、可重规划，适合长链路，但初始计划可能过早固化。Supervisor-Worker 支持专业化和并行，却引入上下文交接、重复工作和裁决问题。</p><p>选型依据任务耦合度、可验证中间产物、并行收益和错误成本。AdaptiveVuls 不是简单套用某一范式：它把 Case Investigation 保持 sticky，把 Review 设为 fresh，并让 Canonical State/Reviewed Delta 限制协调权。</p>`,['什么时候多 Agent 反而更差？','如何合并 Worker 结果？','Planner 失败如何恢复？'],'用项目架构体现不是只会背框架。','中等',['ReAct','Planner','多Agent'],'常规'),
  q('agent','RAG','RAG、Fine-tuning、Prompt、Skill 和 Memory 如何区分与选型？','Prompt 定义当前指令；RAG 提供外部事实；微调改变模型参数行为；Skill 封装可复用流程知识；Memory 保存跨步骤/会话状态。',`<p>知识频繁变化且需溯源，优先 RAG；希望稳定改变风格、格式或领域行为，且有高质量数据时考虑 SFT；即时任务约束用 Prompt；重复的工具步骤、决策规则和资源可封装 Skill；任务状态和用户偏好进入 Memory。</p><p>这些可以组合，但要避免把未经验证的模型总结写入长期记忆。RAG 仍需处理切分、召回、重排、引用和 prompt injection；微调不会自动获得实时事实；长 Prompt 也不等于可靠 Workflow。</p>`,['RAG 召回率怎么评估？','Skill 与 Tool 有何区别？','长期记忆如何防污染？'],'可联系显式/隐式记忆和 AV Canonical State。','中等',['RAG','微调','Memory','Skill'],'必背'),
  q('agent','上下文','上下文窗口、Token、KV Cache 与上下文压缩是什么关系？','上下文占用 Token 并生成注意力 KV；KV Cache 复用历史计算但消耗显存，压缩通过筛选/总结减少上下文成本，同时有信息损失风险。',`<p>自回归推理中，历史 Token 的 key/value 被缓存，生成下一个 Token 无需重算全部前缀，但 attention 读取成本和 KV 显存随序列增长。Prefix caching 可跨请求复用相同前缀，和语义 Memory 不是一回事。</p><p>Agent 长任务中应分层：原始 Artifact 保存在外部；Canonical State 保存权威结构化摘要；工作 Session 保留局部细节；接近窗口上限时做目标相关压缩。压缩要保留来源引用、未决义务和失败实验，避免只保留“结论”导致证据漂移。</p>`,['KV Cache 为什么影响并发？','压缩后如何验证信息没丢？','长上下文是否能替代 RAG？'],'可解释 Session 为什么不能作为唯一真值。','困难',['Token','KV Cache','上下文'],'深挖'),
  q('agent','推理参数','Temperature 与 Top-p 分别如何影响生成？推理任务是不是越低越好？','Temperature 缩放 logits 控制分布尖锐度；Top-p 从累计概率集合采样。低随机性提高一致性，但探索性任务仍需多样性与外部验证。',`<p>Temperature 接近 0 时更偏向高概率 Token；Top-p 截断长尾。二者通常不要同时激进调节。对于结构化输出、代码补丁和证据裁决，更看重稳定性，可低温并做 Schema 校验；对于攻击面发散，可通过多个候选、不同 seed 或角色提示增加多样性。</p><p>推理模型的“思考强度”、采样参数与最终可靠性不是线性关系。关键结论必须由工具、测试和证据门验证，不能把确定性生成误当成正确性。</p>`,['Temperature=0 是否完全确定？','如何兼顾探索与复现？','结构化输出失败怎么处理？'],'联系高召回探索与约束提升。','简单',['Temperature','Top-p','采样'],'常规'),
  q('agent','可靠性','Agent 调用中的 Timeout、Retry、Backoff、Jitter、Circuit Breaker 如何配合？','超时限制单次等待；重试处理瞬态错误；指数退避加随机抖动避免同步风暴；熔断器在持续失败时快速失败并等待恢复。',`<p>先按错误语义判定 retryable：429、部分 5xx、连接重置常可重试；认证错误、无效请求和确定性 Schema 错误不应盲重试。每次调用设置 connect/read/overall deadline，并把剩余全局预算向下传递。</p><p>重试需幂等：为任务设置 idempotency key，避免 Agent 或外部工具重复产生副作用。退避可用 capped exponential backoff + full jitter。熔断器 closed→open→half-open，保护 Provider 和本地 Worker 池；同时保留降级模型、排队和可观测告警。</p>`,['流式输出中断后如何恢复？','超时后子进程一定退出了吗？','最大重试次数如何定？'],'Workflow-Harness 的 Runner 可靠性核心题。','中等',['重试','退避','熔断','幂等'],'必背'),
  q('agent','评测','如何评测一个 Coding Agent 工作流？','分解为任务结果、过程质量、资源成本和鲁棒性，使用可重复环境、多次运行、轨迹审计与人工/自动联合判定。',`<p>结果层看测试通过、真实缺陷闭合或 patch 正确性；过程层看工具调用有效率、回退质量、证据引用、无效循环；资源层看 Token、时延、工具和人工成本；鲁棒性看环境扰动、Runner 失败与随机种子方差。</p><p>评测要固定仓库 commit、依赖镜像和隐藏测试，防数据泄漏；避免只让另一个 LLM 主观打分。安全任务 ground truth 不完备时，可用后验专家审查、厂商确认和可复现证据组合，但需报告选择偏差与置信区间。</p>`,['pass@k 与 pass^k 的区别？','LLM-as-judge 有什么偏差？','如何评估开放式任务召回率？'],'AV 应重点验证 H1–H4、错误提升与 Evidence→State→Action 的轨迹因果，而不只统计发现数。','困难',['Agent评测','指标','实验'],'高压'),

  q('backend','数据库','为什么数据库索引常用 B+ 树，而不是红黑树或哈希？','B+ 树扇出大、树高低、节点适配页 I/O，叶子有序链表支持范围查询；哈希不支持范围，二叉树层高导致更多随机 I/O。',`<p>数据库按页读写，一个 B+ 节点可容纳大量 key 和 child pointer，百万级数据通常只需少量层级。非叶节点只存索引键，提高扇出；数据/主键集中在叶子并有序链接，等值、范围、排序和前缀扫描都高效。</p><p>红黑树每节点分支少且指针离散，磁盘/缓存局部性差；哈希适合等值却难支持范围、排序与最左前缀。实际性能还受页分裂、填充因子、选择性和 Buffer Pool 影响。</p>`,['B 树与 B+ 树区别？','页分裂怎么发生？','低选择性列为何可能不走索引？'],'后端基础高频题。','中等',['B+树','索引','MySQL'],'必背'),
  q('backend','数据库','聚簇索引、二级索引、回表和覆盖索引是什么？','InnoDB 聚簇索引叶子存整行；二级索引叶子存索引列和主键；需再查主键取其他列叫回表，查询列全在索引中则覆盖。',`<p>表数据按主键 B+ 树组织，因此主键应尽量短、稳定且递增，过长会放大所有二级索引。二级索引命中后若查询列不完整，拿到主键再访问聚簇索引，产生随机 I/O；覆盖索引可避免回表。</p><p>联合索引顺序要结合等值、范围、排序与选择性设计。最左前缀来自 B+ 树键的字典序组织；遇范围条件后，后续列通常不能继续用于定位，但可能用于 Index Condition Pushdown 或覆盖。</p>`,['为什么不建议随机 UUID 主键？','索引下推是什么？','count(*) 是否回表？'],'SQL 优化需要能结合 EXPLAIN 回答。','中等',['聚簇索引','覆盖索引','回表'],'必背'),
  q('backend','数据库','ACID、隔离级别和 MVCC 如何关联？','事务用原子性、一致性、隔离性、持久性保证状态转换；MVCC 通过版本和快照减少读写冲突，不同隔离级别决定可见性规则。',`<p>MySQL InnoDB 通过 undo log 构造历史版本，ReadView 判断可见性；redo log/WAL 支撑崩溃恢复。Read Committed 常每条语句创建快照，Repeatable Read 通常事务级快照，因此后者避免不可重复读。</p><p>MVCC 主要服务快照读；当前读、更新和约束仍需锁。InnoDB RR 通过 next-key lock 处理范围当前读的幻影，但普通快照读语义不同。Serializable 提供更强隔离但并发代价高。应用还需正确处理写偏差、死锁重试和外部副作用。</p>`,['幻读和不可重复读区别？','undo/redo/binlog 各做什么？','MVCC 能避免丢失更新吗？'],'面试不要只背四个英文单词。','困难',['ACID','MVCC','隔离级别'],'必背'),
  q('backend','数据库','数据库死锁是怎么产生和处理的？','事务以不同顺序持有并等待互斥资源形成环；数据库检测等待图并回滚一个事务，应用必须能重试。',`<p>典型是 T1 锁 A 等 B，T2 锁 B 等 A。范围更新、二级索引和 gap/next-key locks 会让实际锁集合比 SQL 表面更复杂。排查用死锁日志查看事务、锁模式、索引和 SQL。</p><p>预防：统一访问顺序、缩短事务、建立合适索引减少锁范围、分批更新、避免事务内慢网络调用。应用捕获 deadlock/serialization failure，使用有界退避重试并保证幂等。提高超时不能消除死锁。</p>`,['死锁与锁等待超时区别？','如何选择 victim？','单条 SQL 会死锁吗？'],'可联系任务调度中的资源锁顺序。','中等',['死锁','事务','锁'],'常规'),
  q('backend','Redis','Redis 为什么快？单线程是否意味着没有并发问题？','内存数据结构、事件循环与高效 I/O 降低开销；命令串行执行不代表多命令事务原子，也不消除客户端竞态和持久化/网络成本。',`<p>Redis 核心命令执行长期采用单线程事件循环，避免大量锁和上下文切换；内存访问、专用编码、epoll 和批量协议使常见操作快。新版本在网络 I/O、后台持久化等方面可有多线程。</p><p>“GET 后 SET”是两个原子命令但组合不是原子，会丢失更新。应使用原子命令、Lua、事务 WATCH 或业务侧版本。大 key、O(N) 命令、fork、AOF fsync、网络 RTT 都可能造成尾延迟。</p>`,['Redis 6 多线程做什么？','Pipeline 和事务区别？','为什么会有 big key 问题？'],'缓存系统基础高频。','中等',['Redis','事件循环','原子性'],'必背'),
  q('backend','缓存','缓存穿透、击穿、雪崩分别是什么，如何处理？','穿透是反复查不存在数据；击穿是热点 key 失效瞬间并发回源；雪崩是大量 key 同时失效或缓存整体故障。',`<p>穿透用参数校验、缓存空值、Bloom Filter；击穿用 singleflight/互斥重建、逻辑过期和热点预热；雪崩用 TTL 随机化、多级缓存、限流降级与高可用。三者都不能只靠“加锁”概括。</p><p>还要考虑缓存一致性：常用 cache-aside，写数据库后删除缓存；并发窗口可结合延迟双删、binlog/CDC 失效、版本号和短 TTL。强一致需求不应盲目依赖旁路缓存。</p>`,['为什么是删除而不是更新缓存？','Bloom Filter 会误判吗？','缓存重建失败怎么办？'],'系统设计常见连问。','中等',['缓存','穿透','击穿','雪崩'],'必背'),
  q('backend','分布式系统','如何设计可靠的分布式锁？','需要唯一 owner token、带 TTL 的原子获取、Lua 校验 owner 后释放，并用 fencing token 防止过期持有者继续写权威资源。',`<p>简单 <code>SET key value NX PX ttl</code> 可做基础互斥；释放必须比较 value 再删除，避免删掉新 owner 的锁。业务超过 TTL 需要受控续租，但进程暂停或网络分区会让旧 owner 在锁过期后仍执行。</p><p>因此关键写入要携带单调递增 fencing token，由数据库/资源端拒绝旧 token。明确锁服务故障和时钟假设；若要求强一致，应基于共识系统/数据库约束，而不是把 Redis 锁包装成绝对正确。</p>`,['Redlock 有哪些争议？','续租 watchdog 有何风险？','数据库唯一约束能否替代锁？'],'可联系 Harness 的任务租约与 Worker 恢复。','困难',['分布式锁','fencing token','租约'],'深挖'),
  q('backend','消息队列','至少一次、至多一次、恰好一次分别意味着什么？','至少一次可能重复，至多一次可能丢失；端到端“恰好一次”通常依赖幂等消费、事务边界和可重放日志，而不是 Broker 单项保证。',`<p>生产者发送、Broker 持久化、消费者处理和 ack 任何位置崩溃都影响语义。常用方案是至少一次投递 + 业务幂等键/唯一约束；数据库与消息的一致性可用 transactional outbox，先在同一事务写业务与 outbox，再异步发布。</p><p>消费者应先完成业务事务再 ack，失败重试并设置死信队列；记录处理状态和原始事件以便追踪。需要处理乱序、重复、毒消息和背压。</p>`,['为什么先 ack 会丢消息？','Outbox 如何清理？','Kafka exactly-once 覆盖什么边界？'],'与 Agent 任务队列和结果提交相关。','困难',['消息队列','幂等','Outbox'],'深挖'),

  q('os','进程线程','进程、线程、协程的区别与适用场景？','进程隔离资源，线程共享进程地址空间并由内核调度，协程在用户态协作调度，切换轻但阻塞调用会拖住执行线程。',`<p>CPU 密集型任务适合多进程或可真正并行的线程；高并发 I/O 可用线程池或 async 协程。Python CPython 的 GIL 限制同一进程中 Python 字节码并行，但 I/O 和释放 GIL 的 C 扩展可并行。</p><p>Harness 调 Runner 通常创建子进程以获得故障/环境隔离，主进程异步读取 stdout/stderr；并发 Agent 需同时考虑进程数、文件描述符、内存和 Provider 限流，不能只看协程数量。</p>`,['协程遇到阻塞函数怎么办？','进程间如何通信？','GIL 为什么存在？'],'直接联系 Runner 子进程。','中等',['进程','线程','协程','GIL'],'必背'),
  q('os','I/O','select、poll、epoll 有什么区别？','select 有 fd 上限且每次复制/线性扫描；poll 仍线性扫描；epoll 在内核维护关注集合并返回就绪事件，更适合大量连接。',`<p><code>epoll_ctl</code> 注册 fd，<code>epoll_wait</code> 获取就绪列表，避免每次传整个集合。水平触发只要可读就持续通知，边缘触发只在状态变化通知，ET 模式通常配合 non-blocking 并循环读到 EAGAIN，否则可能漏处理。</p><p>它提高等待就绪的扩展性，不代表业务处理自动变快。少量活跃 fd 时差异可能不大，还需防惊群、慢消费者和单回调耗时。</p>`,['LT 与 ET 如何选择？','epoll 是否 O(1)？','文件为什么不适用网络式 epoll？'],'流式读取多个 Agent stdout 的基础。','困难',['epoll','I/O多路复用','非阻塞'],'必背'),
  q('os','虚拟内存','虚拟内存、页表、TLB 与缺页异常如何协作？','虚拟地址经页表映射到物理页，TLB 缓存近期转换；映射不存在或权限不符触发缺页异常，由内核分配、换入或报错。',`<p>虚拟内存提供隔离、统一地址空间和按需分配。多级页表降低稀疏地址空间开销；TLB 避免每次访问都遍历页表。Minor fault 可能只是建立已在内存的映射，Major fault 需磁盘 I/O，延迟更大。</p><p>Copy-on-write 让 fork 初始共享物理页，写入时复制；这解释 Redis fork 持久化和大进程写放大的问题。页大小、Huge Page、NUMA 与访问局部性都会影响性能。</p>`,['缺页异常等于程序错误吗？','fork 为什么看似很快？','TLB miss 与 cache miss 区别？'],'后端/Redis 性能可联动回答。','困难',['虚拟内存','页表','TLB'],'常规'),
  q('os','子进程','如何可靠管理 Runner 子进程的超时、输出与取消？','启动独立进程组，非阻塞并发读取 stdout/stderr，超时时先优雅终止再强杀整个进程树，保留退出码和尾部日志。',`<p>若只 kill 父进程，编译器或工具子进程可能泄漏。POSIX 可新建 session/process group，收到取消后发 SIGTERM，等待 grace period，再 SIGKILL。必须持续 drain 两个管道，避免缓冲区写满导致死锁；大输出边流式落盘边保留有限内存窗口。</p><p>区分 timeout、user cancel、signal exit 和普通非零码；清理临时资源、释放任务租约，并让状态提交具备幂等性。总体 deadline 还应传播到子步骤，防每层都重新计满超时。</p>`,['SIGTERM 与 SIGKILL 区别？','怎样避免 PIPE deadlock？','Windows 下如何处理？'],'Workflow-Harness 最贴近系统编程的题。','困难',['subprocess','信号','超时'],'高压'),

  q('network','TCP','TCP 三次握手、四次挥手分别解决什么？为什么有 TIME_WAIT？','握手同步双方初始序列号并确认双向可达；TCP 全双工需双方分别关闭；主动关闭方 TIME_WAIT 防旧报文污染并能重发最后 ACK。',`<p>三次而非两次，是因为服务端也需确认客户端收到了服务端的 SYN/序列号。关闭时 FIN 表示本方向无更多数据，另一方向仍可发送，因此常为四次。TIME_WAIT 通常持续 2MSL，让迟到报文消失；若最后 ACK 丢失，主动方还能响应重传 FIN。</p><p>大量短连接可通过连接池/keep-alive、合理端口范围和服务端架构处理，不应粗暴取消 TIME_WAIT 的协议保障。</p>`,['SYN Flood 如何缓解？','CLOSE_WAIT 多说明什么？','服务端能否主动关闭？'],'网络基础必背。','中等',['TCP','TIME_WAIT','握手'],'必背'),
  q('network','HTTP','HTTP/1.1、HTTP/2、HTTP/3 的核心差异是什么？','1.1 主要按文本请求响应；2 在单 TCP 上二进制多路复用和头压缩；3 基于 QUIC/UDP，把流级可靠性与连接迁移做进协议。',`<p>HTTP/1.1 keep-alive 复用连接，但管线化受限，浏览器常开多 TCP。HTTP/2 的 stream 并发减少应用层队头阻塞，但底层 TCP 丢包仍会阻塞所有流。HTTP/3 的 QUIC 为每条流独立可靠传输，支持 0/1-RTT 与连接 ID 迁移，减少 TCP+TLS 握手成本。</p><p>HTTP/3 并非任何场景都更快，受 UDP 可用性、CPU、网络质量和实现成熟度影响。0-RTT 数据可能被重放，非幂等请求需谨慎。</p>`,['HPACK/QPACK 为什么不同？','HTTP/2 是否必须 TLS？','QUIC 如何拥塞控制？'],'联系 Provider 流式调用和长连接。','困难',['HTTP2','HTTP3','QUIC'],'深挖'),
  q('network','TLS','HTTPS/TLS 握手如何建立机密性和身份认证？','客户端验证证书链与主机名，双方通过密钥交换导出会话密钥，后续用对称 AEAD 加密并保证完整性。',`<p>TLS 1.3 中客户端发 ClientHello、随机数、支持套件与 key share；服务端返回选择和证书，用私钥签名握手 transcript 证明身份。双方通过 (EC)DHE 共享秘密经 HKDF 导出流量密钥，提供前向保密。</p><p>证书由受信 CA 链验证，必须检查有效期、用途、撤销策略和 hostname。TLS 防传输窃听与篡改，不保证服务端业务安全。会话恢复降低握手成本，0-RTT 需处理重放。</p>`,['对称与非对称加密各做什么？','中间人为何不能替换证书？','证书固定有什么代价？'],'安全岗位网络基础。','困难',['TLS','HTTPS','证书'],'必背'),
  q('network','流式通信','SSE 与 WebSocket 如何选择？流式 Agent 输出中断怎么办？','SSE 是基于 HTTP 的服务端单向事件流，简单可重连；WebSocket 全双工。Agent 单向 Token/事件推送常适合 SSE，中断需事件 ID、持久化游标与幂等恢复。',`<p>SSE 使用 <code>text/event-stream</code>，浏览器原生 EventSource 支持重连和 Last-Event-ID，代理配置要关闭缓冲并设置心跳。WebSocket 适合双向低延迟交互，但连接状态、背压、认证续期和网关支持更复杂。</p><p>Provider 流中断时要区分模型任务是否仍在服务端运行、已接收内容是否可作为正式结果。最好事件带 sequence，服务端落盘原始流；可 resume 则从游标续接，不可 resume 则以同一 run id 重试并避免重复提交副作用。</p>`,['SSE 是否支持 POST？','如何做背压？','代理超时怎么处理？'],'对应 Agent 流式 stdout/Provider 输出。','中等',['SSE','WebSocket','流式输出'],'深挖'),

  q('computer','Cache','Cache Line 和局部性是什么？为什么数组通常比链表快？','缓存以固定 Cache Line 搬运数据；数组连续，具有空间局部性和预取优势，链表节点分散且指针依赖导致更多 cache miss。',`<p>CPU 与内存速度差距大，L1/L2/L3 缓存利用时间局部性和空间局部性。访问数组一个元素会把邻近元素一并加载，硬件预取也容易识别顺序模式；链表每步地址依赖前一节点，节点可能跨页并额外存指针。</p><p>算法复杂度相同不代表实际性能相同。紧凑布局、批量处理和避免随机访问常显著改善吞吐，但数组中间插入成本高，仍需按工作负载权衡。</p>`,['Cache miss 有哪些类型？','Structure of Arrays 何时更好？','预取有什么副作用？'],'计组和性能分析基础。','中等',['Cache Line','局部性','数组链表'],'必背'),
  q('computer','并发','什么是伪共享？内存屏障解决什么问题？','不同线程修改同一 Cache Line 上的不同变量会导致一致性抖动，叫伪共享；内存屏障约束编译器/CPU 的读写重排与可见顺序。',`<p>缓存一致性以 line 为粒度，所以两个独立计数器若落在同一 line，写入会互相使对方缓存失效。可用 padding/alignment、分片计数再聚合缓解。</p><p>多核和编译器会重排内存操作；原子变量的 acquire/release 建立 happens-before，使数据在正确同步后可见。volatile 在 C/C++ 中主要约束某些编译优化，不提供线程同步和原子性。屏障不能修复普通数据竞争，优先使用正确的锁与原子抽象。</p>`,['MESI 大致如何工作？','volatile 为什么不能做锁？','顺序一致性代价是什么？'],'多线程题常见深挖。','困难',['伪共享','内存屏障','原子'],'深挖'),
  q('computer','体系结构','中断、异常和系统调用有什么区别？','中断通常由外部设备异步触发；异常由当前指令同步触发；系统调用是程序主动用受控异常进入内核。',`<p>时钟、网卡完成等产生硬件中断；除零、页故障、非法指令属于异常；系统调用通过专用指令切换特权级并进入内核入口。内核保存上下文、验证参数、执行服务后返回用户态。</p><p>系统调用不必然发生进程切换，但会有用户/内核态切换成本；缺页可能进一步阻塞并调度其他线程。批处理、io_uring、vDSO 等机制用于减少或绕开部分高频切换开销。</p>`,['用户态/内核态为何隔离？','软中断是什么？','一次 read 发生哪些步骤？'],'操作系统与计组交叉基础。','中等',['中断','异常','系统调用'],'常规'),

  q('algorithm','链表','如何反转单链表？怎样证明不会丢节点？','维护 prev、cur、next：先保存 cur.next，再反向指向 prev，最后推进 prev/cur；循环不变量是 prev 已反转、cur 及之后未处理。',`<p>迭代模板：<code>prev=None; cur=head; while cur: nxt=cur.next; cur.next=prev; prev=cur; cur=nxt</code>，返回 prev。时间 O(n)、额外空间 O(1)。先保存 next 是关键，否则改指针后会丢失后缀。</p><p>递归写法简洁但有 O(n) 调用栈并可能溢出。面试时先说空链表/单节点边界，再用 1→2→3 手推指针变化。</p>`,['如何反转前 k 个？','如何每 k 个一组反转？','递归版本怎么写？'],'高频手写题。','简单',['链表','双指针','手写'],'必背'),
  q('algorithm','滑动窗口','最长无重复子串如何用滑动窗口解决？','右指针扩展，哈希表记录字符最近位置；重复时左边界跳到 max(left,last+1)，每步更新最大长度。',`<p>窗口始终保持无重复这一不变量。使用 lastIndex 可让 left 一次跳过旧重复字符，时间 O(n)、空间 O(字符集)。必须取 <code>max(left,last[c]+1)</code>，否则遇到窗口左侧的历史重复会让 left 倒退。</p><p>如果题目改成“至多 K 种字符”，可用频次表并在种类数超限时逐步收缩；滑动窗口适用于区间性质能随左右移动增量维护的题。</p>`,['为什么 left 不能倒退？','Unicode 字符怎么处理？','最小覆盖子串有什么不同？'],'高频滑窗模板。','中等',['滑动窗口','哈希表','字符串'],'必背'),
  q('algorithm','堆','海量数据 Top K 如何做？','求最大 K 个时维护大小为 K 的小根堆，新元素大于堆顶才替换；时间 O(n log k)、空间 O(k)。',`<p>小根堆顶是当前 Top K 中最小者，也是进入门槛。扫描后堆内即答案，若要有序再 O(k log k) 排序。若数据无法单机容纳，可分片各求局部 Top K，再合并；也可按场景使用 Quickselect，平均 O(n) 但会修改数据且不适合流式。</p><p>高频词 Top K 先哈希计数，再堆；如果 key 数量极大，还需外部排序、Count-Min Sketch 或分布式聚合。</p>`,['为什么最大 K 用小根堆？','Quickselect 最坏复杂度？','如何处理并列？'],'堆高频题与系统数据量结合。','中等',['Top K','堆','海量数据'],'必背'),
  q('algorithm','设计题','如何设计 O(1) 的 LRU Cache？','哈希表提供 O(1) 定位，双向链表维护最近使用顺序；访问/更新移到头部，满时淘汰尾部。',`<p>节点保存 key/value/prev/next，使用 dummy head/tail 简化边界。<code>get</code> 命中后 detach + insertFront；<code>put</code> 已存在则更新并前移，不存在则插入并在超容量时删除 tail.prev，同时从 map 删除。</p><p>双向链表是因为已通过哈希定位节点，需要 O(1) 从中间删除；单链表无法直接得到前驱。并发版本还要加锁或分段，严格 LRU 会造成热点锁，工程中可能选择近似 LRU。</p>`,['LFU 如何实现？','为什么需要 dummy 节点？','线程安全怎么做？'],'后端面试经典手写设计题。','中等',['LRU','哈希表','双向链表'],'必背'),
  q('algorithm','并发题','生产者—消费者模型如何正确实现？','用互斥锁保护有界队列，用 notEmpty/notFull 条件变量在 while 条件中等待，状态改变后通知对应等待者。',`<p>生产者持锁检查队列满则 <code>while(full) wait(notFull)</code>，入队后通知 notEmpty；消费者同理。wait 会原子释放锁并休眠，唤醒后重新竞争锁。必须用 while 防虚假唤醒以及被其他线程先消费条件。</p><p>工程中还需关闭语义：设置 closed 标志并 notify_all，让消费者处理完剩余项后退出；支持取消、超时、背压和异常传播。不要持锁执行慢 I/O。</p>`,['为什么两个条件变量更清晰？','信号量如何实现？','如何避免线程退出死锁？'],'联系 Agent Worker 队列和背压。','困难',['生产者消费者','条件变量','并发'],'深挖'),
  q('backend','Java并发','ThreadPoolExecutor 的核心参数和任务执行顺序是什么？','任务先交给 corePoolSize 内核心线程；核心线程满后进入 workQueue；队列满后扩到 maximumPoolSize；仍无法接收时触发拒绝策略。',`<p>关键参数包括 corePoolSize、maximumPoolSize、keepAliveTime、workQueue、threadFactory 和 rejectedExecutionHandler。执行顺序不是“先创建最大线程再入队”，而是<strong>核心线程 → 队列 → 非核心线程 → 拒绝</strong>。</p><p>无界队列会让 maximumPoolSize 形同虚设，并可能积压到 OOM；队列太小则在突发流量下频繁扩容和拒绝。CPU 密集型线程数通常接近 CPU 核数，I/O 密集型可更高，但应根据等待/计算比、下游容量和压测决定。生产环境还需监控 activeCount、queue size、拒绝次数和任务耗时。</p>`,['execute 和 submit 有什么区别？','四种拒绝策略分别是什么？','核心线程会超时吗？'],'可联系 Harness 的并发 Agent Worker 池、Provider 限流和背压。','困难',['线程池','ThreadPoolExecutor','背压'],'必背'),
  q('algorithm','概率结构','Bloom Filter 的原理、误判特性和适用场景是什么？','多个哈希函数把元素映射到位数组；查询位中只要有 0 就一定不存在，全为 1 则可能存在，因此有假阳性但没有假阴性。',`<p>插入元素时用 k 个哈希函数设置 k 个 bit；查询时检查同一组位置。随着元素增多，bit 冲突使假阳性率上升。标准 Bloom Filter 不能直接删除，因为某个 bit 可能被多个元素共享；Counting Bloom Filter 用计数器支持删除但占用更多空间。</p><p>典型用途是缓存穿透防护、爬虫去重和存储系统读前过滤。它只能作为前置筛选，不能把“可能存在”当成权威结果；容量 n、位数组大小 m 和哈希数 k 应按可接受误判率预估。</p>`,['为什么没有假阴性？','如何估计最优哈希函数数量？','布谷鸟过滤器有什么区别？'],'可用于解释 Redis 缓存穿透方案的空间效率与边界。','中等',['Bloom Filter','缓存穿透','概率结构'],'必背'),
  q('network','TCP','TCP 如何通过滑动窗口、重传和拥塞控制保证可靠与高效？','序列号与 ACK 保证有序确认，滑动窗口支持流水发送，超时/快速重传处理丢包，拥塞窗口依据网络反馈控制在途数据量。',`<p>发送方维护已发送已确认、已发送未确认和可发送窗口；接收方通过 rwnd 做流量控制，避免压垮接收缓存。RTO 基于 RTT 动态估计，超时触发重传；收到重复 ACK 可触发快速重传。</p><p>实际发送窗口约为 <code>min(rwnd, cwnd)</code>。慢启动让 cwnd 指数增长，到阈值后拥塞避免线性增长；丢包时根据算法执行快速恢复或回退。可靠性来自字节序号、校验、ACK、重传和有序交付的组合，不是只靠“三次握手”。</p>`,['流量控制和拥塞控制区别？','为什么 RTO 不能设成固定值？','SACK 解决什么问题？'],'联系 Agent Provider 长连接、流式输出与弱网恢复。','困难',['TCP可靠传输','拥塞控制','滑动窗口'],'深挖')
];

