  {id:'career',order:'08',title:'岗位面试与工程表达',desc:'把真实项目、工程权衡、国产算力适配、协作冲突和入职计划讲清楚，不夸大个人职责或实验数据。',subs:['求职表达'],skills:['Project Story','Bad-case / Metrics','Collaboration','Career Motivation']}
