QUESTIONS.push(
  X('agent','Prompt工程','System、Developer、User 与 Tool 内容的优先级为什么重要？','不同消息层代表不同信任与控制来源；应用必须把稳定规则放高优先级，把网页、文档和工具输出明确标为不可信数据。',['不能依赖自然语言让低优先级内容“自觉服从”，工具权限仍由宿主强制。','模板拼接时保持边界和来源标签，防用户输入逃逸到系统指令区域。','冲突指令、间接注入和工具结果攻击应进入回归集。'],['引用文档中的命令该执行吗？','角色消息能否防所有注入？','怎样标记不可信上下文？'],'安全 Agent 读取仓库时，README/代码注释属于数据而不是高权限指令。','简单',['Instruction Hierarchy','Prompt'],'必背'),
  X('agent','Prompt工程','Zero-shot、Few-shot 与 In-context Learning 如何选择？','简单清晰任务先 Zero-shot；格式、边界或少见模式不稳时加入少量代表性 Few-shot，让模型从上下文示范中归纳行为。',['示例要覆盖正常、边界和拒答，不要只堆成功案例。','示例顺序和标签分布会影响输出，避免把测试答案泄漏进 Prompt。','Few-shot 占用上下文并可能过拟合表面格式，稳定长期行为可考虑微调。'],['示例越多越好吗？','负例怎么写？','Few-shot 和 Fine-tuning 区别？'],'可用于 Runner 输出 Schema 和 Reviewer qualification 示例。','简单',['Few-shot','ICL'],'常规'),
  X('agent','Prompt工程','Chain-of-Thought、Scratchpad 和最终答案应如何处理？','复杂问题可让模型使用内部或受控 Scratchpad 分解，但产品应要求简洁可验证的最终依据，而不是依赖暴露的长推理文本。',['推理文本可能包含不可靠叙事、敏感上下文和提示攻击，不应直接作为 Evidence。','更有效的方法常是让模型列假设、调用工具、检查结果和给出来源。','不同模型对显式 CoT 的最佳实践不同，应遵循 API 能力并做任务评测。'],['CoT 一定提高准确率吗？','隐藏推理如何审计？','Self-Consistency 需要公开 CoT 吗？'],'AV 只接收 Artifact、Attempt 与结构化 Proposal，不把模型“想法”当科学真值。','中等',['Chain-of-Thought','Scratchpad'],'深挖'),
  X('agent','Prompt工程','如何做 Context Packing？','按当前目标把最高价值的指令、状态、证据和历史装入有限窗口，并使用相关性、时效、来源和 Token 成本决定取舍。',['稳定规则放前部，当前问题和关键证据放模型易关注位置；长上下文仍可能出现 middle loss。','先精确检索和去重，再扩展邻近上下文；不同数据类型用清晰分隔和元数据。','打包结果记录 source/version，便于复现某次模型调用。'],['重要信息放开头还是结尾？','如何处理重复文档？','Packing 与 Summarization 区别？'],'Review Package 的输入顺序就是领域化 Context Packing。','困难',['Context Packing','Long Context'],'必背'),
  X('agent','Prompt工程','Prompt 优化为什么必须基于错误分类？','先区分知识缺失、指令歧义、检索失败、工具失败、格式错误和流程状态错误，再选择改 Prompt、RAG、Schema 或 Workflow。',['只根据少数失败不断加规则会让 Prompt 膨胀并产生冲突。','建立 failure taxonomy 和代表样本，每次修改验证目标切片与全局回归。','能由代码确定的校验交给代码；需要外部事实的交给检索/工具；跨步可靠性由 Workflow 负责。'],['什么时候应该删除 Prompt 规则？','自动 Prompt Optimization 可靠吗？','如何防回归？'],'你的项目价值就在于识别“不是 Prompt 文案就能解决”的调查控制问题。','困难',['Prompt Optimization','Failure Taxonomy'],'高压')
);
;
/* LangGraph 状态工程专项：核心是长程 Agent 的 Task State 外部化，不把所有文件泛化为“Memory”，也不声称项目直接使用 LangGraph。 */
QUESTIONS.push(
  X('agent','LangGraph · 对齐','Workflow-Harness 与 LangGraph 最准确的关系是什么？','我们没有直接使用 LangGraph，而是围绕完整 Coding Agent 实现了文件化、Runner-neutral 的显式状态与恢复机制；它与 LangGraph 的 State/Persistence 思想相似，但执行单元和持久化边界不同。',['Manifest/Canonical State 类似 State，Worker Result 类似 Node 的局部 State Update，Runtime 负责受控合并。','Run/Workflow ID 类似 Thread ID，Checkpoint 文件类似 Checkpointer，跨任务经验与 Skill 更接近 Store。','最大差异是 LangGraph Node 常是函数、模型或工具；Harness 的执行单元是 Codex/Claude Code/OpenCode 的完整 Agent Turn。'],['为什么不能说我们就是 LangGraph State？','能否用 LangGraph 重构 Harness？','哪些领域不变量仍需自己实现？'],'开场先说“思想相似、边界不同”，不要把框架名词冒充成项目事实。','简单',['LangGraph','Workflow-Harness','概念对齐'],'必背'),
  X('agent','LangGraph · 对齐','Manifest、Canonical State、Checkpoint、Artifact 分别对应什么？','Canonical State 保存当前权威事实，Manifest 还包含运行配置与引用，Checkpoint 是可恢复快照，Artifact 是原始日志、PoC、Diff 等外部证据。',['Canonical State 接近 Graph State，Checkpoint 接近 Thread-scoped Checkpointer。','Artifact 不是聊天记忆；State 通常只保存 artifact_id、hash、path/URI、producer 与 summary。','Runner Session 没有 LangGraph 中的完全等价物，它是底层 Coding Agent 的隐式上下文。'],['Manifest 和 Canonical State 为什么不完全一样？','Artifact Store 放哪里？','Session Handle 应该进 State 吗？'],'用这张映射表回答“你们自研了什么”。','中等',['Manifest','Canonical State','Checkpoint','Artifact'],'必背'),

  X('agent','LangGraph · State','Agent 系统中的 State 到底是什么？','State 是工作流某一时刻对任务事实和执行进度的显式表示；节点读取它，执行后只返回需要修改的字段。',['通常用 TypedDict/Pydantic/dataclass 定义 Schema，包括目标、阶段、工具结果、候选假设、未决问题和下一节点。','AV 中可映射为目标认知、Frontier、Case/Claim、Evidence State、Gap/Obligation、Artifact 引用和工作流位置。','State 能驱动确定性恢复与路由，不应只是一段让模型自己重新理解的摘要。'],['State 为什么需要 Schema？','节点返回完整 State 还是 Delta？','State 是业务真值吗？'],'可直接用“现在系统确认了什么、还缺什么、做到哪里”口语化解释。','简单',['State','Schema','State Update'],'必背'),
  X('agent','LangGraph · State','State 和聊天历史有什么区别？','聊天历史只是 State 的一个可选字段；真实 Agent State 还包括环境、阶段、工具结果、未解问题、权限和已产生的副作用。',['只保存 messages，后续 Agent 必须从自然语言重新推断任务状态，容易遗漏条件或把假设当事实。','“我认为可能越界”是 message；`candidate=CASE-17, evidence=source_trace, gap=runtime_reachability` 才是可路由的状态。','对话可压缩或裁剪，权威业务状态不应随摘要消失。'],['MessagesState 够用吗？','什么信息不应进 messages？','聊天摘要错了怎么恢复？'],'对应 Harness 的核心判断：Session Memory 服务效率，Canonical State 服务权威与审计。','简单',['MessagesState','Chat History','Canonical State'],'必背'),
  X('agent','LangGraph · State','State、Context 和 Memory 如何区分？','State 是当前任务中会变化的数据，Context 是本次运行依赖但通常不由节点改写的环境，Memory 是历史信息的保存和召回机制。',['State：当前阶段、Case 状态、工具结果和进度。','Context：user/tenant_id、workspace、模型配置、Runner 名称和权限。','Memory：过往会话、经验、用户偏好或跨任务知识；被召回后仍只是输入，不自动变成当前事实。'],['Runtime Context 为什么不放进 State？','Memory 召回后如何验证？','Config 和 Context 是一回事吗？'],'速记：State=现在做什么；Context=这次在什么环境；Memory=过去什么可能有用。','简单',['State','Context','Memory'],'必背'),

  X('agent','LangGraph · Persistence','Checkpointer 和 Store 有什么区别？','Checkpointer 保存单个 Thread 的工作流 State 快照，服务暂停、恢复和回溯；Store 保存状态之外、可跨 Thread 复用的应用级数据。',['Checkpointer 中可是某次仓库调查的 Frontier、CASE-3 进度和下一节点。','Store 中可是语言生态漏洞模式、工具经验、历史环境失败或用户偏好。','短期 Thread State 被清理不代表应删除跨 Thread 知识；用户删除长期记忆也不应破坏审计 Checkpoint。'],['Store 能否代替向量数据库？','Checkpoint 是短期记忆吗？','跨 Thread 经验怎样隔离租户？'],'这是 LangGraph 最高频区分题之一。','简单',['Checkpointer','Store','Persistence'],'必背'),
  X('agent','LangGraph · Persistence','Thread ID 和 Checkpoint ID 有什么区别？','Thread ID 标识一条持续任务或会话，Checkpoint ID 标识该 Thread 在某一时刻的状态快照；一个 Thread 通常有多个 Checkpoint。',['Thread 例如 `nginx-run-003`，Checkpoint 可分别对应 survey 完成、CASE-17 补证完成、review 完成。','恢复最新进度通常给 Thread ID；回放、分叉或对比需明确 Checkpoint ID。','ID 还要和 tenant/user/workflow 授权绑定，不能因为客户端知道 Thread ID 就允许读取。'],['Checkpoint 什么时候产生？','一个 Run 和 Thread 一定是一对一吗？','如何清理旧 Checkpoint？'],'对应 Harness 的 Run ID/Workflow ID 与阶段性文件快照。','简单',['Thread ID','Checkpoint ID'],'必背'),
  X('agent','LangGraph · Persistence','为什么不能只保存最后一个状态？','历史 Checkpoint 同时服务崩溃恢复、失败回放、分叉实验、责任审计和结论形成过程的追溯。',['只有最终值，无法解释哪个 Agent 在什么证据上修改了哪个字段。','从历史快照分叉可以在同一起点比较 Prompt、模型或下一行动。','生产中不一定永久保存每一份完整快照；可以周期快照 + 增量写入 + 分层保留。'],['Checkpoint 与 Event Log 有什么区别？','回放是否完全确定？','怎样防止存储无限增长？'],'项目中可用来回答“怎样复盘 Agent 为什么得出这个结论”。','中等',['State History','Audit','Time Travel'],'深挖'),

  X('agent','LangGraph · Reducer','Reducer 在 StateGraph 中解决什么问题？','Reducer 决定节点返回的局部更新如何与旧 State 合并；默认常是覆盖，也可按业务规则追加、去重、合并或拒绝。',['`artifacts=[b]` 若覆盖会丢掉 a，若追加则得到 [a,b]；两种都可能合理，要看字段语义。','Reducer 应尽量确定、可测试，并考虑 Resume 后重复 Update 的幂等性。','Harness 比通用 Reducer 更强调状态准入：Worker 只交 Proposed Delta，Runtime 验证，Reviewer 限定证据语义后才进 Canonical State。'],['哪些字段适合覆盖？','Reducer 与数据库事务是一回事吗？','如何测 Reducer？'],'不要只背“Reducer=追加列表”，关键是字段的合并语义。','中等',['Reducer','State Update','Merge'],'必背'),
  X('agent','LangGraph · Reducer','为什么不能对所有列表都直接 append？','无条件 append 会产生重复 Artifact、重复工具记录、冲突结论和 Resume 后的重复写入，而且并行合并顺序可能不稳定。',['Artifact 按 ID/hash 去重，Tool Attempt 按 attempt_id 幂等，Case 状态按 version/CAS 迁移。','多个 Reviewer 的意见可以追加到 reviews，但正式 disposition 必须经 adjudication，不能谁最后写谁赢。','对需要可审计的对象，可保留 append-only event，同时维护一份当前快照供读取。'],['add_messages 为什么可以追加？','如何为 Artifact 定义去重键？','冲突结论怎样裁决？'],'可联系 AV 的 Reviewed Delta 和 Runtime Gate。','中等',['Reducer','Idempotency','Deduplication'],'深挖'),
  X('agent','LangGraph · Reducer','两个并行节点同时更新一个字段怎么办？','要么为字段定义可交换、可合并的 Reducer，要么让分支写入不同字段，再由专门裁决节点合并；默认覆盖字段不能依赖“最后写入者”。',['Worker A 说 report，Worker B 说 reject，应分别进 `reviews[]`，正式状态等待裁决。','Reducer 在并行下应最好满足交换律/结合律，否则调度顺序会改变结果。','Canonical State 提交可用 base_revision + compare-and-swap，若版本已变则拒绝迟到 Delta 或重新基于最新状态执行。'],['INVALID_CONCURRENT_GRAPH_UPDATE 是什么？','CAS 失败后能盲目重试吗？','哪些 Reducer 不具有交换性？'],'对应多 Worker 结果合并与 Canonical State 的乐观并发控制。','困难',['Concurrent Update','CAS','Adjudication'],'高压'),
  X('agent','LangGraph · State','State 应保存当前快照还是完整事件？','实际系统常用两层：当前快照供节点直接读取，追加事件保留状态如何形成的审计轨迹。',['快照例如 `CASE-1.status=needs_more_evidence`，事件例如 created→source_traced→env_failure→reproduced→accepted。','Checkpoint 偏向可恢复快照与节点写入元数据，Audit Trace/Event Log 偏向原因和时序。','事件要是已验证的领域变更，不要把每个模型 Token 都当领域事件。'],['Checkpoint 与 Event Sourcing 区别？','快照多久保存一次？','事件 Schema 如何版本化？'],'可用“当前状态 + 行为责任链”说明可观测性。','困难',['Snapshot','Event Log','Audit Trace'],'深挖'),

  X('agent','LangGraph · Artifact','完整文件、日志和 PoC 应该直接放进 State 吗？','通常不放；State 保存小而稳定的 Artifact Metadata 与引用，原始大文件放 Workspace、对象存储或内容寻址的 Artifact Store。',['元数据至少包含 artifact_id、type、URI/path、sha256、producer、created_at、summary 和权限范围。','大对象进 State 会使每次 Checkpoint 序列化、数据库体积、模型上下文和权限控制都恶化。','引用必须绑定 run/workspace/commit 并做 hash 校验，否则旧 State 可能读到被替换的新文件。'],['Artifact 丢失后怎么办？','为什么要内容寻址？','原始模型输出算 Artifact 吗？'],'对应简历中的 Artifact 管理和证据可审计性。','中等',['Artifact Reference','Object Storage','State Size'],'必背'),
  X('agent','LangGraph · Artifact','为什么 State 里不能只保存摘要？','摘要适合快速定位，但可能丢失命令参数、环境、返回码、时序和正负对照，因此必须保留原始 Artifact 引用。',['三层设计：短摘要供模型定位，结构化状态保留事实和来源，原始 Artifact 供复核与重现。','State 尽量保存原始、通用的业务数据，不要提前格式化为某个节点专用 Prompt。','证据摘要要带 source/hash/version，Reviewer 能随时下钻到完整日志、触发输入、构建命令和目标 Commit。'],['摘要错了怎么修正？','原始数据必须永久保留吗？','如何防止 Reviewer 读到无关 Artifact？'],'“结论可修订，原始产物尽量不可变”是好的面试收口。','中等',['Raw Data','Summary','Provenance'],'必背'),

  X('agent','LangGraph · Memory','Agent 的短期记忆和长期记忆如何区分？','短期记忆通常是 Thread 范围的当前 State，由 Checkpointer 支持继续执行；长期记忆跨 Thread 存在，通常放 Store 并用 Namespace 隔离。',['短期：当前仓库 Security Map、Frontier、正在调查的 Case 和最近实验。','长期：漏洞模式、工具使用经验、历史失败类型和语言生态调查策略。','长期记忆只是先验；它可影响调查优先级，不能直接成为当前目标的漏洞证据。'],['Checkpoint 是否就是 Memory？','长期记忆如何过期？','Namespace 应包含哪些主体？'],'联系一面问题：错误经验最多改变方向，不能改变事实。','简单',['Short-term Memory','Long-term Memory','Store'],'必背'),
  X('agent','LangGraph · Memory','Semantic、Episodic、Procedural Memory 分别是什么？','Semantic 是事实知识，Episodic 是历史经历，Procedural 是完成任务的做法与流程。',['Semantic：ASan 可检测内存越界、CWE-863 是不正确授权。','Episodic：某次相似仓库中复现失败是因为模块未编译。','Procedural：验证对象级授权时先构造两个身份，再做交叉访问对照；AV 中分别对应漏洞知识、历史 Trace、Skill/Playbook。'],['用户偏好属于哪类？','Skill 和 Procedural Memory 有什么区别？','Episodic Memory 如何抽象成经验？'],'不要只背三个英文名词，每个准备一个安全项目例子。','简单',['Semantic Memory','Episodic Memory','Procedural Memory'],'必背'),
  X('agent','LangGraph · Memory','记忆应在 Hot Path 写入还是后台整理？','当前任务的权威事实需及时进 State，跨任务经验更适合在任务后由 Reviewer 或异步流程去重、审核和提炼。',['Hot Path 立即可用，但增加延迟，也容易让 Agent 过度记录尚未验证的内容。','Background 不阻塞主流程，可做去重、冲突检查、TTL 和权限分类，但不能立即被下一步使用。','记忆写入也应有 source、scope、confidence、created_at、expires_at 和 counterexamples。'],['当前对话摘要算 Hot Path 吗？','后台任务失败会怎样？','哪些内容永远不应自动进长期记忆？'],'项目推荐口径：调查事实即时入 State，通用经验离线提炼。','中等',['Memory Write','Hot Path','Background'],'深挖'),

  X('agent','LangGraph · Context','State 持久化了全部历史，每次都要全部塞给模型吗？','不需要；持久化解决恢复与审计，模型 Context 解决当前决策，每个 Agent Turn 只应获取相关 State Slice 和 Artifact。',['完整 Canonical State 留在存储中；Harness 根据 Action 组装只含当前 Case、Gap、可读 Artifact 和约束的 Resource/Action Packet。','上下文可使用 Trim、Delete、Summarize 和相关召回，但这不意味着数据库历史也必须被删除。','选择标准包括：是否直接影响当前 Action、是否有效、是否有来源、是否冲突以及 Token 预算。'],['State Slice 谁来生成？','为什么不按最近时间全量保留？','裁剪会不会破坏恢复？'],'对应 Harness 中“Manifest 全量保存，Action Packet 按需投喂”。','中等',['Context Engineering','State Slice','Token Budget'],'必背'),
  X('agent','LangGraph · Context','上下文摘要会不会丢失重要信息？','会，所以摘要不能替代 Canonical State 和原始 Artifact；它只是面向当前模型调用的有损索引。',['使用“短摘要→结构化事实与引用→原始 Artifact”三层。','摘要要保留未决问题、失败实验、来源、版本和冲突，不能只留“最终结论”。','对重要决策可让节点按需下钻原文，并用断言检查摘要中引用的 Artifact 仍存在。'],['摘要多久刷新？','怎样评测摘要损失？','冲突信息应该怎样呈现？'],'回答长上下文问题时，先分清“保存”与“投喂”。','中等',['Summarization','Context Loss','Canonical State'],'深挖'),

  X('agent','LangGraph · Recovery','Checkpoint 如何支持并行节点的故障恢复？','持久化完成的节点写入与 Pending Writes，并行 Super-step 中某个节点失败时，恢复应尽量只重试未完成部分，不重跑已成功节点。',['A/B 成功而 C 崩溃时，Checkpoint 需能识别 A/B 的结果已经可用。','即使节点计算不重跑，外部副作用仍要有 attempt_id/idempotency_key，防止“已执行但来不及记录”。','恢复时同时校验 Artifact 是否存在、State Schema 是否兼容、租约和权限是否过期。'],['Pending Writes 是什么？','节点已成功但 Checkpoint 未落盘怎么办？','外部工具调用能 exactly-once 吗？'],'可用三个 Case Worker 并行的例子回答。','困难',['Checkpoint','Pending Writes','Fault Recovery'],'高压'),
  X('agent','LangGraph · Recovery','Resume 后节点会从函数中间继续吗？','通常不会；Checkpoint 位于节点或 Super-step 边界，受影响的节点可能从函数开头重新运行，因此副作用必须幂等或拆成独立节点。',['Agent Turn 已经建文件却在 State 提交前崩溃，Resume 重跑可能产生重复报告、目录或危险工具调用。','将“计算决策”与“执行副作用”分节点，对副作用使用稳定 action_id 和状态查询。','Interrupt 也可使当前节点重新执行，中断前的逻辑同样需要注意。'],['为什么不能保存 Python 调用栈？','模型调用如何幂等？','已产生一半的流式输出怎么办？'],'这是“Checkpoint 会自动保证可靠性”的典型误区。','困难',['Resume','Node Boundary','Side Effect'],'高压'),
  X('agent','LangGraph · Recovery','什么是幂等性，Agent Workflow 怎样实现？','幂等表示同一动作执行一次或多次，最终可观察效果相同；可用稳定幂等键、Upsert、内容 Hash、CAS 和固定 Artifact ID 实现。',['每次尝试有 attempt_id，业务动作有 idempotency_key；“同一动作的重试”与“新一次动作”必须区分。','数据库用唯一约束/Upsert/CAS，Artifact 用内容 Hash，外部 API 传幂等键并查询业务结果。','发送邮件、转账、执行 PoC 等无法简单回滚的动作，还需要审批、限额、补偿与审计。'],['Exactly-once 是否可以绝对保证？','幂等键保留多久？','CAS 失败后如何处理？'],'对应简历中 Harness 的异常恢复、审计和可重现性。','中等',['Idempotency','Retry','CAS'],'必背'),
  X('agent','LangGraph · Recovery','Workflow Resume 和 Runner Session Resume 有什么区别？','Workflow Resume 从外部显式 State 恢复下一 Action、Case 和 Artifact；Runner Session Resume 恢复 Codex/Claude 自身看过的文件、对话和隐式推理上下文。',['Workflow 恢复成功但 Runner Session 丢失时，可以用显式 State 与 Artifact 给 Fresh Agent 重建任务包。','Runner Session 还在但 Canonical State 丢失时，系统不知道会话结论是否已被复核，不能仅凭 Session 继续提交。','Session ID 只是 State 中的可选引用，不是任务真值，也无法保证跨 Runner 迁移。'],['Session 丢失时会不会丢掉推理？','Fresh 和新 Thread 完全等价吗？','为什么不能只保存 Session ID？'],'这是 Workflow-Harness 相比普通模型编排的特有高分题。','困难',['Workflow Resume','Runner Session','Fresh'],'高压'),

  X('agent','LangGraph · HITL','Agent 系统为什么需要 Interrupt？','Interrupt 在明确状态已持久后暂停工作流，用于高风险审批、补充信息、人工修订或长时间等待。',['中断包应显示动作、参数、影响对象、原因、证据、风险和 state version，而不是只问“是否继续”。','漏洞场景中，运行高风险 PoC、写真实目标、修改系统配置或对外提交报告都可是控制点。','长时间无人响应时要过期、取消或降级；Resume 前重验权限、环境和对象状态。'],['Interrupt 和普通 return 区别？','审批者很久不回复怎么办？','拒绝后从哪个节点继续？'],'可联系 Human-in-the-loop 和 Agent 高风险工具分级。','中等',['Interrupt','Human-in-the-loop','Approval'],'必背'),
  X('agent','LangGraph · HITL','Interrupt 之前为什么不能随便执行副作用？','Resume 时节点可能从开头重新运行，Interrupt 之前的创建、写入或发送动作可能再执行一次。',['错误顺序：创建用户→Interrupt 等审批→Resume 后又创建用户。','正确顺序：先 Interrupt 获得批准，再执行副作用；或者使用稳定幂等键与业务结果检查。','如果审批等待期间对象或权限变更，批准结果不应绕过 Resume 时的二次校验。'],['Interrupt 调用能放在条件分支中吗？','多个 Interrupt 怎样区分？','审批重复提交怎么办？'],'用一个“先创建用户再审批”的反例最好记。','困难',['Interrupt','Side Effect','Idempotency'],'高压'),

  X('agent','LangGraph · Debug','Time Travel 在 Agent Workflow 中是什么？','Time Travel 是读取历史 Checkpoint，从某个快照查看、回放或修改状态后分叉运行，用于复现 Bug 和受控对比。',['可在同一 Case 起点比较不同 Prompt/模型/下一 Action，或修正一个错误状态后重跑后续节点。','`update_state` 一般产生新分叉 Checkpoint，不应悄悄覆盖已有审计历史。','分叉必须记录 parent checkpoint、新配置、模型版本和 Artifact 共享边界。'],['Time Travel 和业务回滚一样吗？','历史外部系统已变怎么办？','分叉任务如何计费？'],'对应“从同一证据状态测试不同决策”的评测需求。','中等',['Time Travel','Fork','Checkpoint History'],'深挖'),
  X('agent','LangGraph · Debug','Replay 会直接复用原来的模型和工具输出吗？','不能默认会；Replay 可跳过快照前的步骤，但之后的节点通常会重新执行，包括非确定模型调用、API 请求和 Interrupt。',['Replay 表示重新执行；Record/Replay 才表示对已记录的模型/工具响应做固定返回。','严格调试可为外部调用保存 request fingerprint、response、version 和时间，用 mock/recording 做确定回放。','要测新模型则应真正重执行，但要承认外部世界变化和随机性会影响结果。'],['怎样做可重现的 LLM 评测？','温度设为 0 就完全确定吗？','回放时副作用如何隔离？'],'回答时主动区分“重执行”和“固定历史响应”。','困难',['Replay','Record Replay','Non-determinism'],'高压'),

  X('agent','LangGraph · Subgraph','多 Agent 子图为什么需要独立 State Schema？','不同 Agent 有私有工作记忆与不同权限，子图与父图应通过稳定的入口/出口 Schema 转换，而不是共享所有字段。',['Parent Canonical State 生成 Resource Packet，Investigator 使用私有 Context 工作，只向父图返回 Proposed Result/Artifact。','Survey Agent 不需看 Reviewer 的全部推理，Fresh Reviewer 也不应继承 Investigator 未审核的隐式判断。','独立 Schema 能减少字段冲突、上下文爆炸和越权读写，但需明确 Schema adapter 与来源。'],['子图能共享 Checkpointer 吗？','父子 State 同名字段怎么办？','子 Agent 结果谁负责验收？'],'对应 AV 的权限/视角边界，不要说成自由 Swarm。','困难',['Subgraph','Private State','Multi-Agent'],'深挖'),
  X('agent','LangGraph · Subgraph','子图的 Per-invocation、Per-thread 和 Stateless 怎么选？','Per-invocation 每次独立且可中断，Per-thread 在同一 Thread 下持续保留内部状态，Stateless 不做内部持久化。',['Per-invocation 适合 Fresh Reviewer、一次性知识 Worker，每次调用不继承上次私有记忆。','Per-thread 适合长期调查同一个目标的 Sticky Investigator，但权威事实仍必须从父状态刷新。','Stateless 适合格式转换、简单分类器和短确定任务，不能依赖内部 Interrupt/Resume。'],['Fresh Reviewer 为什么仍需要显式 State？','Sticky 会不会累积错误假设？','子图状态多久清理？'],'可用来解释 V1.43 的目标级 Sticky Investigator 和 Fresh Controller/Reviewer。','困难',['Subgraph Persistence','Sticky Session','Fresh Reviewer'],'高压'),

  X('agent','LangGraph · Migration','State Schema 升级后老 Checkpoint 怎么兼容？','持久 State 要有显式 schema_version 和可测试的迁移函数，旧 Checkpoint 加载后先迁移，再进入新图或兼容节点。',['危险变更包括删除/重命名字段、将可选变必填、修改类型、删除暂停中的节点或改变 Resume 顺序。','策略包括默认值、只追加字段、旧字段兼容读、弃用期、节点 alias 与 `v1→v2→v3` 纯迁移函数。','长任务可固定图版本运行到结束，新 Thread 进新版；必须强迁移时先备份和 Shadow Replay。'],['Reducer 变了如何迁移？','next_node 指向已删节点怎么办？','迁移失败如何回滚？'],'这是状态 Agent 从 Demo 进入生产必经的版本化问题。','困难',['State Migration','Backward Compatibility','Schema Version'],'高压'),
  X('agent','LangGraph · Migration','文件化 State 为什么也需要版本号？','文件不会自动解决兼容问题；字段从字符串变对象、数组变按 ID 索引、Action 重命名或 Result Schema 增字段都会使旧 Run 无法恢复。',['每份 Manifest/Checkpoint 包含 schema_version、workflow_version、runner_adapter_version 和必要的 tool schema version。','加载层负责检测版本并迁移，业务节点不应到处写兼容 if/else。','保留迁移前快照和迁移日志，对所有受支持的历史样例做回归。'],['Workflow 版本和 State 版本为什么要分开？','JSON Schema 能否自动迁移？','旧 Runner Session 与新 Adapter 怎么兼容？'],'直接对应 Workflow-Harness 的 Manifest 与跨版本 Resume。','中等',['File State','Schema Version','Manifest'],'必背'),

  X('agent','LangGraph · Security','State 和 Checkpoint 中可以存 API Key 或密码吗？','不应存真实 Secret；State 只保存 secret_ref 或权限需求，执行工具时由 Secret Manager 在受控边界临时注入。',['Checkpoint 可被运维读取、复制到测试环境、打印到 Trace、用于 Time Travel 或发送给 Reviewer。','持久化加密可降低静态泄露，但不能替代数据最小化、字段级脱敏、访问控制与密钥轮换。','工具不应把含 Secret 的环境变量、请求头和完整错误日志返回给模型。'],['Secret Ref 被 Agent 篡改怎么办？','加密 Checkpoint 怎样做密钥轮换？','调试时如何保留有用日志？'],'对应 Agent 的 Secret 隔离与最小数据面。','简单',['Secrets','Checkpoint Encryption','Data Minimization'],'必背'),
  X('agent','LangGraph · Security','为什么 Checkpoint Store 本身是安全边界？','恢复过程会解析并重建持久化对象，因此能写 Checkpoint 的主体可能污染系统真值，甚至利用不安全反序列化扩大为代码执行。',['2026 年 LangGraph 安全公告 GHSA-g48c-2wqr-h844 说明：在攻击者已获得 Checkpoint Store 写权限的前提下，恶意序列化数据可影响恢复时对象重建。','防护包括最小化数据库写权、安全序列化、完整性校验、依赖升级、加密、审计与禁止加载用户上传的任意快照。','加密保密不等于完整性；需要验证数据未被非授权修改，并隔离控制面与 Worker 凭证。'],['这个公告的前置条件是什么？','JSON 是否就绝对安全？','完整性校验和加密区别？'],'不要夸大为“LangGraph 远程无条件 RCE”，必须先说明攻击者需已有 Store 写权。','困难',['Checkpoint Security','Deserialization','GHSA-g48c-2wqr-h844'],'高压'),
  X('agent','LangGraph · Security','多租户 Agent 怎样隔离 State、Store 和 Artifact？','所有读写都同时绑定 tenant_id、user_id、workflow/thread_id 和 workspace/artifact scope，并在服务端基于当前主体重新授权。',['不能只信任客户端传入的 Thread ID/Artifact URI，查询必须带 tenant 条件且由服务端注入。','Store Namespace、向量过滤、Redis Key、对象存储前缀、缓存 Key 和 Trace 查询都要包含租户边界。','异步 Worker 使用短时委派凭证，只访问当前 Action 需要的 State Slice 和 Artifact，不继承控制面高权限。'],['如何防止跨租户向量召回？','管理员能否看所有 Checkpoint？','共享公共 Skill 怎样与租户记忆分开？'],'对应 Harness 的 Workspace、Artifact 与主体权限绑定。','困难',['Multi-tenancy','Namespace','Authorization'],'高压'),
  X('agent','LangGraph · Security','Memory Poisoning 在长期 Store 中怎样防止？','Worker 只能提议记忆，系统保留来源、作用域和反例，经审核、去重、冲突检查和有效期管理后才写入长期 Store。',['记忆至少包含 source、scope、confidence、created_at、expires_at、owner 和 counterexamples。','召回后仍标记为历史数据/经验，不能自动升级为系统指令、当前事实或高风险工具授权。','经验持续出现反例时应收窄条件、降权或过期，并支持用户查看、纠正和删除。'],['记忆评审也用 LLM 可信吗？','冲突记忆能同时保留吗？','删除向量后缓存怎样失效？'],'一面“人给错误经验怎么办”的状态工程版答案。','困难',['Memory Poisoning','Provenance','TTL'],'必背'),

  X('agent','LangGraph · Testing','如何单元测试 State 更新与 Reducer？','将节点和 Reducer 当作可独立调用的纯函数/受控命令，验证只改预期字段、合并语义正确、重复输入幂等且非法迁移被拒绝。',['覆盖正常、空更新、重复 Update、过时 revision、未知 ID、Artifact 缺失与冲突 disposition。','并行 Reducer 测试调换更新顺序是否改变结果，对不可交换字段应强制串行裁决。','对 v1/v2/v3 历史 Fixture 运行迁移回归，再执行一步真实节点确认可继续。'],['Reducer 怎样做性质测试？','节点有模型调用怎么单测？','如何测试 CAS 竞态？'],'直接映射到 Harness 的 Schema、Revision、Artifact Reference 和 Runtime Gate。','困难',['State Testing','Reducer Testing','Migration Test'],'必背'),
  X('agent','LangGraph · Testing','如何只测工作流中间某一段？','人工构造经 Schema 验证的中间 State/Checkpoint，指定它由哪个节点产生，并在目标区间前后设置中断，避免每次从全链路开始。',['例如构造“CASE-17 已有源码证据，缺运行时可达性”，只测 Materializer→Reviewer→Runtime Gate。','模型与 Tool 在单元层用固定 Stub/Record，集成层再使用真实服务并多次采样。','构造 State 必须通过同一业务不变量检查，否则可能测了线上根本不会出现的非法状态。'],['`update_state(..., as_node=...)` 的意义？','如何测条件边覆盖？','中间 State Fixture 怎样版本化？'],'对应“不从 Survey 开始，只测补证与复核”。','中等',['Workflow Testing','Checkpoint Fixture','Partial Execution'],'深挖'),
  X('agent','LangGraph · Testing','如何测试 Agent Workflow 的恢复能力？','对进程、Checkpoint Store、Runner Session、Artifact、重复 Action 和 Schema 升级做故障注入，检查恢复位置、幂等性和错误语义。',['场景：节点中途退出、数据库短暂不可用、Session 丢失、Artifact 缺失、同一 Action 重复送达和 v2→v3 迁移。','断言：从正确 Checkpoint 续跑，已成功步骤不重复，副作用不重复，缺失 Artifact 被显式识别。','还要区分 Workflow State 恢复、Runner Session 恢复和外部业务副作用的真实状态。'],['崩溃点如何系统化生成？','如何测试 accepted-but-uncommitted？','存储完全损坏时怎么办？'],'与 AI 测开的故障注入、可恢复性和 Trace 完整性直接对齐。','困难',['Fault Injection','Crash Recovery','Agent Testing'],'高压'),
  X('agent','LangGraph · Testing','如何评测 Agent Memory 是否真的有效？','不只比最终成功率，还要测正确召回、错误/过期记忆使用、跨用户泄露、写入准确率、重复率和 Token/延迟成本。',['对照组：No Memory、Full History、Summary Memory、Retrieved Memory 和 Structured State，在同模型、任务与预算下多次运行。','注入错误、冲突、过期、不相关和跨租户记忆，检查 Agent 是否降权、忽略、求证或越界使用。','最终指标还要分任务类型：Memory 可能在连续任务有益，在 Fresh Review 中却制造确认偏差。'],['Memory 召回的 Precision/Recall 怎样标注？','怎么测记忆使用而非只是召回？','多次运行如何做统计？'],'可直接回答“怎么测 Harness 的 Memory/State 机制”。','困难',['Memory Evaluation','Ablation','Isolation Test'],'高压'),

  X('agent','LangGraph · 选型','为什么 Workflow-Harness 用文件，而不是直接用 LangGraph 或数据库？','初期优先选文件，是为了跨 Codex、Claude Code、OpenCode 保持 Runner-neutral，让 Agent 能用普通文件工具读取，同时便于审计、复制实验和绑定 Workspace。',['这不意味着文件是最终生产形态；它在并发事务、查询、迁移、权限和大规模清理上都有局限。','产品化可将 State、Checkpointer、Store 和 Artifact 抽成接口：Postgres/SQLite 管事务状态，Redis 管热状态/租约，对象存储管大产物。','LangGraph 可作为上层图编排，把完整 Coding Agent 封装成 Runner Node；但 Workspace、CLI Session、Adapter 与领域证据 Gate 仍需自己实现。'],['文件并发写怎么办？','什么时候迁移到 Postgres？','为什么 Redis 不宜是唯一真值？'],'不贬低 LangGraph：强调当时的设计目标与未来可组合边界。','困难',['File-based State','Runner-neutral','Build vs Buy'],'高压'),
  X('agent','LangGraph · 选型','为什么 Worker 不能直接修改 Canonical State 文件？','Worker 是模型驱动的不可信执行单元，可能输出错误 ID、过强结论、失效引用或受仓库 Prompt Injection 影响，因此只能提交 Proposed Delta。',['Runtime 确定性检查 Schema、identity、base revision、allowed transition、Artifact hash 和幂等键。','Reviewer 检查证据真正支持哪些 Claim、条件与范围；它也只提议变更，最终由 Runtime 原子提交。','权限分离让调查 Agent 可以灵活探索，但无法自己把未审查假设变成系统真值或漏洞报告。'],['Reviewer 也是 LLM，为什么更可信？','Runtime 能否判断漏洞语义？','两个 Delta 基于同一 revision 怎么处理？'],'这是 Harness 安全、状态一致性与 AV 科学权限的交叉题。','困难',['Proposed Delta','Runtime Gate','Canonical State'],'高压'),
  X('agent','LangGraph · 选型','Fresh Reviewer 为什么仍然需要 State？','Fresh 表示不继承前序 Agent 的隐式 Session，不是没有上下文；Reviewer 仍需要经筛选的权威 State、Claim、未决问题和原始 Artifact。',['如果什么都不给，Reviewer 无法判断证据；如果复制全部会话，又会继承 Investigator 的隐式叙事与确认偏差。','Review Packet 只包含当前 Revision、待审 Claim、Artifact 引用、provenance、关键对照与允许的处置。','Fresh 是降低错误相关性和自我确认，不是保证绝对正确；重要结论仍需结构化证据、确定性测试和人工抽查。'],['Fresh 会不会丢失仓库上下文？','Review Packet 谁生成？','为什么不用多数投票？'],'一句话速记：Fresh 丢弃隐式叙事，不丢弃显式证据。','中等',['Fresh Reviewer','Review Packet','Explicit State'],'必背'),

  X('agent','AV · 长程状态','为什么不应把 Harness 中的所有文件统称为“记忆文件”？','因为它们承担的语义不同：系统是把单条 Session 里的隐式认知外部化为可持久、可恢复、可选择注入和可审核的 Task State，而不是简单把历史写进 JSON。',['五层分类：Runner Session 是隐式工作记忆；Canonical Investigation State 是正式事实；Portfolio 是可恢复的调查机会集。','Artifact/Evidence 保存真实执行产物；Cross-task Knowledge/Skill 才是跨任务长期知识与方法。','其中 Canonical State 与 Portfolio 最接近 LangGraph State；Session 和跨任务 Store 都只是相邻层，不应混成一个向量库。'],['五层分别由谁写入？','Task State 属不属于广义 Memory？','哪些信息可以删除？'],'标准开场：“我们不把所有历史统称为 Memory，而是分离 Session、Task State、Portfolio、Artifact 和跨任务知识。”','简单',['Task State','五层状态','最新分析'],'必背'),
  X('agent','AV · 长程状态','既然 Coding Agent 已经有 Session，为什么还需要外部 State？','Session 适合保持单个 Investigator 的局部调查连续性，但它不可稳定审计、迁移或给 Fresh Agent 有界传递；外部 State 则保存系统已正式确认的事实和未解机会。',['Session 记得看过的文件、局部推理、命令、TODO 和构建经验，Resume 可减少重建仓库认知的成本。','但 Session 中无法可靠区分观察、假设和已复核证据，也容易将早期误判沿长 trajectory 保留下去。','所以 Sticky Agent 仍然 owns search，Harness 不把搜索机械化；它只是为仓库级视野提供可恢复的外部支点。'],['外部 State 会不会限制 Agent 自由探索？','Session 丢失后哪些能恢复？','为什么 Sticky 不等于权威？'],'速记：Session 保存 Agent“脑子里在想什么”，State 保存系统“正式知道什么”。','简单',['Runner Session','External State','Sticky Investigator'],'必背'),
  X('agent','AV · Portfolio','Investigation Portfolio 为什么不是 TODO List 或任务队列？','队列表示等待被执行的任务，Portfolio 表示一组会随在线证据演化的调查机会；它保留深入当前方向时仍不应丢失的仓库级广度。',['Direction 可以 active、paused、narrowed、merged、reopened、rejected，还可因 Fresh Re-Survey 或其他方向的新证据而产生。','A→A1→A2→PoC 深挖时，Portfolio 仍保留 B/C，并允许 D 被新证据重新打开；这是 recoverable opportunity set。','它不用 FIFO 语义，也不把优先级简化为静态分数；新 Evidence 可改变整个机会集的后续投入。'],['Portfolio 中的方向什么时候清理？','优先级谁决定？','Portfolio 收敛是否代表目标安全？'],'面试不要说“我们维护了一个待办任务表”，要强调认知状态与机会恢复。','中等',['Investigation Portfolio','Opportunity Set','Direction'],'必背'),
  X('agent','AV · Portfolio','Direction 和 Candidate/Case 有什么区别？','Direction 是有依据但可以很弱的调查机会，只需说清可疑关系、代码锚点、决定性未知和下一探针；Candidate/Case 则是更成熟、可证伪的漏洞命题。',['Direction 可以是“range/offset 关系可能不一致”，即使尚不知攻击者、完整调用路径和最终影响。','成熟 Case 需要更明确的机制、可达条件、边界、竞争解释和可验证主张。','如果要求每个 Direction 先形成完整 Candidate，会过早收窄开放搜索，并丢掉尚弱但可能高价值的方向。'],['Direction 的最低准入条件？','什么时候升级为 Case？','两个 Direction 什么时候合并？'],'这是最新 Direction-centric 分析的核心词义，先用弱方向与强命题的差异口语化说明。','中等',['Direction','Candidate','Case'],'高压'),
  X('agent','AV · Evidence','Evidence Savepoint 和 Workflow Checkpoint 有什么区别？','Workflow Checkpoint 解决运行恢复，回答程序执行到哪里；Evidence Savepoint 解决调查语义持久化，回答哪个关键证据刚刚改变了当前认知。',['Checkpoint 保存 thread/graph state snapshot、next node 和恢复位置；Savepoint 立即落盘 Artifact，记录 Evidence Decision 并更新 Direction/Portfolio。','Savepoint ≠ Handoff：Sticky Investigator 保存关键证据后可以继续调查，不必立即结束 Session 或转给 Reviewer。','一个 Savepoint 可以和运行 Checkpoint 同时发生，但它们的触发条件、审计问题和使用者不同。'],['什么算 Material Evidence？','Savepoint 多频繁会不会拖慢搜索？','每次 Savepoint 都要 Reviewer 吗？'],'一句话：Checkpoint 保存“运行到哪”，Savepoint 保存“证据改变了什么”。','中等',['Evidence Savepoint','Workflow Checkpoint','Savepoint != Handoff'],'必背'),
  X('agent','AV · Fresh','Fresh Re-Survey 和 Fresh Reviewer 分别解决什么？','Fresh Re-Survey 隔离已有调查 trajectory 以恢复搜索广度，Fresh Reviewer 则在 Claim-ready 时限定正式结论的证据边界。',['Re-Survey 可知道仓库、目标边界和必要任务，但故意不读已有 Portfolio、Claim 和 Negative Knowledge，避免先前方向锚定新搜索。','Re-Survey 只提交 Direction Proposals，不直接覆盖 Portfolio；由 Sticky/Portfolio 端做 accept、merge、challenge、defer 或 reject。','Reviewer 不负责每次搜索状态更新；它只在 Artifact-backed Claim 需要进入 Finding 或正式处置时工作。'],['Fresh 什么都不知怎么调查？','为什么 Re-Survey 不读负面知识？','新 Direction 如何与旧方向去重？'],'不要把两个 Fresh 角色混淆：一个扩搜索视角，一个管正式结论准入。','困难',['Fresh Re-Survey','Fresh Reviewer','Context Isolation'],'高压'),
  X('agent','AV · Recovery','可靠恢复为什么必须区分 Workflow、Runner Session 和 Task Environment 三层？','三层分别回答“下一步是什么”、“Agent 还记得什么”和“文件/依赖/运行环境是否仍存在”；只恢复任何一层都不等于任务已可靠续跑。',['Workflow Resume 依赖 Canonical State、Checkpoint 和 Action ID；Session Resume 依赖 Runner 原生 Session Handle。','Environment Resume 要校验 Workspace、代码 Commit、依赖、编译产物、端口、凭证和 PoC/Artifact 是否匹配。','Session 在但 Workspace 被删时，Agent 记得的文件已不存在；Workspace 在而 Session 丢失时，可用 Fresh Agent + State + Artifact 恢复。'],['如何校验三层一致性？','依赖版本变了怎么办？','能否跨 Runner 恢复？'],'速记：显式 State 是可迁移恢复基础，Session 是连续性增强，Workspace 是实际执行基础。','困难',['Workflow Resume','Session Resume','Environment Resume'],'高压'),
  X('agent','AV · Evidence','为什么 Reviewer 不应检查每一次 Direction Update？','搜索状态是高频、探索性的，正式 Claim 则是低频、需要稳定证据门的；把两者混在一起会让 Reviewer 成为搜索瓶颈，并过早把弱方向当成漏洞命题。',['搜索路径：Evidence→Direction→Portfolio→下一轮 Search，包括方向新建、收窄、否定、暂停和重开。','结论路径：Artifact-backed Claim→Fresh Review→Finding/hold/refuted/caller_misuse 等正式处置。','Runtime 可对高频 Direction Delta 做 Schema、ID、revision 和 Artifact 引用校验；只在需要改变正式 Claim 时引入独立语义复核。'],['Direction Update 会不会污染 Portfolio？','什么叫 Claim-ready？','哪些结论必须人工抽查？'],'面试收口：Reviewer 不是每步看着 Agent，而是控制正式结论进入系统的边界。','困难',['Search Path','Claim Path','Reviewer Boundary'],'高压'),
  X('agent','AV · Evidence','Evidence 为什么不只是让当前 Candidate 判得更准？','在开放多方向调查中，证据还应更新 Direction 的认知状态，进而改变 Portfolio 中其他方向的投入、合并、重开和下一步搜索。',['某个运行时结果可能否定当前机制，同时暴露一个新的状态转换或输入边界，从而生成新 Direction。','一个共享 Guard 的可达性证据，可以同时收窄多个 Direction，避免每个 Case 重复做相同追踪。','所以 Evidence Decision 的输出不只是 support/refute，还应包含对 Direction 、deciding unknown 和 Portfolio 的影响。'],['证据如何跨 Direction 复用？','共享 Artifact 如何做 Scope 绑定？','怎样衡量证据是否改变了搜索？'],'这是新研究主线的关键：Evidence 要能改变整个多方向搜索，而不只是给已有漏洞补分。','困难',['Evidence Feedback','Portfolio Update','Open Search'],'高压')
);

/* 通用 Agent 面经到 Harness 的桥接题：先讲行业抽象，再落到项目边界。 */
QUESTIONS.push(
  X('agent','Agent Runtime · 基础','LLM、Agent、Agent Runtime 和 Harness 分别是什么？','LLM提供推理与生成；Agent在模型外加入工具、状态和循环；Runtime让这个循环可靠执行；Harness进一步规定一个长程任务如何组织状态、上下文、恢复和验收。',['LLM本身不拥有外部工具权限和业务真值；Agent Loop通常包含观察、决策、工具调用、结果反馈和终止。','Runtime负责执行、持久化、重试/恢复、流式事件、权限和可观测性；LangGraph可视为低层Agent orchestration runtime。','本项目的Workflow-Harness不重做Codex/Claude Code内部Loop，而是以完整Coding Agent Turn为执行单元，在外层组织长程漏洞调查。'],['Runtime和Framework有什么区别？','Harness一定在Runtime外面吗？','Coding Agent属于哪一层？'],'先讲通用抽象，再说明项目里Harness同时包含Thin Runtime能力和领域Workflow；不要为名词争论。','简单',['LLM','Agent','Agent Runtime','Harness'],'必背'),
  X('agent','Agent Runtime · Recovery','Retry 和 Resume 有什么区别？','Retry是重新尝试当前失败动作，Resume是从已持久化的长程任务状态继续执行；前者处理局部瞬时失败，后者处理跨进程或跨时间恢复。',['429、短暂网络错误和可重试Runner故障可在预算内Retry；权限不足、非法参数或核心假设被证据否定不能盲目重试。','Resume需要Checkpoint、External State和环境一致性；恢复后当前节点仍可能重跑，所以仍需幂等。','一次Resume内部可能包含Retry，但Retry本身不保证Session、Workspace和Workflow位置能够恢复。'],['超时应该Retry还是Resume？','重试几次后转Resume？','业务失败为什么不能盲目Retry？'],'一句话：Retry重做动作，Resume续接任务。','简单',['Retry','Resume','Failure Classification'],'必背'),
  X('agent','Agent Runtime · 架构','多 Agent 为什么不一定优于一个强 Agent？','多Agent增加通信、Context Handoff、状态冲突、重复工作和成本；只有角色隔离、并行性或权限边界带来的收益超过协调损耗时才值得拆分。',['把每个Direction拆成独立Agent会重复建立仓库认知，也容易让多个局部结论争夺Canonical State。','AV更偏向一个Persistent Sticky Investigator owns search，保留连续深度；Fresh Agent只用于重新探索和独立复核这两种明确的隔离需求。','评测时必须和同预算强单Agent比较，不能把更多模型调用产生的结果数量当作架构收益。'],['什么任务适合并行Sub-agent？','Sticky Investigator会不会形成单点偏差？','怎样计算Handoff成本？'],'回答时不要站队单Agent或多Agent，重点是拆分收益与协调成本。','中等',['Multi-Agent','Sticky Investigator','Coordination Cost'],'高压'),
  X('agent','Agent Runtime · 边界','为什么 Workflow-Harness 不只是更复杂的 Prompt Engineering？','Prompt只改变某次调用看到的指令与上下文；Harness还能在模型外控制Session、Workspace、持久State、Artifact、权限、预算、恢复和真实执行路径。',['相同Prompt下，Harness可以因Checkpoint、权限或Evidence Savepoint选择不同Session模式和执行边界。','Prompt无法确定性保证文件权限、超预算终止、Artifact Hash、CAS提交和重复副作用防护，这些必须由Runtime代码强制。','Context Construction属于Harness的一部分，但Harness不等于Context文字拼接，也不因Prompt更长就获得durable execution。'],['哪些逻辑适合写Prompt？','Prompt能否定义State Schema？','为什么Guardrail不能只靠System Prompt？'],'秒答句：Prompt改变本轮输入，Harness控制跨轮系统行为。','简单',['Prompt Engineering','Workflow-Harness','Runtime Boundary'],'必背'),
  X('agent','Agent Runtime · Testing','怎样分层测试 Workflow-Harness？','按Unit、Runner Contract、Integration、E2E四层测试，再横向加入Failure Injection，既验证确定性组件，也验证真实Coding Agent长程协作。',['Unit：Schema/Reducer、revision/CAS、failure classifier、Context Delta、权限与预算；这些尽量不用真实模型。','Contract：Codex/Claude Code/OpenCode Adapter在Fresh/Resume、事件、取消、Artifact和错误Envelope上满足统一agent()语义。','Integration/E2E：联合Session、Workspace、External State、Artifact和Checkpoint；再注入Session丢失、Workspace消失、Tool timeout、状态冲突和进程崩溃。'],['LLM非确定性怎样断言？','哪些测试必须跑真实Runner？','怎样测试权限真的生效？'],'先测确定性边界，再测模型行为；不要用昂贵E2E代替底层单测。','困难',['Harness Testing','Contract Test','Failure Injection'],'高压'),
  X('agent','Agent Runtime · Evaluation','怎样评测 Native Session 和 External State 是否真的有效？','设置可归因的对照组，不只看最终成功率，还要看重复行动、恢复、错误历史继承、跨Session一致性和成本。',['对照可为No External State、Full History、Summary、Structured External State、Structured State + Native Session。','固定模型、目标、工具、环境和预算，多次运行；指标包括任务成功、决定性Artifact、重复阅读/调用、恢复成功率、状态漂移、Token和延迟。','Native Session可能提高连续任务效率，却增加路径依赖；因此还要单独测Fresh Re-Survey、Session丢失恢复和错误假设继承。'],['怎样证明收益来自State而非更多Token？','Full History为什么不是公平上界？','如何测State drift？'],'评测要同时覆盖效果、过程、恢复、成本和副作用，而不是只报找到多少漏洞。','困难',['State Evaluation','Ablation','Long-Horizon Agent'],'高压')
);

/* 最新简历四项机制专项：Thin Runtime、双层持久化、Bootstrap/Delta 注入、证据搜索与上下文隔离。 */
QUESTIONS.push(
  X('agent','简历 · Thin Runtime','为什么叫 Thin Runtime，“Thin”具体薄在哪里？','Thin不是功能少，而是职责边界窄：Runtime控制完整Coding Agent的运行边界，但不重新实现其规划、仓库搜索、工具选择和局部推理循环。',['Runtime负责Session、Workspace、Artifact、预算、权限、超时、取消、异常恢复和Trace。','Coding Agent原生循环负责读代码、搜索、执行命令、编辑、测试、形成局部假设和选择下一探针。','这样既复用强Runner能力，也避免上层硬编码搜索步骤；Runtime提供可靠性约束，不宣称拥有调查策略。'],['如果Runtime不管搜索，Portfolio怎样影响下一步？','Thin是否意味着不能做路由？','什么逻辑不应放进Runtime？'],'回答顺序：先说边界，再列职责，最后说明为什么不接管原生Agent Loop。','简单',['Thin Runtime','Agent Loop','职责边界'],'必背'),
  X('agent','简历 · Thin Runtime','Thin Runtime 和完整 Agent Framework 有什么区别？','完整Agent Framework通常从模型、Prompt、Tool Loop和节点路由开始搭Agent；Thin Runtime把已有Coding Agent视为完整Runner，只做跨Turn的运行与状态控制。',['LangChain/LangGraph可以把模型、工具和函数组织为图；Harness的一个调用内部已经包含模型—工具—环境循环。','Thin Runtime不需要知道Agent每次grep、读文件或测试的内部细节，但要知道调用身份、权限、Workspace、Artifact和完成状态。','若将原生循环再拆成大量机械节点，既重复Runner能力，也可能削弱它对仓库上下文的自适应搜索。'],['Thin Runtime还能使用LangGraph吗？','什么时候应该自建完整Agent？','Runner内部事件需要记录到什么粒度？'],'不要把“薄”说成只封装CLI；它仍负责可靠执行和跨Turn边界。','中等',['Thin Runtime','Agent Framework','完整 Runner'],'必背'),
  X('agent','简历 · Multi-Runner','统一 agent() 与 Runner Adapter 的稳定契约应包含什么？','稳定契约要描述输入资源、会话语义、权限预算、事件与终态，而不是把某个CLI的参数直接暴露给上层。',['输入：action/task、workspace_ref、context_packet、session_mode、budget、permission_profile和idempotency_key。','输出：runner/session handle、structured result、artifact refs、usage、events、exit reason和可分类错误。','Adapter把Codex、Claude Code、OpenCode各自的CLI/SDK、Resume、流事件和版本能力映射到统一语义，并通过capability negotiation处理不支持项。'],['不同Runner没有同等Resume能力怎么办？','流式事件是否属于正式State？','怎样做Adapter契约测试？'],'先讲稳定语义，再讲实现差异；不要声称三种Runner能力完全等价。','困难',['Runner Adapter','agent()','契约设计'],'高压'),
  X('agent','简历 · Thin Runtime','为什么预算和权限必须由 Runtime 管，而不能只写在 Prompt 里？','Prompt只能表达期望，Runtime才能在模型之外确定性地拒绝越权调用、终止超预算执行并留下审计记录。',['预算至少覆盖Token/模型调用、墙钟、工具次数、重试和Workspace资源；达到软阈值可提醒，硬阈值必须停止。','权限按Runner、Action、Tool、路径、网络目标和副作用风险分级，凭证在执行边界临时注入。','仓库内容可能含Prompt Injection，若权限只靠自然语言提醒，Agent仍可能被诱导执行不允许的命令。'],['Agent启动子进程后怎样限制？','权限变化时Resume怎么办？','预算耗尽如何安全收口？'],'可对应AI测开：验证的不只是文本服从，而是控制面是否真正执行限制。','困难',['Runtime Permission','Budget','Prompt Injection'],'高压'),

  X('agent','简历 · Long-Horizon','为什么采用 Native Persistent Session + External Persistent State？','两层分别优化连续性和可恢复权威：原生Session保留高带宽局部认知，外部State保存可审计、可迁移、可选择注入的任务事实。',['Session适合保留看过的代码、近期推理、构建经验和局部TODO，避免每Turn重建仓库认知。','External State保存Target Cognition、Portfolio、Direction、Evidence、Artifact引用和revision，不依赖某个Runner的隐式历史。','Session丢失时可用外部State为Fresh Agent重建；Session仍在时也不能绕过外部State的正式事实和权限。'],['这两层冲突时相信谁？','为什么不只做Session摘要？','External State会不会成为单点故障？'],'速记：Native Session保深度，External State保权威、广度和恢复。','简单',['Native Persistent Session','External Persistent State','双层记忆'],'必背'),
  X('agent','简历 · Context','Bootstrap Context Injection 是什么，什么时候触发？','Bootstrap是在新建、Session丢失或跨Runner接管时，为Agent注入一份足以独立工作的任务基线，而不是把全部历史原样重放。',['内容包括目标与边界、当前State revision、必要的Target Cognition、相关Portfolio/Direction、权限预算和关键Artifact索引。','它不复制前序Agent的隐藏推理；对Fresh Re-Survey还要进一步隔离已有Portfolio/Claim，对Reviewer则构造Claim与证据专用Packet。','Bootstrap完成后记录agent_known_revision或context baseline，后续才能准确计算Delta。'],['Bootstrap和System Prompt区别？','哪些历史不能进入Bootstrap？','怎样测试Bootstrap足够但不过载？'],'核心是“建立可独立工作的基线”，不是简单发送一份长摘要。','中等',['Bootstrap Injection','Context Baseline','Fresh Session'],'必背'),
  X('agent','简历 · Context','Delta Context Injection 是什么，怎样避免重复和状态漂移？','Delta只向持续Session注入相对其已知revision新增或变更的正式状态与Artifact，而不是每轮重复完整Manifest。',['维护agent_known_revision、state_before/after、delta_id和artifact hash；成功确认注入后再推进已知版本。','Delta需包含变更内容、来源、冲突/撤销语义和必要上下文；不能只说“D-17变了”而缺少为什么与证据引用。','若版本断档、Session状态不可信或Delta过大，停止增量注入并重新Bootstrap，避免隐式认知与Canonical State持续分叉。'],['Delta丢了一次怎么办？','状态删除怎样表达？','Session是否真的“理解”了Delta怎么验证？'],'回答要包含revision、ack与fallback，不要只说“每次传新增内容”。','困难',['Delta Injection','State Revision','Context Drift'],'高压'),
  X('agent','简历 · Context','Bootstrap、Delta Injection、Resume 和 Checkpoint 有什么区别？','Resume是继续原生Runner Session，Checkpoint是持久化工作流快照；Bootstrap/Delta则决定恢复或继续时给Agent看什么显式上下文。',['Session Resume可能成功，但若外部State已有新证据，仍需Delta Injection。','Session丢失时不能Resume，可从Checkpoint确定工作流位置，再用Bootstrap给Fresh Runner重建上下文。','Checkpoint解决“系统从哪继续”，Context Injection解决“当前Agent需要知道什么”；二者不能互相替代。'],['Bootstrap是否一定创建新Thread？','Checkpoint恢复后必须注入Delta吗？','Workspace恢复属于哪一层？'],'用“运行位置—会话连续性—可见上下文”三个维度回答。','中等',['Bootstrap','Delta','Resume','Checkpoint'],'必背'),
  X('agent','简历 · Context','Bootstrap/Delta Injection 与 LangGraph 的 State Slice 或 Node Input 怎么对照？','都体现“完整持久化State不等于一次模型调用的Context”；但我们的注入对象是带原生Session的完整Coding Agent Turn，需要额外跟踪它已经知道哪个revision。',['LangGraph节点通常按Schema直接读取State，节点内部再构造模型消息；Harness从External State生成Runner可消费的Context Packet。','Bootstrap类似为新节点实例准备基线输入，Delta更像向有持续隐式状态的执行单元同步状态变更；LangGraph通用State不会自动提供这套Session同步协议。','Packet仍可由LangGraph节点生成，但revision、ack、Runner能力和Context隔离属于应用设计。'],['LangGraph MessagesState能代替吗？','Delta是否写入State？','怎样避免节点看到全局敏感字段？'],'先承认思想共通，再说明原生Session带来的额外同步问题。','困难',['LangGraph State Slice','Node Input','Context Injection'],'高压'),

  X('agent','简历 · Evidence','Evidence Savepoint 如何驱动 Direction switching 和后续投入？','Savepoint不仅保存证据，还把证据转成对决定性未知、Direction状态和Portfolio关系的显式更新，下一轮搜索据此继续、切换、合并、收窄或重开。',['源码追踪、PoC或运行实验先落盘为不可变Artifact，并记录supports/refutes/narrows及适用范围。','若当前方向核心前提被否定，Agent可转向Portfolio中的其他方向；若证据暴露新边界，则可生成或重开Direction。','Savepoint不是固定打分器，也不强制Handoff；具体下一步仍由Coding Agent在更新后的Portfolio和预算下自主选择。'],['谁决定切换方向？','所有工具输出都算Savepoint吗？','如何防止Portfolio频繁抖动？'],'强调Evidence改变搜索状态，而不是Runtime机械指定每一步。','困难',['Evidence Savepoint','Direction Switching','Portfolio'],'高压'),
  X('agent','简历 · Verification','Fresh Re-Survey 与 Fresh Reviewer 的输入分别是什么？','Re-Survey获得干净仓库、任务边界和必要基础信息，但隔离既有调查trajectory；Reviewer获得待审Claim、权威State切片和原始Artifact，但不继承Investigator Session。',['Re-Survey不读已有Portfolio、Claim和Negative Knowledge，输出新的Direction Proposals，目的是恢复搜索广度。','Reviewer必须读Claim条件、代码/运行Artifact、provenance和竞争解释，输出有界处置，目的是控制正式结论准入。','二者都是Context Isolation，但一个减少搜索锚定，一个减少自我确认；都不等于“什么都不给”。'],['为什么Reviewer能看Evidence而Re-Survey尽量不看？','两者能用同一模型吗？','Fresh是否保证独立？'],'这是 Context Isolation & Verification 最重要的角色边界题。','中等',['Fresh Re-Survey','Fresh Reviewer','Context Isolation'],'必背'),
  X('agent','简历 · Verification','为什么搜索状态更新和正式 Claim 更新要分成两条路径？','Direction/Portfolio是高频探索状态，需要快速随证据演化；正式Claim是低频结论状态，需要Artifact绑定和独立Review，二者准入成本不同。',['搜索路径是Evidence→Direction→Portfolio→Search，可包含弱假设、暂停、收窄和重开，不要求每步Reviewer。','结论路径是Artifact-backed Claim→Fresh Reviewer→Finding/hold/refuted等正式处置。','若每个Direction都走正式Review，会阻塞搜索；若Claim也按普通Delta写入，又会把工作假设直接升级成事实。'],['Runtime能否直接批准Claim？','Direction错误会不会污染搜索？','什么时候算Claim-ready？'],'一句话：搜索允许可修订，正式结论要求有界证据门。','中等',['Search Path','Claim Path','Claim Admission'],'必背'),

  X('agent','简历 · LangGraph','Thin Runtime 与 LangGraph Runtime、Node、Graph 的边界是什么？','LangGraph负责通用State、节点和路由编排；Thin Runtime负责一次完整Coding Agent Turn的Runner适配与执行控制，两者可以组合但抽象层不同。',['可以把agent()封装为一个LangGraph Node，由Graph决定何时Survey、Review或结束。','Node内部仍需Adapter启动CLI/SDK、绑定原生Session与Workspace、收集Artifact、执行权限预算并分类错误。','Investigation Portfolio、Evidence Savepoint、Bootstrap/Delta协议和Fresh输入边界都是应用/领域逻辑，不会因采用LangGraph自动获得。'],['为什么不直接把每个工具调用做成Node？','LangGraph Checkpointer能保存Runner Session吗？','若重构你会怎样分层？'],'不要说“LangGraph不能做”，应说“可以承载上层编排，但仍需这些Runner和领域能力”。','困难',['LangGraph Runtime','Runner Node','分层架构'],'高压'),
  X('agent','简历 · LangGraph','External Persistent State 与 LangGraph State、Checkpointer、Store 怎么映射？','目标认知、Portfolio、Direction和Evidence最接近Thread-scoped Graph State；其历史快照由Checkpointer持久化，跨任务知识与Skill才更接近Store。',['Artifact原文件外置，State只存引用；Runner Session Handle可以是State字段，但Session内容不等同Graph State。','Workflow Checkpoint保存执行与状态快照，Evidence Savepoint则是安全调查领域事件，二者可以同一事务落盘但语义不同。','Native Coding Agent Session不等于LangGraph Thread：Thread标识图状态序列，Session标识底层Runner的隐式上下文，两者可一对一、缺失或重建。'],['一个Thread能切换多个Runner Session吗？','Store里能否放Portfolio？','Artifact元数据应由谁Reducer？'],'用“State/Checkpointer/Store/Session/Artifact”五项逐一映射。','困难',['LangGraph Mapping','Checkpointer','Store'],'必背'),
  X('agent','简历 · LangGraph','Investigation Portfolio 为什么不是 LangGraph 自动提供的能力？','LangGraph提供持久化State和路由机制，但Portfolio的对象语义、状态迁移、证据反馈和投资策略是漏洞调查领域建模。',['用TypedDict定义directions字段只解决数据承载，不会自动决定何时形成、收窄、拆分、合并或重开Direction。','Reducer可以合并Delta，但哪些证据改变哪个决定性未知、是否产生新方向仍需领域规则与Agent判断。','因此“使用LangGraph”是基础设施选型，“如何表示和演化开放调查机会集”才是AdaptiveVuls的方法问题。'],['Portfolio能否实现成优先队列？','哪些迁移可确定性校验？','如何测试Portfolio设计有效？'],'收口：Graph State是容器与执行语义，Portfolio是领域State与搜索方法。','中等',['Investigation Portfolio','Domain State','LangGraph'],'必背')
);
;
/* 按目标类型组织的安全题库：面试时先识别目标资产和信任边界，再选择漏洞模型。 */
QUESTIONS.push(
  // 1. Web / API / 业务系统
  X('security','Web/API目标','Mass Assignment（批量赋值）漏洞是什么？','框架把请求 JSON/Form 自动绑定到完整领域对象，攻击者提交本不应可控的字段，如 role、owner、price 或 status。',['不要直接把外部 DTO 反序列化为数据库实体；为每个动作定义允许字段的 Input DTO。','黑名单容易在新增字段时失效，优先 allowlist 和服务端强制覆盖敏感字段。','验证时比较不同角色可控字段、更新前后对象与审计日志，不能只看响应。'],['与 IDOR 有什么区别？','GraphQL Input 是否也会出现？','ORM save(entity) 有什么风险？'],'适合对象更新 API、后台管理与多租户系统。','中等',['Mass Assignment','DTO'],'必背'),
  X('security','Web/API目标','Open Redirect 为什么可能是安全问题？','攻击者控制跳转目标，使可信域名链接把用户重定向到钓鱼站，或参与 OAuth Token/授权码泄露和安全校验绕过。',['不要仅检查字符串前缀，使用 URL Parser 后严格 allowlist scheme、host 和 port。','相对路径跳转更安全；外部跳转可使用服务器映射 ID 与确认页。','单纯跳转的影响通常低于与登录、OAuth、SSO 或敏感参数组合后的影响。'],['`//evil.com` 为什么危险？','redirect_uri 如何校验？','前端跳转算漏洞吗？'],'强调 Impact 依赖组合路径，避免只见机制就夸大。','简单',['Open Redirect','URL解析'],'常规'),
  X('security','Web/API目标','HTTP Host Header Injection 会造成什么？','应用或代理信任客户端 Host/X-Forwarded-Host 构造绝对 URL、重置密码链接或缓存键，可能导致链接投毒、缓存污染和路由绕过。',['外部 Host 必须由反向代理与应用 allowlist，生成链接优先使用固定配置 base URL。','只信任来自受控代理写入的 Forwarded Header，入口先清除客户端同名 Header。','测试覆盖端口、大小写、重复 Host、绝对 URI 与多级代理。'],['密码重置投毒如何形成？','Host 与 SNI 不一致怎么办？','CDN 会怎么缓存？'],'适用于 Web Framework、反向代理和多域名 SaaS。','困难',['Host Header','Password Reset'],'深挖'),
  X('security','Web/API目标','Web Cache Poisoning 的核心条件是什么？','缓存键未包含会影响响应的输入，攻击者用未键入 Header/参数改变响应并让恶意响应被共享缓存保存。',['先识别缓存层、key 组成、Vary 和 TTL，再找 unkeyed input 对响应的影响。','影响可与 XSS、Open Redirect、Host Injection 和路径规范化差异组合。','修复统一规范化、完整 key、禁止缓存用户化响应，并清除已污染对象。'],['Web Cache Deception 有何不同？','Vary 能解决所有问题吗？','如何安全测试共享缓存？'],'CDN/反向代理目标常见的跨层漏洞。','困难',['Cache Poisoning','CDN'],'高压'),
  X('security','Web/API目标','GraphQL 常见安全风险有哪些？','字段级授权缺失、对象越权、深度/复杂度 DoS、批量别名绕限速、过度信息暴露和不安全 Resolver。',['认证后仍对每个 Resolver/对象执行授权，不能只保护顶层 Query。','限制 depth、complexity、batch/alias 与响应大小；生产按需关闭或保护 introspection。','DataLoader 防 N+1 但缓存键要包含用户/租户上下文，避免跨用户数据泄漏。'],['Introspection 是漏洞吗？','如何对 GraphQL 限流？','Subscription 有何风险？'],'适用于现代 API 与多租户平台。','中等',['GraphQL','Resolver'],'必背'),
  X('security','Web/API目标','WebSocket 的认证授权有哪些坑？','握手后形成长连接，服务端仍需验证 Origin、认证有效期、每条消息的动作/对象权限和消息大小，不能只在建立连接时检查一次。',['Cookie 认证会自动携带，需防 Cross-Site WebSocket Hijacking 并校验 Origin。','Token 过期、用户禁用和权限变化要能终止或重新认证现有连接。','限制帧大小、频率、订阅数量与后端 fan-out，防资源耗尽。'],['CSWSH 与 CSRF 关系？','如何刷新 Token？','断线重连如何幂等？'],'适用于实时协作、聊天与 Agent 流式控制通道。','困难',['WebSocket','CSWSH'],'深挖'),
  X('security','Web/API目标','文件解析类目标为什么高风险？','上传文件会进入图像、PDF、压缩、音视频、Office 等复杂解析器，可能触发内存破坏、命令调用、路径穿越和资源耗尽。',['隔离解析服务、非 root、无网络、只读输入和严格 CPU/内存/时间/解压比限制。','先验证格式魔数与大小，再使用更新库；必要时转码为安全中间格式。','文件名、元数据、嵌套文件和外部引用同样是不可信输入。'],['ImageMagick 历史问题说明什么？','压缩炸弹怎么限制？','解析后文件如何安全提供？'],'适用于漏洞平台上传 PoC、日志、固件和报告。','中等',['文件解析','Parser'],'必背'),
  X('security','Web/API目标','业务竞态漏洞应如何测试？','找到“检查—修改”分离的业务不变量，用同步并发请求观察重复扣款、超卖、重复领券或状态跳转。',['稳定复现需要 barrier 同步请求、不同连接/账户和服务端日志，而不只是快速点击。','数据库唯一约束、条件更新、锁和幂等键应在权威事务边界实现。','区分客户端重复、网络重试和真实并发，修复后做高并发回归。'],['HTTP/2 单连接并发有什么帮助？','乐观锁会返回什么？','如何验证资金影响？'],'适合电商、支付、任务领取和审批系统。','困难',['Race Condition','业务竞态'],'高压'),
  X('security','Web/API目标','API Excessive Data Exposure 是什么？','后端返回了调用者不需要或无权看到的字段，依赖前端隐藏/过滤，导致敏感数据可从响应直接获得。',['为不同角色/场景定义 Response DTO 和字段级授权，避免序列化完整 ORM 对象。','日志、导出、错误响应、GraphQL 和批量接口也要检查。','数据分类、契约测试与响应 Schema 可防新增字段意外暴露。'],['与 BOLA 有何区别？','字段脱敏放前端可以吗？','内部 API 是否需要限制？'],'适合个人信息、密钥、内部状态和多租户数据。','简单',['Data Exposure','API Security'],'必背'),
  X('security','Web/API目标','Rate Limit Bypass 常见原因是什么？','限流键、代理 Header、路径规范化、分布式节点或业务动作选择错误，使攻击者通过换标识、变形请求或并发绕过。',['限流应绑定经过认证的主体/租户和真正稀缺资源，不只依赖可伪造 IP。','统一 URL/方法/大小写规范化，多实例使用一致的全局或分层配额。','对登录、验证码、发送消息等动作还要结合账户、设备、目标和风险策略。'],['IPv6 地址如何计数？','CDN 后真实 IP 怎么信任？','限流能防撞库吗？'],'适用于登录、模型调用、短信和计算密集 API。','中等',['Rate Limit Bypass','Abuse'],'常规'),

  // 2. Java / Spring / JVM 目标
  X('security','Java目标','Java 原生反序列化漏洞为什么危险？','ObjectInputStream 会按数据中的类型图实例化对象并触发 readObject/readResolve 等回调，可通过 classpath 中 Gadget Chain 产生危险副作用。',['成立需不可信字节到达反序列化入口、存在可用 Gadget 和足够运行权限。','JEP 290 ObjectInputFilter 可限制类型、深度和大小，但优先改用数据型 Schema。','仅修某条 Gadget 不稳，攻击面是允许任意对象图。'],['serialVersionUID 有何作用？','RMI/JMX 会涉及反序列化吗？','签名数据是否安全？'],'适合 Java 中间件、RPC、Session 与消息目标。','困难',['Java Deserialization','Gadget Chain'],'必背'),
  X('security','Java目标','SpEL、OGNL、MVEL 等表达式注入是什么？','应用把不可信字符串作为表达式解析，表达式语言可能访问对象、类型、方法或 Bean，造成越权读取乃至代码执行。',['区分“用户数据作为变量”与“用户控制表达式源码”；后者风险更高。','使用受限上下文、禁用类型/方法访问、固定表达式并只绑定值。','错误信息和简单算术只能证明表达式执行，Impact 要结合可访问对象与沙箱。'],['SpEL 与 SSTI 区别？','SimpleEvaluationContext 有何作用？','黑名单类名有效吗？'],'适用于规则引擎、搜索过滤、模板和 Spring 配置。','困难',['Expression Injection','SpEL','OGNL'],'深挖'),
  X('security','Java目标','JNDI 注入的安全模型是什么？','不可信名称或地址进入 JNDI Lookup，可能让应用访问攻击者控制的命名/目录服务，并触发远程对象、反序列化或本地 Gadget。',['现代 JDK 对远程 Codebase 有更多限制，但 LDAP/RMI 数据、工厂类和本地 classpath 仍需分析。','修复是不让不可信输入控制 Lookup 名称/Provider，更新组件并限制出网。','不能因为某一 JDK 版本阻止远程类加载就判定无影响。'],['Log4Shell 与 JNDI 的关系？','出网限制能否完全修复？','本地 Gadget 是什么？'],'适用于日志、目录服务和 Java 企业组件。','困难',['JNDI Injection','Java'],'高压'),
  X('security','Java目标','Spring Boot Actuator 暴露可能带来什么风险？','未授权暴露 env、configprops、heapdump、logfile、mappings 或管理操作，会泄露密钥、内存数据和内部攻击面。',['只开放必要 endpoint，管理端口放内网并强认证授权。','heapdump 常包含 Token、密码、Session 和用户数据，影响远高于普通版本信息。','结合具体版本检查历史高风险 endpoint，但不能只按路径名称下结论。'],['health endpoint 能公开吗？','Jolokia 有什么风险？','配置脱敏可靠吗？'],'适用于 Spring 微服务和云原生 Java 目标。','中等',['Spring Actuator','信息泄露'],'必背'),
  X('security','Java目标','Java Zip Slip 如何形成？','解压条目名包含 `../`、绝对路径或符号链接，拼接目标目录后可写出根目录，覆盖配置、脚本或可执行文件。',['对每个 entry 规范化后验证最终路径位于目标根目录，使用安全路径 API。','还需限制文件数、总解压大小、压缩比和重复文件，防 Zip Bomb。','写入后是否可执行、被加载或被 Web 访问决定安全影响。'],['Windows 路径要考虑什么？','tar 解包也会发生吗？','符号链接条目怎么处理？'],'适用于上传插件、导入包和构建制品。','中等',['Zip Slip','Java'],'必背'),
  X('security','Java目标','Spring Security 配置常见授权错误有哪些？','Matcher 顺序、路径规范化、方法级授权缺失、默认放行和多过滤链覆盖不完整会导致鉴权旁路。',['URL 授权与对象级授权都需要；控制器隐藏不能替代 Service/Domain 权限。','检查大小写、尾斜杠、编码、Forward 与静态资源路径在代理和容器中的解析。','测试匿名、普通用户、管理员和跨租户主体的完整矩阵。'],['permitAll 与 ignoring 区别？','方法注解何时不生效？','反向代理路径重写有什么影响？'],'适用于 Java Web/API 源码审计。','困难',['Spring Security','Authorization'],'深挖'),

  // 3. Python / Node.js 目标
  X('security','Python目标','Python pickle / dill / joblib 输入为什么不能来自不可信方？','这些格式可编码对象恢复逻辑并在加载时调用任意 callable，本质上不是安全数据格式。',['攻击者无需借助目标类的额外 Gadget，恶意 pickle 本身通常已有执行能力。','签名只在密钥和生产端可信时保证来源，不改变格式能力。','改用 JSON/MessagePack/Protobuf 和显式类型映射，并隔离历史模型文件。'],['Requests `__setstate__` 为什么不一定新增 RCE？','机器学习模型文件有何风险？','RestrictedUnpickler 可靠吗？'],'正是 AV 最新实验中 Mechanism→Impact 错误提升的典型。','困难',['Pickle','Python'],'高压'),
  X('security','Python目标','PyYAML 不安全加载有什么风险？','旧式或不安全 Loader 可根据 YAML Tag 构造 Python 对象并触发执行；处理不可信 YAML 应使用 SafeLoader 并限制资源。',['确认实际调用是 safe_load、FullLoader 还是 UnsafeLoader，不要只因文件扩展名报告。','YAML Anchor/Alias 也可能造成内存/CPU 膨胀。','配置系统还要防环境变量插值、include 路径和后续模板执行。'],['FullLoader 是否绝对安全？','YAML Bomb 是什么？','ruamel.yaml 如何配置？'],'适用于 CI 配置、Agent Manifest 和插件系统。','中等',['PyYAML','Unsafe Load'],'必背'),
  X('security','Python目标','Python eval/exec 与 ast.literal_eval 的边界是什么？','eval/exec 解释 Python 代码，不能用于不可信输入；literal_eval 只解析有限字面量但仍需大小/深度限制。',['给 eval 删除 builtins 并非可靠沙箱，对象图和实现细节可能绕过。','表达式需求使用专用 parser、白名单 AST 或受限 DSL。','literal_eval 可被极深/巨大结构用于资源耗尽，仍需输入限制。'],['compile() 是否安全？','模板表达式怎么办？','Python 沙箱为什么难？'],'适用于规则、过滤器和 Notebook/在线判题。','简单',['eval','Python Sandbox'],'必背'),
  X('security','Python目标','Python subprocess 调用的主要安全坑是什么？','shell=True、字符串拼接和不可信 argv/环境/工作目录会造成命令或参数注入，子进程权限又扩大影响。',['使用参数数组、固定可执行路径、`--` 终止选项并 allowlist 参数。','清理 PATH、PYTHONPATH、LD_PRELOAD 等环境，设置 cwd、umask、资源和超时。','杀超时进程时终止整个进程组并读取 stdout/stderr，避免泄漏与死锁。'],['shell=False 就绝对安全吗？','PATH Hijacking 如何发生？','临时文件有什么竞态？'],'直接对应 Runner Adapter 与外部工具执行。','中等',['subprocess','Python'],'必背'),
  X('security','Node.js目标','Node.js child_process 使用有哪些风险？','exec 会经过 Shell，spawn/execFile 虽可传 argv，但仍有参数注入、PATH 劫持、环境污染、输出爆量和子进程泄漏。',['固定 binary 绝对路径与 argv，限制输入、cwd、env、stdio 和 maxBuffer。','异步不代表安全，攻击者可启动大量长进程耗尽事件循环外资源。','Electron/桌面应用中 child_process 与 Renderer 输入组合尤其高风险。'],['exec 与 spawn 区别？','maxBuffer 超限会怎样？','npm script 是否经过 Shell？'],'适用于 Node 服务、构建系统和 Electron。','中等',['Node.js','child_process'],'必背'),
  X('security','Node.js目标','ReDoS 为什么常见于 Node.js？','回溯型正则在特定嵌套量词和歧义输入上出现指数级回溯，单线程事件循环被长时间阻塞。',['识别 `(a+)+`、重叠 alternation 等模式，并用长接近匹配输入测试耗时增长。','使用线性时间正则引擎/安全规则、限制输入长度或改写为确定解析。','把正则放 Worker 只是隔离，不修复攻击复杂度和资源耗尽。'],['如何判断正则是线性的？','超时能中断 JS RegExp 吗？','RE2 有什么限制？'],'适用于路由、验证器、日志和文本规整。','困难',['ReDoS','Node.js'],'深挖'),
  X('security','Node.js目标','npm 依赖目标常见供应链风险是什么？','Typosquatting、Dependency Confusion、恶意 install script、维护者账号接管和深层传递依赖可在安装/构建时执行代码。',['使用 lockfile、私有 registry scope、ignore-scripts（评估兼容性）、审计和最小 CI 凭证。','审查新增依赖的维护活跃度、发布历史、安装脚本和权限，而不只看下载量。','构建网络与密钥隔离，制品签名并保存来源。'],['npm audit 的局限？','锁文件能防恶意新版本吗？','postinstall 为什么危险？'],'适用于前端、Node Agent 和构建链。','中等',['npm','供应链'],'必背'),

  // 4. C/C++ / 二进制 / 解析器目标
  X('security','Native目标','格式化字符串漏洞是怎么产生的？','攻击者控制 printf-family 的格式字符串，格式说明符会读取栈参数，`%n` 还可写入已输出字符数。',['安全调用使用固定格式 `printf("%s", user)`，不能 `printf(user)`。','影响取决于 ABI、参数位置、ASLR/PIE、可控输出与进程权限。','编译器 `-Wformat-security` 和 FORTIFY 能发现部分错误，但需修源码。'],['`%x`、`%s`、`%n` 分别做什么？','日志 API 会受影响吗？','C++ iostream 是否同类？'],'适用于 C/C++ 服务、固件和本地工具。','中等',['Format String','C/C++'],'必背'),
  X('security','Native目标','越界读与越界写的影响如何区分？','越界读可能泄露相邻内存或造成 Crash；越界写会破坏对象、控制数据或分配器状态，通常影响更直接但仍需分析可控性。',['确定 base、index、长度、真实对象边界和读写字节数，检查整数转换。','Sanitizer 复现是强 Mechanism Artifact，但真实构建布局与影响需另行限定。','修复在可信长度类型上做边界检查，并验证所有调用者与变体。'],['Heartbleed 属于什么？','Off-by-one 有多严重？','ASan 为什么有漏报？'],'适用于二进制、图像库和网络 parser。','中等',['OOB','Memory Safety'],'必背'),
  X('security','Native目标','Double Free 会造成什么？','同一堆块被释放两次可能破坏 allocator freelist、触发安全检查或使后续分配返回重叠对象。',['根因常是错误所有权、异常路径、重复回调或竞态。','现代 allocator 有 tcache/元数据检查，Crash 不等于无法利用，也不等于可利用。','使用 RAII、唯一所有权、状态机和释放后清除所有别名。'],['Double Free 与 UAF 区别？','智能指针会不会 Double Free？','如何用 ASan 定位？'],'适用于 C/C++ 生命周期漏洞。','困难',['Double Free','Heap'],'深挖'),
  X('security','Native目标','Uninitialized Memory 会产生哪些问题？','读取未初始化栈/堆内存会导致信息泄露、非确定控制流、错误长度和未定义行为。',['MSan 能追踪初始化传播，但依赖库通常也需插桩。','结构体 padding、错误分支和部分初始化是常见来源。','初始化为零可避免泄露但不一定符合业务语义，应保证每个字段在使用前定义。'],['Valgrind 与 MSan 区别？','编译器为何会优化出奇怪行为？','padding 泄露怎么修？'],'适用于协议响应、系统调用结构体和加密代码。','中等',['Uninitialized Memory','MSan'],'常规'),
  X('security','Native目标','二进制协议 Parser 容易出现哪些漏洞？','长度、offset、整数、状态机、嵌套计数和压缩字段处理错误会导致越界、死循环、资源耗尽与逻辑绕过。',['解析每层前验证剩余长度，用 checked arithmetic，限制递归/元素/解压大小。','处理分片、重复字段、未知扩展和大小端；不同实现解析差异会造成协议混淆。','使用语法感知 Fuzzing、差分测试与 Sanitizer。'],['TLV 如何安全解析？','为什么需要 differential fuzzing？','大端小端错会怎样？'],'适用于网络服务、固件、文件格式和 IPC。','困难',['Binary Parser','Protocol'],'必背'),
  X('security','Native目标','ROP 与控制流劫持的基本概念是什么？','攻击者利用内存破坏控制返回地址/函数指针，并串联已有代码片段（gadgets）绕过不可执行内存执行计算。',['NX 阻止直接执行数据，ASLR/PIE 随机化地址，Canary 检测部分栈破坏，CFI 限制间接跳转。','利用通常还需要信息泄露、稳定布局和可控写；不能从 Crash 自动推导 RCE。','根因修复仍是消除内存破坏，缓解措施只是增加利用难度。'],['ret2libc 是什么？','ASLR 熵有什么影响？','CFI 能防所有 ROP 吗？'],'安全研究岗位需要理解 Crash→Exploit 的证据跨度。','困难',['ROP','Mitigation'],'深挖'),

  // 5. 云、容器与 Kubernetes 目标
  X('security','云目标','云 IAM 权限提升常见路径是什么？','主体虽无管理员权限，但能附加高权限角色、PassRole、修改策略、创建访问密钥、部署带权限计算或调用可代理权限的服务。',['不要只检查显式 Administrator，分析权限组合与 resource/condition。','PassRole 必须限制可传角色和目标服务；CI/Serverless 部署权限尤其敏感。','使用权限图、CloudTrail 和最小权限，删除长期未用权限。'],['IAM 与资源策略如何组合？','显式 Deny 优先级？','如何发现 privilege escalation path？'],'适用于 AWS/云平台和企业 CI。','困难',['Cloud IAM','Privilege Escalation'],'高压'),
  X('security','云目标','云元数据服务为什么经常与 SSRF 组合？','服务端能访问 link-local 元数据地址，SSRF 可读取实例身份凭证；旧式无会话保护接口风险更高。',['使用元数据服务会话 Token/跳数限制，禁用不需要的元数据访问。','容器/代理网络可能使 hop-limit 配置出现差异，仍需应用 URL allowlist 与 egress policy。','获得临时凭证后的影响取决于实例角色权限与凭证有效期。'],['IMDSv2 解决什么？','169.254.169.254 为什么特殊？','Kubernetes Pod 能访问节点元数据吗？'],'SSRF 影响评估的云环境关键路径。','困难',['Cloud Metadata','SSRF'],'必背'),
  X('security','云目标','对象存储 Bucket 常见配置错误有哪些？','公开读写、过宽 Bucket Policy、ACL 与 Policy 叠加误判、预签名 URL 过长、目录枚举和敏感备份泄露。',['阻止公共访问并用最小 IAM；服务端加密不等于访问控制。','预签名 URL 是 Bearer 能力，限制对象、方法、有效期和内容条件。','记录访问日志、版本和删除保护，敏感文件还需数据分类与生命周期。'],['公开网站 Bucket 如何安全？','CORS 配置有何影响？','Bucket 名称接管是什么？'],'适用于云应用、报告和 Artifact 存储。','中等',['Object Storage','Bucket'],'必背'),
  X('security','容器目标','容器逃逸常见攻击面是什么？','危险 capabilities、特权容器、宿主挂载、Docker Socket、内核漏洞和不安全运行时配置可让容器影响宿主。',['默认删除 capabilities，禁 privileged，限制 hostPID/hostNetwork/hostPath 和设备。','只读 rootfs、seccomp、AppArmor/SELinux 与 user namespace 缩小攻击面。','不可信代码用 microVM/gVisor 等更强隔离，容器共享内核是根本边界。'],['挂载 docker.sock 等于什么权限？','CAP_SYS_ADMIN 为什么危险？','rootless 能否防逃逸？'],'Coding Agent 与 PoC Sandbox 的关键安全目标。','困难',['Container Escape','Capabilities'],'高压'),
  X('security','Kubernetes目标','Kubernetes RBAC 常见错误是什么？','对 `*`、secrets、pods/exec、create pods、impersonate、bind、escalate 等权限过宽，可直接或间接提升到集群高权限。',['能创建 Pod 且指定 ServiceAccount/hostPath 常可代理更高权限。','RoleBinding 的 subject 与 namespace 要检查，ClusterRole 可被多个绑定复用。','最小权限、审计与定期权限图分析，禁用默认 Token 自动挂载。'],['Role 与 ClusterRole 区别？','bind/escalate 为什么危险？','能读 Secret 是否等于获取凭证？'],'适用于云原生平台审计。','困难',['Kubernetes RBAC','Privilege Escalation'],'必背'),
  X('security','Kubernetes目标','ServiceAccount Token 泄露后的影响如何分析？','Token 代表 Pod 身份，可调用 Kubernetes API；影响由绑定 RBAC、受众、有效期和网络可达决定。',['使用 projected bound token、短期与 audience，关闭不需要的 automountServiceAccountToken。','容器文件读取、SSRF、日志和错误页都可能泄露 Token。','轮换/删除 Pod，审计 API 调用并修正 RBAC，而不只是换 Token。'],['旧 Secret Token 有何问题？','TokenReview 做什么？','Pod 如何获得云身份？'],'适用于集群内服务、Agent Worker 与 CI Runner。','中等',['ServiceAccount','Kubernetes Token'],'必背'),
  X('security','Kubernetes目标','Kubernetes NetworkPolicy 的边界是什么？','NetworkPolicy 控制允许的 Pod 入站/出站连接，但依赖 CNI 实现，不能替代应用认证、DNS 安全和节点防护。',['默认没有策略通常允许通信；需建立 default deny 再精确允许。','按 label 选择目标，错误标签或 namespaceSelector 可扩大范围。','DNS、云元数据、控制面和 egress Proxy 需要单独考虑。'],['策略是否影响宿主网络？','Ingress 和 Egress 区别？','Service Mesh 能替代吗？'],'适用于多租户 Agent 执行集群隔离。','中等',['NetworkPolicy','Kubernetes'],'常规'),

  // 6. 移动端 / 桌面 / Electron 目标
  X('security','Android目标','Android Exported Component 风险是什么？','Activity、Service、Receiver、Provider 对外导出且缺少权限/输入校验时，其他 App 可调用内部功能、读取数据或触发敏感动作。',['检查 Manifest exported、intent-filter、permission 和 Android 版本默认语义。','每个入口重新做认证授权，不能信任 Intent extras 或仅检查调用页面。','ContentProvider 路径、URI permission 和 PendingIntent 需要专门分析。'],['显式 Intent 能绕过吗？','signature permission 是什么？','PendingIntent mutable 有何风险？'],'适用于 Android App 与设备管理目标。','中等',['Android','Exported Component'],'必背'),
  X('security','Android目标','Android WebView 常见风险有哪些？','加载不可信内容时启用 JavaScript、addJavascriptInterface、文件访问、混合内容或不安全 URL 校验，可能跨越 Web 与本地能力边界。',['只加载 allowlist HTTPS Origin，禁不需要的 file/content access 和 mixed content。','JavascriptInterface 只暴露最小方法并检查来源；外部 URL 使用系统浏览器。','处理 shouldOverrideUrlLoading 时用 URL Parser，防 scheme/host 绕过。'],['WebView Cookie 与浏览器共享吗？','file:// 有何风险？','JS Bridge 如何鉴权？'],'适用于 Hybrid App 与嵌入式管理界面。','困难',['WebView','JS Bridge'],'深挖'),
  X('security','移动端目标','Deep Link / Universal Link 安全问题是什么？','自定义 Scheme 可能被其他 App 抢占，链接参数若直接触发登录、支付或 WebView 导航会造成劫持和参数注入。',['优先验证域名归属的 Universal/App Links，并在 App 内再次校验路径、状态和用户确认。','OAuth 回调使用 PKCE、state 和精确 redirect URI，不能只信任收到回调。','敏感动作不应仅凭 Link 中 Token 自动执行。'],['自定义 Scheme 为什么不唯一？','App Link 验证文件是什么？','Deferred Deep Link 有何风险？'],'适用于移动登录和运营活动。','中等',['Deep Link','Mobile'],'常规'),
  X('security','移动端目标','移动端本地存储敏感数据有哪些风险？','SharedPreferences、SQLite、文件、日志、剪贴板、备份和截图可能泄露 Token、PII 或业务数据，越狱/Root 后风险更高。',['密钥放 Keychain/Android Keystore，敏感数据最小化并设置备份/文件保护策略。','客户端加密的密钥若硬编码在 App 中不能抵抗逆向。','服务器端仍要支持 Token 轮换、撤销和设备丢失处置。'],['Keystore 能防 Root 吗？','如何防截图？','日志脱敏怎么做？'],'适用于 App、SDK 与终端 Agent。','简单',['Mobile Storage','Keystore'],'必背'),
  X('security','Electron目标','Electron 中 nodeIntegration 与 contextIsolation 为什么关键？','不可信网页若能直接使用 Node.js 能力就可能读文件/执行命令；contextIsolation 和安全 preload 用于隔离 Renderer 与特权 API。',['禁用 nodeIntegration，启用 contextIsolation、sandbox，并严格限制 navigation/new-window。','preload 通过 contextBridge 暴露最小、参数校验的 API，不能把 ipcRenderer 整体交给页面。','IPC Main Handler 对每个 sender、Origin 和参数做授权，防 XSS 升级为本地 RCE。'],['remote 模块为什么危险？','CSP 有何作用？','自定义协议如何验证路径？'],'适用于桌面客户端、开发工具和 AI IDE。','困难',['Electron','IPC'],'必背'),
  X('security','桌面目标','桌面应用自更新机制应如何保证安全？','更新清单和制品必须使用可信密钥签名，客户端验证版本、签名、目标平台与回滚策略，并通过安全通道获取。',['TLS 不能替代制品签名；CDN/服务器被攻破时签名仍保护完整性。','私钥离线/硬件保护，支持轮换和撤销；客户端内置多个信任根或安全更新根。','防降级到有已知漏洞旧版本，并对增量包和安装路径做验证。'],['代码签名与 TLS 区别？','密钥泄露怎么办？','TUF 解决什么问题？'],'适用于固件、桌面客户端和 Agent Runner 更新。','困难',['Auto Update','Code Signing'],'深挖'),

  // 7. 固件 / IoT / 嵌入式目标
  X('security','固件目标','固件安全分析通常从哪些入口开始？','识别 CPU/文件系统/分区和启动链，解包文件系统，寻找 Web/API、服务、凭证、更新逻辑、启动脚本和本地二进制。',['使用 binwalk/file/strings 等获得 Observation，再结合 QEMU/真机动态验证。','配置、证书、私钥、调试口和云端 endpoint 常比直接二进制逆向更快暴露边界。','解包失败可能因加密、压缩或厂商容器，需要先分析 Header 与 bootloader。'],['SquashFS/UBI 是什么？','固件模拟难点？','如何确认版本？'],'与简历覆盖固件/二进制目标能力相关。','简单',['Firmware','Reverse Engineering'],'必背'),
  X('security','固件目标','固件更新链常见漏洞有哪些？','缺少签名、只校验 CRC/Hash、密钥硬编码、版本回滚、解包路径穿越和更新分区切换错误会破坏更新信任链。',['真实性需要非对称签名与受保护信任根，Hash/CRC 只检测偶然损坏。','签名覆盖版本、型号、分区与完整 Manifest，防合法包跨设备重放。','支持 anti-rollback、安全失败恢复和 A/B 分区，避免断电变砖。'],['Secure Boot 与安全更新区别？','签名公钥放哪里？','离线升级怎么防重放？'],'典型 Evolving Investigation：Boundary 跨 bootloader、OS 与管理服务。','困难',['Firmware Update','Secure Boot'],'高压'),
  X('security','IoT目标','硬编码凭证为什么在 IoT 中常见且危险？','同一固件中的默认账号、SSH Key、API Token 或调试密码会复制到大量设备，泄露一台即可横向影响整个产品线。',['区分每设备唯一凭证与全局共享 Secret；首次启动应个性化并支持轮换。','固件内字符串发现只是线索，要确认服务可达、凭证用途和量产配置。','厂商后门、维护账户和云端共同密钥需要明确 Ownership 与 Scope。'],['哈希密码算硬编码吗？','如何为设备安全注入密钥？','证书过期怎么轮换？'],'适用于路由器、摄像头和工业设备。','中等',['Hardcoded Credentials','IoT'],'必背'),
  X('security','IoT目标','UART、JTAG、SWD 调试接口的风险是什么？','暴露的调试接口可能读取 Flash/内存、绕过启动流程或获得 Shell，但需要物理访问、焊接和设备配置等前提。',['先识别引脚、电压和协议，避免损坏；确认量产设备是否禁用/锁定。','物理攻击者模型与远程漏洞不同，报告需说明所需接触和防拆边界。','使用安全熔丝/认证调试并保留受控返修流程。'],['关闭 JTAG 是否可逆？','UART Shell 如何鉴权？','物理访问是否一定不算漏洞？'],'适用于硬件/固件 Scope 和攻击者模型分析。','中等',['JTAG','UART','Physical Security'],'常规'),
  X('security','IoT目标','嵌入式 Web 管理界面常见漏洞是什么？','默认凭证、命令注入、路径遍历、CSRF、固件上传、配置备份泄露和不安全 CGI 常组合成设备接管。',['目标常用 C/C++ CGI/Lua/轻量服务器，检查参数到 shell、NVRAM 和系统配置的数据流。','默认仅 LAN 可达仍要分析浏览器跨站请求、UPnP、云代理和错误 WAN 暴露。','资源限制和老旧组件使补丁/缓解策略不同于普通 Web 服务。'],['LAN-only 是否降低严重性？','配置备份为什么敏感？','命令注入如何做安全验证？'],'融合 Web、Native、网络和固件的典型目标。','困难',['Embedded Web','Router'],'必背'),
  X('security','IoT目标','BLE/MQTT/CoAP 等 IoT 协议应关注什么？','关注设备身份、配对/认证、加密、Topic/资源授权、重放、广播隐私和 Broker/网关配置。',['MQTT 连接认证后还需 Topic 级 ACL，通配符权限容易跨租户。','BLE “Just Works” 缺少 MITM 保护；特征值读写权限和绑定状态需要验证。','资源受限不等于可省略随机数、nonce 和更新机制。'],['MQTT Retained Message 有何风险？','BLE 地址随机化做什么？','CoAP 如何加密？'],'适用于智能设备、车联网和工业网关。','困难',['MQTT','BLE','IoT Protocol'],'深挖'),

  // 8. 基础设施 / 中间件 / 网络服务
  X('security','中间件目标','Redis 未授权访问的影响如何判断？','若 Redis 对不可信网络开放且无认证/ACL，攻击者可读写缓存与业务数据；进一步影响取决于版本、命令、文件权限和部署。',['先确认网络可达、protected-mode、bind、ACL、TLS 和容器网络。','不要机械声称一定能写 SSH Key/RCE，现代版本、权限和路径条件不同。','修复网络隔离、ACL/TLS、最小命令权限并轮换泄露数据。'],['requirepass 与 ACL 区别？','危险命令重命名够吗？','主从复制能被滥用吗？'],'体现机制、环境和影响分层。','中等',['Redis Security','Unauthenticated'],'必背'),
  X('security','中间件目标','Elasticsearch 暴露常见风险是什么？','未授权集群可泄露、修改或删除索引数据，脚本、Snapshot、插件和集群管理 API 还可能扩大影响。',['检查认证、TLS、网络、角色的 index/cluster privilege 与多租户隔离。','`_cat`、mapping 和搜索响应可暴露 Schema/敏感数据；生产禁公网直连。','历史版本漏洞需结合确切版本与启用功能，不能只看到端口。'],['Kibana 暴露有什么不同？','Snapshot Repository 有何风险？','如何做字段级安全？'],'适用于日志、搜索和安全分析平台。','中等',['Elasticsearch','Data Exposure'],'常规'),
  X('security','中间件目标','消息队列的安全边界有哪些？','Producer/Consumer 身份、Topic/Queue ACL、管理面、传输加密、消息完整性和租户隔离共同决定风险。',['只认证 Broker 连接不够，每个 Topic 的 publish/subscribe/alter 权限要最小化。','消息内容可能含反序列化、模板或命令输入，消费者仍要验证。','管理接口、JMX、Schema Registry 和 Connect 组件常拥有更高权限。'],['Kafka ACL 如何分层？','消息重放是否是漏洞？','死信队列包含敏感数据吗？'],'适用于 Kafka、RabbitMQ 和任务平台。','中等',['Message Queue','ACL'],'必背'),
  X('security','网络服务目标','认证协议中的 Replay Attack 如何防？','攻击者重放之前合法消息；协议使用 nonce、时间窗、序列号、挑战响应和会话绑定保证每次认证的新鲜性。',['时间戳依赖时钟同步且需要缓存已用 nonce；单独时间戳不能防窗口内重放。','签名保证消息未改，但若未包含 nonce/上下文，原签名仍可重放。','把身份、目标、动作和 Channel Binding 纳入签名/MAC。'],['JWT jti 能防重放吗？','TLS 能否防应用层重放？','0-RTT 为什么有重放风险？'],'适用于设备协议、Webhook、SSO 和 API 签名。','困难',['Replay Attack','Nonce'],'深挖'),
  X('security','网络服务目标','协议降级攻击是什么？','攻击者干扰能力协商，使双方使用更弱的协议版本、加密套件或认证方式，再利用旧方案缺陷。',['协商结果必须绑定到完整握手 transcript 并设置最低版本。','移除不安全 fallback，服务器和客户端共同禁用旧协议。','版本字段可改不代表成功降级，需证明双方接受且安全属性下降。'],['TLS_FALLBACK_SCSV 做什么？','STARTTLS stripping 是什么？','向后兼容如何安全设计？'],'适用于 TLS、SSH、设备升级和自定义协议。','困难',['Downgrade Attack','Protocol'],'深挖'),
  X('security','管理面目标','管理端口“只在内网”为什么仍要认证？','内网可能被 SSRF、受感染主机、VPN 用户、错误路由或云配置访问；网络位置只能是纵深边界。',['管理面使用独立身份、MFA、最小角色、审计和强 TLS。','绑定 localhost/管理网并加防火墙，同时防代理错误转发。','调试 endpoint、metrics、pprof、JMX 和 Docker API 都可能泄露或提供高权限操作。'],['Prometheus metrics 有敏感信息吗？','localhost 服务能被浏览器访问吗？','SSRF 如何打内网管理面？'],'适用于微服务、中间件和 Agent 控制平面。','简单',['Management Plane','Defense in Depth'],'必背'),

  // 9. CI/CD 与供应链目标
  X('security','CI/CD目标','CI Workflow Injection 如何形成？','不可信 PR 标题、分支名、Issue 内容或提交消息被直接插入 Shell 脚本/表达式，Runner 执行时形成命令注入。',['把不可信上下文通过环境变量传递并在脚本内安全引用，不直接拼入 run。','`pull_request_target` 等高权限触发器不能 checkout/执行不可信 PR 代码。','最小化 GITHUB_TOKEN 权限，Fork PR 不提供生产 Secret。'],['表达式 `${{ }}` 何时展开？','自托管 Runner 风险？','Artifact 名称能注入吗？'],'适用于 GitHub Actions、GitLab CI 和企业流水线。','困难',['CI Injection','GitHub Actions'],'高压'),
  X('security','CI/CD目标','构建 Artifact 替换与投毒如何防？','攻击者若能覆盖、伪造或从不可信 Job 注入制品，后续签名/发布步骤可能把恶意产物当正式版本。',['Artifact 使用内容 hash、来源 Job/commit/Workflow identity 和不可变存储。','签名发生在隔离受信环境，并验证输入 provenance；不能只按文件名下载“latest”。','不同信任级流水线和缓存分开，清理自托管 Runner Workspace。'],['Cache Poisoning 与 Artifact Poisoning 区别？','构建后签名就安全吗？','如何做 provenance？'],'适用于软件发布、模型权重和 Agent Skill 分发。','困难',['Artifact Poisoning','Provenance'],'深挖'),
  X('security','CI/CD目标','自托管 CI Runner 为什么高风险？','它会执行仓库代码并长期接触宿主网络、缓存和凭证；恶意任务可持久化、横向移动或窃取后续 Job Secret。',['每个 Job 使用一次性 VM/容器并销毁，避免长期共享主机。','按仓库/信任等级隔离 Runner Group，Fork/外部贡献不进高权限 Runner。','限制网络、云身份、Docker Socket 与缓存写权限，检测异常进程和残留。'],['容器化 Runner 是否足够？','如何清理 Workspace？','Runner Token 泄露影响？'],'与 Coding Agent 执行不可信仓库的威胁模型高度相似。','困难',['CI Runner','Sandbox'],'必背'),
  X('security','供应链目标','Dependency Confusion 的根因是什么？','构建工具在公共仓库找到与私有包同名但更高版本的攻击包，并优先下载执行。',['私有包使用组织 scope/namespace，配置 registry 映射并阻止公共 fallback。','占位注册私有名称、锁定版本/hash并监控公共仓库同名包。','CI 安装脚本在构建阶段即可泄露 Secret，即使应用从未运行。'],['Typosquatting 有何区别？','内部包版本 0.0.1 为什么危险？','Python/npm/Maven 如何配置私库？'],'适用于 Python、Node、Java 和模型依赖供应链。','中等',['Dependency Confusion','Package Registry'],'必背'),
  X('security','供应链目标','模型、数据集和 Agent Skill 供应链有什么特殊风险？','权重可能包含恶意序列化对象，数据集可投毒，Skill/插件包含可执行脚本和 Prompt，下载源与版本必须验证。',['优先安全权重格式并禁不可信 pickle，校验 hash、签名、来源与 license。','数据/Skill 更新经过 Review、沙箱测试和行为评测，不自动获取 main/latest。','模型卡和 README 也是间接 Prompt Injection 来源，不能自动获得工具权限。'],['safetensors 解决什么？','数据投毒如何发现？','Skill 应如何签名？'],'安全与 Agent 技术栈的交叉目标。','困难',['Model Supply Chain','Skill Security'],'高压'),

  // 10. LLM / Agent 应用目标
  X('security','Agent目标','Excessive Agency 是什么？','Agent 被授予了超出任务所需的工具、权限、自动执行范围或自主决策，使模型错误/注入直接造成高影响副作用。',['缩小功能、资源和自治三个维度：只给必要工具、最小对象范围、高风险操作需确认。','优先只读和可撤销操作，区分 propose/execute 两阶段。','权限由宿主强制并与用户身份绑定，不能只在 Prompt 中说“谨慎”。'],['与普通越权区别？','Human-in-the-loop 是否足够？','怎样设计可撤销工具？'],'OWASP LLM 应用中与 Harness 权限设计最相关的风险。','困难',['Excessive Agency','Agent Security'],'高压'),
  X('security','Agent目标','Memory Poisoning 如何形成？','攻击者把错误事实、恶意指令或跨用户数据写入长期记忆，后续任务召回后持续影响决策。',['记忆写入需来源、作用域、信任、TTL、去重和审核，外部网页内容不能自动变长期规则。','召回时按用户/租户/项目隔离并标记为数据；高风险事实重新验证。','提供查看、纠正和删除记忆能力，保留变更 lineage。'],['RAG Poisoning 与 Memory Poisoning 区别？','摘要会放大污染吗？','如何检测长期后门？'],'AV 的 Canonical State 只接受 Reviewed Delta，正是防止会话提案污染真值。','困难',['Memory Poisoning','Persistent Attack'],'必背'),
  X('security','Agent目标','Tool Output Injection 是什么？','工具、网页或命令输出包含诱导模型改变行为的文本，Agent 把结果数据误当成可信指令。',['工具结果使用结构化 Envelope，标注来源/信任并只暴露所需字段。','高权限决策不依赖工具中的自然语言指令，调用前由策略引擎校验。','HTML/终端 ANSI/隐藏 Unicode 和注释都可承载注入。'],['如何测试间接注入？','结构化 JSON 能否完全防？','搜索结果摘要安全吗？'],'Coding Agent 读取恶意仓库时的核心威胁。','困难',['Tool Output Injection','Prompt Injection'],'高压'),
  X('security','Agent目标','Insecure Output Handling 为什么危险？','下游把 LLM 输出直接当 SQL、Shell、HTML、代码或配置执行，模型错误或注入可转化为传统漏洞。',['所有模型输出按不可信输入处理：Schema、allowlist、参数化、编码与沙箱。','生成代码先静态检查、测试和人工/策略 Review，再在隔离环境运行。','输出内容过滤不能替代执行层权限与最小副作用。'],['与 Prompt Injection 的关系？','生成 SQL 如何限制？','HTML Markdown 渲染有何风险？'],'Agent 安全必须落到传统安全 Sink。','简单',['Insecure Output Handling','LLM Security'],'必背'),
  X('security','Agent目标','Vector/Embedding Store 的跨租户风险是什么？','索引查询若缺少 tenant/filter、缓存键或删除同步，可能召回其他用户文档；Embedding 本身也可能泄露语义信息。',['在存储层强制 tenant namespace/metadata，而不是让模型生成过滤条件。','写入、检索、rerank、缓存和引用下载各层都带权限。','用户删除要传播到原文、向量、缓存、备份与长期记忆。'],['ANN 过滤会不会漏权限？','共享索引怎么隔离？','Embedding 能否反演？'],'适用于企业 RAG 与多租户知识库。','困难',['Vector DB Security','Multi-Tenant'],'必背'),
  X('security','Agent目标','Agent Denial of Service 有哪些形式？','超长上下文、递归委派、工具循环、压缩炸弹、慢网页、昂贵查询和并行 fan-out 会消耗 Token、GPU、进程、网络与人工审批。',['对输入大小、递归深度、并发、工具成本和返回体设置外部工程限制。','重复指纹和无进展检测终止循环；昂贵工具预估成本与排队。','AV 方法内部不向 Investigator暴露预算，但外部 Harness 仍实施墙钟、资源隔离和 operational interruption。'],['Prompt Bomb 是什么？','如何区分慢任务与循环？','限流应该在哪层？'],'区分科学方法无内部预算与平台必须防资源滥用。','困难',['Model DoS','Resource Exhaustion'],'高压'),
  X('security','Agent目标','Agent 身份与 Delegation 如何防 Confused Deputy？','Agent 代用户调用工具时必须携带原始主体、委派范围和目标资源，不能用 Agent 自身高权限替所有用户执行。',['采用 on-behalf-of/短期 scoped token，工具端重新校验 subject、action、resource。','Handoff 只传必要权限，后续 Agent 不自动继承全部凭证。','审计同时记录用户、Agent/Service、批准者和具体工具动作。'],['Service Account 与用户 Token 如何组合？','Delegation Chain 怎么验证？','Agent 能否自行申请权限？'],'适用于企业 Agent 平台、MCP Server 与多 Agent 协作。','困难',['Confused Deputy','Delegation'],'深挖'),

  // 11. 密码学与认证实现目标
  X('security','密码学目标','随机数使用错误会导致哪些漏洞？','可预测或重复的 Token、nonce、IV、密钥会破坏会话、重置链接、签名或加密安全。',['安全 Token 使用 CSPRNG 并具备足够熵，不用时间戳、递增 ID 或普通 PRNG。','AES-GCM/ChaCha20-Poly1305 的 nonce 在同一密钥下必须唯一，重复会泄露/伪造。','分布式系统生成 nonce 要考虑进程重启、计数持久化和多节点冲突。'],['UUID v4 适合 Token 吗？','IV 和 nonce 区别？','如何检测 nonce reuse？'],'适用于认证、设备协议和加密存储。','困难',['CSPRNG','Nonce Reuse'],'必背'),
  X('security','密码学目标','为什么不应该自创加密算法或协议？','密码学安全依赖经过公开分析的原语与组合；自创方案容易在 nonce、认证、填充、密钥派生和错误处理上失败。',['使用成熟 AEAD、TLS 和标准库，先做威胁模型与密钥生命周期。','加密不带认证会被篡改；MAC-then-encrypt 等组合顺序需遵循标准。','协议实现要处理版本、重放、降级、侧信道和密钥轮换。'],['AES 模式如何选？','Hash 能替代 MAC 吗？','Base64 是加密吗？'],'通用安全设计基础。','简单',['Cryptography','AEAD'],'必背'),
  X('security','密码学目标','硬编码加密密钥和“客户端加密”有什么问题？','攻击者能获得客户端/固件/代码时也能提取同一密钥，无法建立对客户端攻击者的秘密边界。',['密钥应由服务端 KMS、设备安全硬件或用户口令 KDF 派生，并支持每设备/每租户隔离。','混淆只能提高逆向成本，不改变密钥在运行时必须可用的事实。','评估目标要区分防数据库泄露、网络攻击者、设备拥有者和恶意客户端。'],['白盒密码能解决吗？','密钥分片是什么？','移动端 Keystore 的边界？'],'适用于 App、固件、桌面和 SDK。','中等',['Hardcoded Key','Key Management'],'必背'),
  X('security','密码学目标','TLS 证书校验常见实现错误有哪些？','禁用校验、信任所有证书、只验证链不验证 hostname、错误自签名处理和过期 pin 会使 MITM 成立。',['客户端使用系统信任库并校验 hostname、用途和有效期。','证书 Pinning 需要备份 key、轮换和失效方案，否则容易把正常更新变成故障。','开发环境跳过校验不能进入生产构建，配置与日志需可审计。'],['IP 地址证书如何校验？','Pin 公钥还是证书？','mTLS 解决什么？'],'适用于移动、IoT、Agent Provider 与内部服务。','中等',['TLS Validation','Certificate Pinning'],'必背')
);

