/* 参考小林 coding 等面经目录补齐的计算机基础题。答案均重新组织，按简单/中等/困难排序。 */
QUESTIONS.push(
  // 网络：从一条请求、TCP 状态到 Linux 数据路径
  X('network','网络全链路','浏览器输入 URL 到页面显示，完整链路是什么？','URL 解析与缓存检查后，经 DNS、建连/TLS、HTTP 请求、服务端处理和浏览器解析渲染完成；每一层都可能被缓存或复用。',['先解析 scheme/host/port/path，检查 HSTS、Service Worker、浏览器与系统缓存。','DNS 得到地址后选择路由；TCP 三次握手，HTTPS 再完成 TLS 握手，HTTP/2 或 HTTP/3 可复用已有连接。','响应到达后解析 HTML，构建 DOM/CSSOM、执行脚本、生成布局与绘制；子资源会继续触发请求。'],['DNS 一定发生吗？','HTTP/3 还需要 TCP 吗？','首屏慢怎么分层定位？'],'适合作为网络综合题，也能联系 Agent Web 工具的超时诊断。','简单',['URL','浏览器','全链路'],'必背'),
  X('network','HTTP','HTTP Keep-Alive 与 TCP Keepalive 有什么区别？','HTTP Keep-Alive 是应用层复用连接；TCP keepalive 是长时间空闲后探测对端是否仍存活。',['HTTP/1.1 默认持久连接，多个请求可顺序复用；HTTP/2 可在一条连接上并发多路流。','TCP keepalive 由内核定时发送探测包，参数通常很长，主要清理半死连接，不保证应用健康。','业务心跳能携带语义并采用更短超时，和两者目的又不同。'],['负载均衡空闲超时影响什么？','长连接为何还要业务心跳？','HTTP/1.1 能真正并发吗？'],'适用于长轮询、SSE、WebSocket 和 Agent 流式调用。','简单',['Keep-Alive','长连接'],'必背'),
  X('network','IP与NAT','NAT 为什么存在，常见类型和问题是什么？','NAT 用地址与端口映射让私网主机共享公网地址，也带来端到端可达性、状态表和超时问题。',['SNAT 改源地址用于出网，DNAT/端口映射改目标地址用于入站；NAPT 还利用端口区分连接。','映射依赖五元组与状态表，长时间空闲可能被回收；P2P 常用 STUN/TURN/ICE 穿透。','NAT 不等于防火墙：它可能降低直接可达性，但不能替代显式访问控制。'],['CGNAT 有什么影响？','IPv6 是否完全不需要 NAT？','连接追踪表满会怎样？'],'适用于云网络、容器网络和反向连接排障。','简单',['NAT','IP'],'常规'),
  X('network','诊断工具','ping 能证明什么，不能证明什么？','ping 只证明特定时刻 ICMP Echo 路径可达和往返时间；它不能证明 TCP 端口、应用或业务健康。',['ICMP 可能被禁或限速，因此 ping 失败不等于目标不可达，成功也不等于服务可用。','traceroute 利用 TTL 递减和 ICMP 超时观察路径，但不同包可能走不同 ECMP 路径。','排障要结合 DNS、路由、ARP/ND、端口握手、TLS、HTTP 状态与应用指标。'],['ping localhost 经过网卡吗？','TTL 有什么作用？','如何定位丢包发生在哪层？'],'适用于现场排障题，强调证据边界。','简单',['ping','ICMP','诊断'],'必背'),
  X('network','HTTPS','HTTPS 使用 RSA 握手与 ECDHE 握手有什么关键差异？','旧式 RSA 密钥交换由客户端加密预主密钥，不具前向安全；现代 ECDHE 双方协商临时共享密钥并由证书私钥签名认证。',['证书主要把公钥与身份绑定；对称会话密钥由握手派生，数据阶段使用 AEAD。','ECDHE 临时私钥销毁后，即使服务器长期私钥未来泄露，历史抓包也难被解密。','TLS 1.3 移除了静态 RSA 密钥交换并缩短握手；0-RTT 数据存在重放风险。'],['证书加密了什么？','为什么不全程用非对称加密？','会话恢复怎样工作？'],'模型 Provider、MCP 与招聘数据源都依赖正确 TLS 验证。','中等',['TLS','ECDHE','前向安全'],'必背'),
  X('network','TCP队列','TCP 半连接队列和全连接队列分别保存什么？','半连接队列保存收到 SYN、处于 SYN_RECV 的握手；全连接队列保存握手完成但尚未被应用 accept 的连接。',['listen 的 backlog、内核上限和实现共同影响队列容量；应用 accept 太慢主要压满全连接队列。','SYN Flood 主要消耗半连接状态，SYN Cookie 可在不保存完整状态时验证最终 ACK，但有功能取舍。','应结合 ListenOverflows、ListenDrops、SYN_RECV 数和应用 accept 延迟定位。'],['队列满时客户端看到什么？','SYN Cookie 原理？','backlog 越大越好吗？'],'适用于高并发服务和网络 DoS 分析。','中等',['TCP队列','listen','SYN Flood'],'高压'),
  X('network','Socket','listen 与 accept 的真实行为是什么？','listen 把 Socket 变为被动监听并建立连接队列；内核完成握手，accept 只是取出一个已连接 Socket。',['监听 Socket 与连接 Socket 不同：前者按本地地址等待，后者包含完整四元组并独立收发。','accept 阻塞表示全连接队列当前为空，不代表没有半连接；非阻塞模式返回 EAGAIN。','多进程可共享监听描述符，需考虑惊群、SO_REUSEPORT 与负载分配。'],['accept 后三次握手才完成吗？','一个端口能有多少连接？','close 监听 Socket 会怎样？'],'适用于 Python/Java 网络服务底层追问。','中等',['Socket','accept'],'必背'),
  X('network','TCP状态','TIME_WAIT 为什么通常由主动关闭方进入，为什么要等待 2MSL？','主动关闭方发送最后 ACK 后保留状态，以便重传 ACK，并让旧连接报文在网络中过期，避免污染同四元组新连接。',['被动方重传 FIN 时，TIME_WAIT 一方还能再次回复 ACK；等待覆盖报文最大生存周期的往返。','大量短连接会消耗端口和状态，应优先连接复用、合理架构和端口范围，而不是粗暴禁用。','SO_REUSEADDR、tw_reuse 的语义和系统版本有关，不能作为通用安全答案。'],['CLOSE_WAIT 过多意味着什么？','服务器也会出现 TIME_WAIT 吗？','为什么是 2MSL？'],'适用于 HTTP 客户端、扫描器和 Agent 工具连接池。','中等',['TIME_WAIT','四次挥手'],'必背'),
  X('network','TCP异常','对端进程崩溃、主机断电和网线拔掉，TCP 表现有何不同？','正常进程退出通常发送 FIN；异常进程若内核仍在会发 RST/FIN；主机失联则没有报文，只能靠重传超时、keepalive 或业务心跳发现。',['进程被 kill 后内核负责关闭 Socket；若收到发往不存在连接的报文通常回复 RST。','主机断电或路径中断时，本端已发送数据会指数退避重传，最终超时；空闲连接可能长期不感知。','网线恢复前未超时且连接状态未丢失时可能继续使用，但 NAT/LB 映射可能已经消失。'],['write 成功是否代表对端应用收到？','RST 与 FIN 区别？','如何设置故障检测时间？'],'用于解释 Agent Runner 断连、流式 API 中断和可靠重试。','中等',['TCP故障','RST','超时'],'深挖'),
  X('network','TCP序号','TCP 初始序列号 ISN 为什么不能固定？','ISN 需要随连接和时间变化，既避免旧报文混入新连接，也降低伪造序列号进行注入或劫持的风险。',['TCP 字节流中的 SYN 和 FIN 都消耗一个序列号；ACK 表示下一个期望字节。','现代系统用带秘密的哈希结合四元组和时钟生成难预测 ISN，同时保持单连接内单调。','安全性还依赖窗口范围、随机端口及上层 TLS，不能只靠 ISN。'],['序列号为什么会回绕？','ACK 号如何计算？','抓包怎样判断重传？'],'适合从协议正确性连接到网络安全。','中等',['ISN','序列号'],'深挖'),
  X('network','TCP状态','TIME_WAIT 状态收到同四元组 SYN 会发生什么？','行为取决于序列号、时间戳、系统实现和是否允许复用；核心原则是不能让旧报文被新连接误收。',['若新 SYN 被判断为旧连接的重传或不安全，内核会丢弃或响应旧状态；满足安全条件时可能允许新连接。','RFC 与 Linux 版本细节可能变化，面试应先讲安全不变量，再说明需要看内核实现和 sysctl。','客户端临时端口耗尽时通常通过连接池、多源地址和端口范围解决。'],['为什么不能简单删除 TIME_WAIT？','PAWS 是什么？','四元组中哪一项改变即可不冲突？'],'训练回答“原则 + 版本边界”，避免背单一包序列。','困难',['TIME_WAIT','PAWS','内核实现'],'深挖'),
  X('network','TCP乱序','如果 FIN 比前面的数据先到达，TCP 会立即关闭吗？','FIN 也占序列空间；只有它之前的字节都按序到达后，接收端才能把 EOF 交给应用。',['乱序 FIN 会先放在重组队列，ACK 仍指向缺失的下一个字节，并可能触发重复 ACK。','缺失段重传到达后，连续字节和 FIN 才一起推进接收序号，应用先读完数据再看到 EOF。','这体现 TCP 提供有序字节流，而不是按 IP 包到达顺序交付。'],['RST 会等待乱序数据吗？','FIN 能携带数据吗？','半关闭是什么？'],'适用于深入解释 TCP 可靠性。','困难',['FIN','乱序','重组队列'],'深挖'),
  X('network','Linux网络','Linux 接收一个网络包的大致路径是什么？','网卡 DMA 写入 Ring Buffer，NAPI/软中断轮询收包，经协议栈校验、路由和 Socket 匹配后进入接收队列，应用再通过系统调用读取。',['硬中断通常只调度 NAPI，批量 poll 把报文构造成 skb，减少高包速下的中断风暴。','报文依次经过链路层、IP、TCP/UDP 及 Netfilter 等处理，最终按四元组找到 Socket。','应用 read 是从 Socket Buffer 复制到用户空间；阻塞唤醒、调度和复制都会影响延迟。'],['NAPI 为什么能缓解活锁？','skb 是什么？','XDP 在哪里执行？'],'可联系高性能扫描器、代理和容器网络。','困难',['Linux收包','NAPI','软中断'],'高压'),
  X('network','Linux网络','Linux 发送一个网络包的大致路径是什么？','应用写入 Socket 后，协议栈分段和封装、查路由与邻居表，进入 qdisc 和驱动队列，网卡 DMA 取走并发送。',['TCP 先进入发送缓冲并按拥塞窗口、接收窗口和 MSS 决定可发送量；GSO/TSO 可把分段下放。','IP 层选择路由和源地址，ARP/ND 解析下一跳 MAC；qdisc 负责排队与整形。','send 返回通常只表示数据进入本机缓冲，不代表已到对端，更不代表对端应用处理完成。'],['send buffer 满会怎样？','零拷贝 sendfile 省了什么？','qdisc 有什么作用？'],'适合解释吞吐、背压与端到端确认。','困难',['Linux发包','TSO','背压'],'深挖'),
  X('network','HTTP优化','HTTP 性能优化应从哪些维度入手？','先减少请求关键路径和传输字节，再提高连接复用与缓存命中，最后针对服务器、协议和网络路径优化。',['内容层使用压缩、图片适配、代码拆分与资源优先级；缓存层设计 Cache-Control、ETag、CDN 和版本化资源。','连接层启用 TLS 会话恢复、HTTP/2 多路复用或 HTTP/3，并避免过多域名造成连接分散。','必须用 RUM、Trace 和 LCP/TTFB 等测量，HTTP/2 并不自动解决服务器慢或带宽不足。'],['HTTP/2 队头阻塞在哪里？','预加载何时适得其反？','动态 API 如何缓存？'],'适用于网站、API Gateway 和模型流式响应优化。','中等',['HTTP性能','缓存','HTTP2'],'必背'),
  X('network','TCP优化','TCP 性能调优为什么不能只把缓冲区调大？','吞吐受带宽时延积、拥塞控制、接收窗口、丢包、应用读写和中间设备共同限制；大缓冲还可能造成 Bufferbloat。',['长肥网络需足够窗口并启用窗口扩大；高丢包环境关注拥塞算法、重传和路径 MTU。','连接建立成本可用复用和 TLS 恢复减少，短请求还受慢启动影响。','调优前看 RTT、吞吐、重传、cwnd、rwnd、队列时延和 CPU，按瓶颈验证。'],['BDP 怎么计算？','BBR 与 CUBIC 思路差异？','什么是 Bufferbloat？'],'训练从指标到机制而非背 sysctl。','困难',['TCP优化','拥塞控制','BDP'],'高压'),
  X('network','DNS','DNS 解析链路、缓存与常见安全问题是什么？','Stub Resolver 询问递归解析器，后者按根、顶级域和权威服务器迭代查询并按 TTL 缓存；污染、劫持和错误缓存会影响所有后续连接。',['浏览器、系统、递归解析器和权威侧都可能缓存；负缓存也有 TTL。','CNAME 用于别名，最终仍需 A/AAAA；递归与迭代查询职责不同。','DNSSEC 验证数据来源与完整性但不加密查询；DoH/DoT 加密传输但不自动保证权威数据正确。'],['DNS 轮询能做负载均衡吗？','TTL 越小越好吗？','缓存穿透如何处理？'],'适用于服务发现、CDN、SSRF DNS Rebinding 分析。','中等',['DNS','缓存','DNSSEC'],'必背'),
  X('network','网络指标','排查网络性能应关注哪些指标，如何建立因果链？','至少同时看吞吐、RTT/分位延迟、丢包/重传、连接状态、队列、错误和应用等待，并用跨层时间线定位瓶颈。',['接口层看 PPS/BPS、drop/error；TCP 看 retrans、RTT、cwnd、listen queue；Socket 看 buffer 和连接状态。','应用层看 DNS、connect、TLS、TTFB、下载和服务内部 Trace，避免把服务端慢误判为网络慢。','平均值会掩盖长尾，应看 p95/p99 和按机房、运营商、版本分组。'],['高 RTT 一定是网络问题吗？','如何用 ss/tcpdump 定位？','抓包会改变性能吗？'],'适用于面试中的线上故障复盘。','困难',['网络指标','可观测性'],'必背'),

  // 操作系统：执行、内存、文件与 I/O 模型
  X('os','程序执行','CPU 是怎样执行一个程序的？','可执行文件被加载映射成进程地址空间，CPU 按取指、译码、执行循环运行指令，操作系统通过异常、系统调用和中断提供受保护服务。',['编译链接产生机器码与元数据；Loader 建立代码、数据、堆、栈及动态库映射并设置入口。','指令通过 PC 取到流水线，寄存器和 Cache 提供操作数；缺页、除零等异常进入内核。','调度器保存当前上下文并恢复另一个线程，形成并发执行。'],['静态链接与动态链接区别？','用户态如何进入内核态？','上下文切换保存什么？'],'作为 OS 与计组的总览题。','简单',['程序执行','CPU','进程'],'必背'),
  X('os','内存分配','malloc 一定会立刻向操作系统申请物理内存吗？','不一定；分配器先复用用户态 Arena/空闲块，必要时用 brk 或 mmap 扩展虚拟地址，物理页常在首次访问缺页时才分配。',['小块常来自堆和 size class，大块可能独立 mmap；具体阈值属于实现细节。','free 通常只归还给分配器，未必立即归还 OS；碎片会造成 RSS 居高。','虚拟内存承诺、overcommit 和实际物理页是三层不同概念。'],['calloc 为什么可能看起来很快？','内存碎片分哪两类？','RSS 与 VSZ 区别？'],'适用于 C/C++、Python Runtime 和容器内存题。','中等',['malloc','虚拟内存'],'必背'),
  X('os','内存管理','系统内存不足时 Linux 大致怎样回收，何时触发 OOM？','内核先回收页缓存和匿名页、回写脏页或交换；若在约束范围内仍无法满足分配，就由 OOM Killer 选择进程终止。',['回收分 direct reclaim 与后台 kswapd；匿名页通常需 swap 才能回收，文件页可丢弃或回写。','脏页太多会阻塞写回；频繁换入换出形成 thrashing，延迟可先于 OOM 恶化。','容器 memcg OOM 只在 cgroup 范围选择牺牲者，与主机全局 OOM 不同。'],['OOM score 如何影响选择？','没有 swap 会怎样？','为什么还有 available 内存却 OOM？'],'适用于 Runner 沙箱和大模型/构建任务资源隔离。','困难',['内存回收','OOM','cgroup'],'高压'),
  X('os','进程线程','进程与线程的核心区别是什么？','进程是资源与隔离单位，线程是 CPU 调度和执行流单位；同进程线程共享地址空间与多数资源，但有独立栈、寄存器和调度状态。',['共享内存让线程通信快，但数据竞争和一个非法内存写可能破坏整个进程。','多进程隔离更强、故障边界更清晰，但通信与创建成本通常更高。','现代系统中线程切换成本还取决于地址空间、Cache/TLB 命中和调度位置。'],['线程一定比进程轻吗？','协程与线程区别？','线程共享哪些、不共享哪些？'],'适用于 Agent 并发、Worker 隔离与服务架构。','简单',['进程','线程'],'必背'),
  X('os','故障边界','一个线程崩溃会影响同进程其他线程吗？','未被处理的致命信号通常终止整个进程；因为线程共享地址空间，内存破坏即使未立即退出也可能污染其他线程。',['栈溢出、SIGSEGV、abort 等默认动作通常是进程终止，具体信号可安装 handler 但恢复不一定安全。','语言 Runtime 级异常可能只终止当前线程，例如 Java 未捕获异常，前提是没有破坏进程级状态。','强隔离故障任务应使用进程/容器，而不是只开线程。'],['Java 线程 OOM 会怎样？','信号是发给线程还是进程？','为什么 Crash handler 不等于可恢复？'],'适用于分析 Native 工具、Parser 和 Runner 的隔离边界。','中等',['线程崩溃','信号','隔离'],'深挖'),
  X('os','IPC','常见进程间通信方式如何选择？','管道适合字节流与亲缘进程，Socket 通用且可跨机，共享内存性能高但需同步，消息队列提供边界和异步语义。',['匿名管道单机且生命周期简单，命名管道扩展到无亲缘进程；Unix Domain Socket 保留消息/凭证能力。','共享内存避免数据复制但要用锁、信号量或无锁协议保证一致性，崩溃恢复也更复杂。','RPC 是更高层抽象，还要考虑序列化、超时、重试、幂等和版本。'],['mmap 算 IPC 吗？','Socketpair 有何用途？','共享内存一定零拷贝吗？'],'适用于 Harness 与 Runner/Sidecar 通信设计。','中等',['IPC','共享内存','Socket'],'必背'),
  X('os','调度','常见 CPU 调度算法和指标有哪些？','关注周转时间、响应时间、吞吐、公平和截止期；FCFS、短作业优先、时间片轮转、多级反馈队列各有不同取舍。',['交互系统重响应，批处理重吞吐和周转，实时系统重可预测截止期。','短作业优先平均周转小但需估计长度且可能饥饿；Round Robin 的时间片过小增加切换开销。','Linux CFS 思想是按虚拟运行时间公平分配，实时类另有更高优先级策略。'],['优先级反转是什么？','CFS 是严格 Round Robin 吗？','CPU 密集与 I/O 密集如何兼顾？'],'适用于资源调度和 Agent Task Queue 类比。','中等',['调度','CFS'],'常规'),
  X('os','页面置换','页面置换算法有哪些，为什么实际系统不能实现真正 LRU？','OPT 是理论下界，FIFO 简单但可能 Belady 异常，LRU 利用局部性；精确记录每次访问成本太高，系统用 Clock/近似 LRU。',['页表硬件通常只提供 accessed/dirty 等有限信息，内核周期采样维护冷热近似。','工作集超过物理内存会频繁缺页；增加进程数反而可能降低吞吐。','算法还要区分匿名页、文件页、脏页和 memcg 公平性。'],['什么是 Belady 异常？','Clock 如何工作？','缺页都要读磁盘吗？'],'连接虚拟内存原理与性能问题。','中等',['页面置换','LRU','Clock'],'必背'),
  X('os','磁盘调度','磁盘调度算法为什么在 SSD 时代仍需理解？','机械盘需减少寻道，FCFS、SSTF、SCAN/C-SCAN体现吞吐与公平取舍；SSD 无机械寻道但仍有队列、并行度、写放大和尾延迟管理。',['SSTF 可能让远端请求饥饿，SCAN 像电梯往返，C-SCAN 提供更均匀等待。','现代块层调度还要合并请求、控制队列深度、区分延迟敏感 I/O 与后台 I/O。','NVMe 多队列降低锁竞争并利用设备并行，但过深队列可能增加延迟。'],['SSD 为什么随机读更快？','I/O scheduler 可以关闭吗？','队列深度如何影响吞吐？'],'适用于存储系统与日志数据库性能题。','中等',['磁盘调度','NVMe'],'常规'),
  X('os','文件系统','一次文件读写经过哪些缓存与结构？','路径先通过目录项和 inode 查找，数据通常经 Page Cache；读缺页触发块 I/O，写先变成脏页后由回写机制落盘。',['文件描述符指向 open file description，保存偏移和 flags；inode 保存元数据与块映射。','read/write 默认在用户缓冲和 Page Cache 之间复制；mmap 通过缺页把同一缓存页映射进进程。','write 返回不代表持久化，崩溃一致性还需 fsync、日志和正确写入顺序。'],['inode 与目录项区别？','删除打开文件会怎样？','fsync 文件后目录一定持久吗？'],'适用于数据库 WAL、Artifact 写入和 Exactly-once 提交。','困难',['文件系统','inode','Page Cache'],'必背'),
  X('os','Page Cache','Page Cache 有什么价值和陷阱？','它用空闲内存缓存文件页、合并读写并提供 mmap 一致视图，但会造成双缓存、脏页尖峰和容器内存观测误解。',['顺序读可触发 readahead，重复读命中内存；写回缓存把小写合并但持久化延迟。','数据库可能用 Direct I/O 管理自己的 Buffer Pool，避免双缓存并控制刷盘顺序。','Linux 的 available 会估计可回收缓存，不能把 free 很小直接等同于内存不足。'],['drop_caches 适合优化吗？','mmap 与 read 是否共享缓存？','容器 Page Cache 计费给谁？'],'适用于数据库和大仓库扫描性能。','中等',['Page Cache','Direct IO'],'必背'),
  X('os','零拷贝','零拷贝到底减少了什么？','零拷贝通常减少用户态与内核态之间的数据复制和上下文切换，并不意味着整个链路没有任何 DMA 或内核操作。',['传统 read+write 数据经历磁盘到 Page Cache、复制到用户缓冲、再复制到 Socket Buffer。','sendfile 可在内核中把文件页交给 Socket；splice 在管道缓冲之间移动引用；mmap 省一次复制但仍需系统调用发送。','TLS、内容变换和跨设备路径会限制零拷贝，收益要用 CPU 与吞吐测量。'],['DMA 算不算拷贝？','Java transferTo 对应什么？','TLS 为什么影响 sendfile？'],'适用于静态文件服务和大 Artifact 传输。','困难',['零拷贝','sendfile','DMA'],'深挖'),
  X('os','I/O模型','阻塞、非阻塞、I/O 多路复用与异步 I/O 如何区别？','阻塞描述调用是否等待；多路复用让一个线程等待多个就绪事件；异步 I/O 则由内核完成操作后通知结果。',['非阻塞 read 在无数据时立即 EAGAIN，但仍需轮询或 readiness 通知。','select/poll/epoll 通知“可以尝试读写”，实际 read/write 仍由应用执行，因此常称同步 I/O。','真正异步接口提交操作后取得 completion；工程上还需处理部分读写、背压和取消。'],['epoll 是异步 I/O 吗？','水平触发与边缘触发区别？','文件 I/O 能用 epoll 吗？'],'适用于高并发服务和 Agent event loop。','中等',['IO模型','epoll','AIO'],'必背'),
  X('os','事件模型','Reactor 与 Proactor 的区别是什么？','Reactor 对“就绪事件”分发，Handler 自己执行 I/O；Proactor 提交异步操作并对“完成事件”分发结果。',['Reactor 常基于 epoll/kqueue，流程是等待可读→read→处理；必须循环读到 EAGAIN 才适合 ET。','Proactor 常基于 IOCP、io_uring/AIO 的完成语义，流程是提交 read→完成通知→处理结果。','真实框架可能混合两者，名称不如底层通知语义重要。'],['Node.js 属于哪种？','io_uring 一定是 Proactor 吗？','Handler 阻塞会怎样？'],'适用于事件驱动框架与高并发设计题。','困难',['Reactor','Proactor','事件循环'],'高压'),
  X('os','软中断','硬中断、软中断和系统调用有什么区别？','硬中断由设备异步触发，软中断用于延后批量内核工作，系统调用由当前线程同步请求内核服务。',['硬中断上下文要尽快返回，网卡常只确认并调度 NAPI；网络处理大量发生在 NET_RX softirq。','软中断可在中断返回或 ksoftirqd 执行，负载过高会占用 CPU 并增加应用调度延迟。','系统调用保留进程上下文，通常可以阻塞；中断上下文限制更多。'],['softirq 与 tasklet/workqueue 区别？','为什么 ksoftirqd 占满 CPU？','中断亲和性有什么用？'],'连接 Linux 网络包路径与性能观测。','困难',['软中断','中断','系统调用'],'深挖'),
  X('os','容器隔离','Namespace、cgroup 与容器镜像分别解决什么？','Namespace 隔离资源视图，cgroup 限制和统计资源，镜像提供文件系统内容；容器仍共享宿主内核。',['PID、mount、network、user 等 Namespace 形成不同视图，但不是完整安全边界。','cgroup v2 以统一层级管理 CPU、内存、I/O 和进程数；限制会表现为 throttle 或 memcg OOM。','能力、seccomp、LSM、只读文件系统与 rootless 等共同缩小攻击面。'],['容器与 VM 区别？','user namespace 如何帮助 rootless？','CPU quota 为什么导致延迟尖峰？'],'适用于 Coding Agent 沙箱和不可信工具执行。','中等',['Namespace','cgroup','容器'],'必背'),
  X('os','死锁','死锁四个必要条件是什么，工程上如何避免？','互斥、占有且等待、不可抢占、循环等待同时成立才会死锁；破坏任一条件即可预防。',['最常用是全局锁顺序、缩小临界区、一次获取所需资源或 try-lock + 超时回退。','检测可用等待图；恢复可能杀进程、回滚事务或撤销资源。','活锁是不断行动却无进展，饥饿是长期得不到资源，三者不要混淆。'],['数据库死锁如何处理？','递归锁能解决吗？','超时是否等于根治？'],'适用于并发代码、数据库事务和多 Agent 资源租约。','简单',['死锁','锁顺序'],'必背'),

  // 计算机组成：缓存、浮点数与内存模型
  X('computer','存储层次','为什么需要寄存器、Cache、内存和磁盘的存储层次？','速度、容量和成本无法同时最优，系统利用时间与空间局部性，用小而快的层缓存大而慢的层。',['Cache 以 Cache Line 为单位，命中直接访问，未命中向下一层取数并可能替换。','L1/L2 常每核私有，LLC 可能共享；TLB 则缓存虚拟地址到物理地址的翻译。','顺序访问、数据布局和工作集大小会显著影响命中率。'],['Cache 和 TLB 区别？','局部性有哪些？','为什么链表常比数组慢？'],'适用于性能优化和数据结构取舍。','简单',['存储层次','Cache','局部性'],'必背'),
  X('computer','缓存一致性','MESI 协议解决什么问题？','MESI 用 Modified、Exclusive、Shared、Invalid 状态协调多核私有 Cache 中同一缓存行的副本，使写入获得独占所有权并使其他副本失效。',['读未命中可得到 Shared 或 Exclusive；写 Shared 行先发送 invalidate，Modified 行回写后才能被其他核获取。','一致性保证单地址的可见副本关系，不自动提供程序所需的原子性和顺序性。','伪共享是不同变量落在同一 Cache Line，频繁写导致所有权来回迁移。'],['MESI 与内存一致性模型区别？','什么是 Store Buffer？','如何避免伪共享？'],'适用于无锁编程、JMM 和多线程性能。','困难',['MESI','缓存一致性','伪共享'],'高压'),
  X('computer','浮点数','为什么 0.1 + 0.2 往往不等于 0.3？','IEEE 754 二进制浮点只能有限表示分数，多数十进制小数会被舍入，运算再次舍入后产生误差。',['浮点由符号、指数和尾数组成，存在规范数、非规范数、Infinity 和 NaN。','比较应按业务选择绝对/相对误差，金融精确小数使用定点整数或十进制类型。','运算顺序会影响舍入和结合律，不能假设浮点加法严格满足数学规律。'],['NaN 与任何值比较结果？','为什么浮点范围大但精度有限？','Kahan 求和是什么？'],'适用于算法、计费和数值程序安全。','简单',['IEEE754','浮点数'],'必背'),
  X('computer','虚拟地址','TLB、页表和 Cache 在一次内存访问中如何协作？','CPU 先用 TLB 缓存完成虚拟到物理地址翻译，再用物理地址访问 Cache；TLB miss 才执行页表遍历，页不在内存则触发缺页。',['多级页表节省稀疏地址空间的表内存，页表项含权限、present、dirty 等位。','大页减少 TLB 压力但增加内部碎片和回收迁移成本。','上下文切换时 ASID/PCID 可减少 TLB 全量刷新。'],['TLB miss 一定陷入内核吗？','缺页分哪几类？','VIPT Cache 是什么？'],'将 OS 虚拟内存与硬件路径串起来。','困难',['TLB','页表','Cache'],'深挖'),
  X('computer','CPU流水线','CPU 流水线为什么会停顿，乱序执行怎样提高性能？','数据依赖、控制分支和访存未命中会造成停顿；乱序核心在保持架构语义的前提下，让独立指令先执行并最终按序提交。',['分支预测错会清空错误路径，深流水线惩罚更大；投机结果在提交前不能改变架构状态。','寄存器重命名消除 WAR/WAW 假依赖，ROB 保证按序退休和精确异常。','内存墙使 Cache miss 常比算术指令昂贵，预取和并行未命中很重要。'],['乱序是否改变单线程结果？','RAW/WAR/WAW 区别？','Spectre 利用了什么？'],'适用于性能和微架构安全交叉题。','困难',['流水线','乱序执行','分支预测'],'深挖'),
  X('computer','内存模型','volatile、原子操作和内存屏障分别解决什么？','volatile 主要约束编译器访问并不等于线程同步；原子操作保证不可分割更新；内存屏障约束前后内存操作的可见顺序。',['不同语言语义不同：Java volatile 还建立 happens-before，而 C volatile 不提供跨线程原子性。','CAS 可构造无锁结构但会有 ABA、重试争用和内存回收问题。','Acquire/Release 建立跨线程发布关系，Seq_Cst 还提供更强全局顺序。'],['CAS 为什么会 ABA？','x86 是否不需要屏障？','Java synchronized 与 volatile 区别？'],'适用于 Runtime、并发队列和 CAS 状态提交。','困难',['内存模型','CAS','屏障'],'高压'),

  // MySQL / Redis 缺口
  X('backend','MySQL存储','InnoDB 行记录格式包含什么，为什么一行不能无限大？','行由变长字段长度、NULL 标记、记录头和实际列数据组成；页大小、行内存储上限及溢出页策略共同限制单行。',['COMPACT/DYNAMIC 等格式会把长 VARCHAR、BLOB/TEXT 的部分或大部分放到溢出页，行内保存指针。','隐藏列包括事务 ID、回滚指针，若无合适主键还可能生成隐藏行 ID。','宽行会降低每页记录数、增加随机 I/O 与回表成本，建模时不应只看语法允许长度。'],['VARCHAR 最大长度为何不是固定 65535？','NULL 是否占空间？','DYNAMIC 与 COMPACT 差异？'],'适用于数据库表设计和源码审计数据边界。','中等',['InnoDB','行格式'],'深挖'),
  X('backend','MySQL索引','InnoDB 数据页和 B+ 树如何组织索引？','B+ 树每个节点对应固定大小页，非叶页保存键与子页指针，叶页有序并通过链表相连；聚簇索引叶页就是完整行。',['高扇出使树通常很矮；页目录支持页内二分定位记录，顺序范围查询沿叶链扫描。','二级索引叶页保存索引列和主键，取其他列需回聚簇索引，覆盖索引可避免回表。','随机主键会导致页分裂和低填充，递增主键利于追加但可能形成写热点。'],['为什么不用二叉树？','页分裂怎样发生？','二级索引为什么存主键？'],'适合从结构解释索引优化而不是背口诀。','中等',['B+树','数据页','聚簇索引'],'必背'),
  X('backend','MySQL查询','count(*)、count(1) 与 count(列) 有什么区别？','count(*) 与 count(1) 都统计行，优化器通常选择成本低的索引扫描；count(列) 只统计该列非 NULL 的行。',['InnoDB MVCC 下不能像 MyISAM 那样长期保存所有快照都准确的总行数，通常需要扫描可见记录。','具体执行计划取决于版本、索引和谓词，不应声称 count(1) 永远更快。','高频近似总数可用统计表/缓存，但要明确一致性和更新策略。'],['为什么 information_schema 行数不精确？','带 where 如何优化？','删除很多行后 count 会变快吗？'],'常见面经纠错题。','简单',['count','SQL'],'必背'),
  X('backend','MySQL缓存','Buffer Pool 内部解决什么问题？','Buffer Pool 缓存 InnoDB 数据页和索引页，用页哈希、LRU 变体、Free/Flush List 与后台刷脏协调读写性能和持久化。',['读先查缓存，未命中从磁盘载入；修改先改缓存页并写 redo，脏页稍后刷回数据文件。','LRU 常区分新老区，避免一次全表扫描污染热点；Change Buffer 等机制取决于页类型和版本。','命中率高不代表无瓶颈，还要看脏页比例、等待、刷盘、checkpoint 与 working set。'],['Buffer Pool 与 Query Cache 区别？','脏页何时刷？','为什么数据库重启后会变慢？'],'适用于数据库性能与 WAL 持久化追问。','困难',['Buffer Pool','LRU','脏页'],'高压'),
  X('backend','Redis高可用','Redis Sentinel 提供了什么，不能提供什么？','Sentinel 监控主从、通过主观/客观下线判断和多数派选举执行故障转移，并把新主地址通知客户端；它不提供数据分片。',['多个 Sentinel 独立探测，达到 quorum 才客观下线；获得多数授权的 Sentinel Leader 执行 failover。','选择新主会考虑复制状态、优先级和偏移，随后让其他副本跟随并重配置旧主。','异步复制意味着故障时仍可能丢失已确认写，网络分区也需考虑脑裂与写入限制。'],['quorum 与 majority 区别？','Sentinel 自身怎样发现？','与 Redis Cluster 区别？'],'适用于高可用系统设计。','中等',['Redis Sentinel','故障转移'],'必背'),
  X('backend','Redis复制','Redis 主从复制的全量与增量流程是什么？','副本用 replication ID 和 offset 请求续传；积压缓冲覆盖缺口时做部分重同步，否则主节点生成快照完成全量同步，再持续发送命令流。',['全量同步期间主节点还要缓存新写，副本载入 RDB 后再重放缓冲命令，可能造成 CPU、内存和网络峰值。','复制 backlog 是环形缓冲，断线时间过长或写入过快会覆盖所需 offset。','Redis 复制默认异步，WAIT 只能提高副本确认程度，不等同于强一致提交。'],['无盘复制是什么？','repl backlog 大小怎么定？','主从数据一定一致吗？'],'适用于缓存高可用和故障恢复边界。','困难',['Redis复制','PSYNC','一致性'],'深挖'),
  X('backend','Redis持久化','大 Key 为什么会影响 RDB 和 AOF？','大 Key 增加 fork 写时复制、序列化、网络传输、AOF 重写和恢复成本，也会让单命令长期占用 Redis 主线程。',['RDB fork 后父进程写热点页会触发 COW，内存峰值可能导致延迟或 OOM；大 Key 会放大被复制的页。','AOF rewrite 生成当前数据命令并合并期间增量，大对象延长重写和重放时间。','应拆分对象、限制元素数量、渐进删除 UNLINK，并监控 key size、fork time 和 rewrite 指标。'],['BigKey 如何发现？','DEL 与 UNLINK 区别？','fork 本身会复制全部内存吗？'],'适用于 Redis 故障排查。','困难',['Redis BigKey','RDB','AOF'],'高压'),
  X('backend','Redis内存','Redis 过期删除和内存淘汰有什么区别？','过期删除处理已到 TTL 的键，采用惰性删除加主动抽样；淘汰是在达到 maxmemory 时按配置从候选键中释放空间。',['惰性删除在访问时检查，主动过期周期抽样以避免大量过期键长期占内存。','淘汰策略包括 allkeys/volatile 的 LRU、LFU、random、TTL 以及 noeviction；LRU/LFU 是近似实现。','缓存穿透、雪崩和热 Key 需要业务层共同处理，淘汰策略不能单独解决。'],['为什么不用定时器逐键删除？','TTL 到了内存会立即下降吗？','LFU 适合什么场景？'],'Redis 基础到生产边界的必答题。','中等',['Redis过期','淘汰策略'],'必背')
);
