/* 大厂 Agent / 后端 / 数据库项目深挖题：强调参数来源、线上证据、失败路径与落地边界。 */
QUESTIONS.push(
  // ── RAG 全链路与上下文工程 ──────────────────────────────────────
  X('agent','RAG切分','父子索引（Parent-Child Retrieval）为什么能兼顾召回精度和上下文完整性？','用较小 Child Chunk 建索引和命中查询，再通过 parent_id 回取更大的父段落作为模型上下文，避免“大块召回不准、小块语义不全”。',['离线解析时生成 Document→Parent→Child 的稳定 ID、版本、权限与字符区间；Embedding 只建在 Child，原文父块保存在 DocStore。','在线先召回 Child，按 parent_id 聚合分数、去重父块并扩展相邻段；最终引用仍定位到原文和版本。','父/子尺寸没有固定答案，应对 Recall@K、上下文相关性、引用完整性、Token 和延迟做网格实验；表格、代码和标题层级需专门切分。'],['多个 Child 命中同一 Parent 怎么聚分？','Parent 多大合适？','文档更新怎样避免悬空索引？'],'国防科研项目可按“知识图谱/RAG 数据组织→检索→执行契约”说明；没有真实参数时不要编造，只给实验方法。','困难',['Parent Document Retriever','Chunking','DocStore'],'高压'),
  X('agent','检索','BM25 与向量混合检索的权重应该怎样确定？','不能拍脑袋固定 0.5/0.5；应先校准两路分数或用 RRF 融合，再在分场景验证集上搜索权重并观察召回、排序、延迟和稳定性。',['BM25 对函数名、错误码、型号和专有词更强，向量对同义表达和自然语言意图更强；先分析 Query 类型占比。','原始 BM25 分数与 cosine 不同尺度，直接线性相加会漂移；可归一化、学习融合器，或用 `RRF=Σ1/(k+rank)` 规避分数校准。','记录每路召回贡献、交集/独有相关文档和零结果率；按关键词型、语义型、多跳型切片调参，而不是只优化总体均值。'],['RRF 的 k 如何选？','权重能否由 Query Router 动态决定？','向量模型升级后为什么要重调？'],'可把精确漏洞术语/工具名走 BM25、自然语言步骤走向量作为项目例子，但要以日志或评测集验证。','困难',['BM25','Hybrid Search','RRF'],'高压'),
  X('agent','RAG基础','请从用户 Query 开始完整口述到最终上下文的线上 RAG 流程。','Query 进入后先做身份和意图处理，再多路召回、融合过滤、重排和上下文打包，最后带引用生成并记录全链路 Trace。',['Query 标准化但保留原文，提取 tenant/权限/时间/实体；可做 rewrite、分解或 HyDE，并同时保留原 Query 防漂移。','BM25/向量/图谱并行召回→权限和版本过滤→融合去重→Rerank→父块/邻块扩展→多样性与 Token 预算裁剪。','Prompt 组装系统规则、任务、可信状态和标来源的检索数据；生成后校验引用、拒答和结构，再记录 query、索引版本、候选、分数、耗时与答案。'],['权限过滤为什么不能放生成后？','Query Rewrite 错了怎么回退？','哪一步最容易成为延迟瓶颈？'],'回答国防项目时应能画出离线建库和在线查询两条链，而不是只说“接了向量库”。','中等',['RAG Pipeline','Query Flow','Trace'],'必背'),
  X('agent','Advanced RAG','Rerank 前应该召回多少候选，最终返回多少文本块？','没有通用数字；候选 K 由召回饱和曲线和 Rerank 延迟决定，最终 N 由答案证据覆盖、块冗余和上下文 Token 预算决定。',['从较宽候选如 K∈{20,50,100} 做离线 sweep，观察 Recall@K 增益是否已经饱和，再测 Cross-Encoder 的 p95 延迟和费用。','最终 N 不是简单 `top 5`：先按文档/父块去重，再保留多样来源和必要邻块；用 Token Budget 截断而不是只按块数。','线上记录候选数、过滤后数量、Rerank 分差、实际注入 Token、引用命中率和无答案率，按 Query 类型可动态 K/N。'],['K 越大为什么可能更差？','Reranker 超时怎么办？','怎样证明 topN 足够？'],'若简历项目没有保存具体 K/N，面试时明确“当时参数/日志是否可得”，不要把建议值说成已上线事实。','困难',['Rerank','TopK','Latency'],'高压'),
  X('agent','Advanced RAG','Rerank 后的截断、去重和多样性应该怎样做？','先消除同一父文档的重复命中，再在相关性、来源覆盖、时间和 Token 成本间优化，避免高相似块把上下文占满。',['用 content hash、parent_id 和 overlap ratio 去重；相邻块可合并，但保留原始 offset 与引用。','可用 MMR 或每文档配额减少单一来源垄断；高风险答案保留支持材料和可能反证，而不是只取同方向片段。','截断必须在完整语义边界上进行，表格行、代码函数、否定条件不能被从中间切掉。'],['MMR 的 λ 表示什么？','多样性会不会降低相关性？','相邻块何时扩展？'],'适合回答知识图谱与 RAG 融合后的证据选择。','困难',['Dedup','MMR','Context Selection'],'深挖'),
  X('agent','上下文工程','检索上下文过长时如何兜底？','先去重和按证据价值裁剪，再做查询相关压缩或分层生成；不能简单从末尾截断导致条件、引用和反证丢失。',['预留系统指令、用户 Query、输出和工具消息预算；检索区按相关性、来源质量、时效和多样性分配 Token。','父块可只取命中窗口并带标题路径，长文先 Map 级提取再 Reduce，但摘要与原文引用分离。','超过阈值可分解 Query、分批检索/回答或让模型请求下一批；记录被丢弃材料以便调试。'],['Lost in the Middle 怎么缓解？','压缩模型会不会产生幻觉？','为什么不能盲目使用超长上下文？'],'可联系 AV Review Package：原始 Artifact 不删除，只对当前任务构建有来源视图。','困难',['Context Budget','Compression','Long Context'],'必背'),
  X('agent','上下文工程','检索内容不足或没有可靠证据时如何兜底？','先区分零召回、低置信、权限过滤和知识库无答案，再扩大检索或明确拒答；不能让生成模型用参数记忆偷偷补齐。',['回退可依次尝试拼写/实体规范化、原 Query、Hybrid Search、扩大 K、邻接扩展、其他受信数据源或澄清问题。','设置 evidence sufficiency/score gap 等信号，但阈值必须由无答案集校准；低分不直接等于无关。','最终输出明确缺少什么、查了哪些范围和下一步；线上统计 no-answer precision/recall 与人工转接率。'],['怎样构造无答案评测集？','扩大 K 为什么可能引入噪声？','模型拒答率越高越好吗？'],'项目中遇错自主找兜底路径时，应区分检索失败和执行失败并保留 Error Log。','中等',['No Answer','Fallback','Abstention'],'必背'),
  X('agent','上下文工程','一个降低模型损耗的上下文拼接模板应包含什么？','按信任和任务顺序组织：稳定规则→当前目标→结构化状态→带来源检索材料→允许动作→输出契约，外部内容始终作为不可信数据隔离。',['不要把历史对话、RAG 文本和工具说明揉成一段；使用明确标签、document_id、时间、权限和引用格式。','先给必须遵守的不变量和当前问题，删除无关历史；重复内容合并，关键材料可在任务附近引用而不是复制多次。','模板版本、字段 Token 数和截断原因进入 Trace；通过消融比较正确率、忠实度、Token 和延迟。'],['指令应该放开头还是结尾？','XML/Markdown 分隔能防注入吗？','如何验证模板没有丢关键状态？'],'Planner 输入和 Actor 执行契约可以按这一结构说明；协议边界由宿主校验而非只靠模板。','困难',['Prompt Template','Context Packing','Grounding'],'高压'),
  X('agent','RAG评测','怎样用数据证明 RAG 参数是线上落地而不是纸上谈兵？','为每阶段保存可复现指标和版本：离线测检索/生成，Shadow或灰度测真实分布，最终同时看质量、延迟、成本和业务成功。',['离线记录 Recall@K、MRR/nDCG、Rerank 增益、Faithfulness、引用正确率、无答案表现，按 Query 类型切片。','线上记录零结果率、点击/采纳、任务完成率、人工兜底、p50/p95/p99、Token 和费用；A/B 只改一个关键变量。','保留数据集、索引、Embedding、Reranker、Prompt 与模型版本；没有线上日志时诚实称为离线实验/项目验收，不虚构“线上提升 30%”。'],['离线变好线上变差有哪些原因？','如何计算置信区间？','LLM-as-Judge 怎样校准？'],'当前简历只写项目通过验收和指标达到预期；面试前应从验收材料恢复可公开口径，无法公开时说明测量方法与保密边界。','困难',['RAG Metrics','Online Eval','A/B'],'高压'),

  // ── Memory、Tool Calling 与企业安全 ─────────────────────────────
  X('agent','Memory工程','短期记忆和长期记忆在线上分别存在哪里、怎样读取？','短期记忆通常跟随 run/thread 存消息、摘要和工作状态；长期记忆按用户/租户/实体存结构化事实与可检索事件，两者不能混成一张无限增长的聊天表。',['短期层可用 Checkpoint DB/Redis 保存 thread state，原始大 Artifact 放对象存储；窗口内只装当前相关片段。','长期层可分 profile/semantic facts、episodic events 和 procedural skills，使用关系库+向量索引并保留 source、scope、time、confidence。','读取顺序先权威业务状态，再当前 Session，最后按目标召回长期记忆；缓存键和向量过滤都带 tenant。'],['Redis 能否作为唯一长期记忆？','摘要存哪里？','跨设备 Session 如何恢复？'],'对应你们“Session Memory ≠ Canonical State”：会话提高效率，权威状态必须在会话外重建。','中等',['Short-term Memory','Long-term Memory','Storage'],'必背'),
  X('agent','Memory工程','长期记忆怎样更新、冲突、淘汰和删除？','写入前做价值与来源判断；同一事实按实体和时间版本化处理冲突；通过 TTL、衰减、容量和用户删除淘汰，并同步清理派生索引。',['只有具有 novelty、未来用途和可信来源的内容进入长期层，外部网页指令和模型猜测不自动写入。','新旧事实冲突时保留 valid_from/to 和 provenance，权威来源优先；合并摘要不能覆盖原始记录。','删除必须传播到主库、向量、缓存、备份策略和生成摘要；建立 tombstone 防异步任务把旧数据重新写回。'],['遗忘分数怎么设计？','用户更正记忆怎么处理？','如何防 Memory Poisoning？'],'可类比 AV 的 Reviewed Delta、Revision 与 lineage，但不要把一般用户记忆说成安全 Case。','困难',['Memory Update','Eviction','Lineage'],'高压'),
  X('agent','工具设计','企业级 Function Calling 的完整架构是什么？','模型只产生 Tool Proposal；宿主完成 Schema 校验、身份授权、策略判断、执行隔离、结果封装和审计，再把结构化结果交回模型。',['Tool Registry 保存版本、输入输出 Schema、owner、权限、幂等性、超时和副作用等级；模型只看到当前允许子集。','执行前做类型/范围/对象级授权和审批，写操作使用 idempotency key；执行器隔离凭证并限制网络与资源。','结果 Envelope 区分 success、business_error、retryable_error、partial 和 unknown，正文标记为不可信数据并限制大小。'],['JSON Schema 能解决什么、不能解决什么？','Tool 描述注入怎么办？','MCP Server 放在哪一层？'],'国防项目可从 MCP 契约化编排回答；你们 Harness 则把完整 Coding Agent 当 Runner，控制粒度高于单次 Tool Call。','困难',['Function Calling','Tool Registry','Execution'],'必背'),
  X('agent','Workflow Pattern','任务规划应该由模型自主拆分，还是由规则/状态机兜底？','稳定高风险主流程由代码和状态机保证，不确定的局部选择交给模型；模型提出计划，宿主校验合法动作、前置条件和完成条件。',['支付、权限、报告发布等阶段固定；搜索、诊断和候选工具选择可由模型根据当前 Observation 决定。','计划表示为带依赖、输入、预期输出和状态的结构，而不是一段无法恢复的自然语言待办。','模型卡住时由规则检测重复、无进展和非法迁移，触发重规划、人工或安全终止。'],['固定 DAG 为什么不适合开放任务？','完全自主规划的风险？','计划改变如何审计？'],'Planner-Actor 的面试重点是“确定性骨架+模型局部智能”，AV 则进一步由证据状态约束下一行动。','困难',['Planner-Actor','State Machine','Replanning'],'高压'),
  X('agent','工具设计','多个工具调用怎样决定串行、并行和执行顺序？','先从参数引用、资源冲突和副作用构建依赖 DAG；无依赖只读调用可并行，有数据依赖或共享写资源的调用必须串行或加事务/锁。',['模型可提出多个调用，但调度器验证前置条件；B 的参数引用 A 输出时形成显式 edge。','并行 fan-out 设置并发上限、各自 deadline 和结果聚合策略，避免部分失败后无脑全量重试。','写工具按风险排序并设置 commit barrier；同一对象更新使用版本/CAS，最终结果记录父子 span。'],['Parallel Tool Calls 有什么风险？','部分成功怎样补偿？','模型怎样引用前序输出？'],'可联系四阶段闭环和 Harness Workflow 的并行能力；AV 当前主循环是否并行要以最新 `av.md` 为准。','困难',['Tool DAG','Parallel Calls','Ordering'],'深挖'),
  X('agent','可靠性','工具接口报错时怎样设计重试、降级和重规划？','先分类网络瞬态、限流、参数、业务、权限、环境和部分成功；只有可重试且幂等的失败才退避重试，其余修正计划、降级或人工接管。',['429/部分5xx/连接重置使用 capped exponential backoff + jitter 并遵守 Retry-After；认证和 Schema 错误不盲重试。','Fallback 必须能力兼容且保持权限/数据合规；结果质量下降要显式标记，不能静默换成不可靠数据源。','每次 Attempt 保存错误码、输入 hash、已产生副作用和恢复动作，重复错误触发断路器或重新规划。'],['超时后工具一定没执行吗？','如何设计补偿事务？','错误日志要不要全部给模型？'],'国防项目“解析 Error Log 自主搜索兜底路径”应能落到错误分类、幂等和状态迁移。','困难',['Retry','Fallback','Error Taxonomy'],'必背'),
  X('agent','安全','企业 Agent 怎样分层防御 Prompt Injection？','把注入视为不可信数据影响高权限动作的问题，用指令隔离、来源标记、权限最小化、数据流策略、调用前授权和人工确认形成多层防线。',['直接/间接注入样本进入安全评测；网页、RAG、代码和 Tool Output 不获得系统指令级信任。','检测器只能作风险信号，核心是宿主限制外部内容可影响的工具、参数、目标资源和可外发数据。','对敏感工具做 taint/source-to-sink 策略，提交、发送、删除和外联前重新确认；保留完整 Trace 便于归因。'],['只写“忽略恶意指令”为什么不够？','结构化输出能否完全防注入？','怎样测试多步注入？'],'安全 Agent 会主动读取恶意仓库，这一题可直接连接你们的 Workspace、Runner 权限和 Fresh Review。','困难',['Prompt Injection','Data Flow','Defense in Depth'],'高压'),
  X('agent','安全','敏感工具白名单应该怎样设计？','白名单不只是工具名称，还要绑定主体、任务、资源、动作、参数范围、环境、有效期和审批条件，并由执行宿主强制。',['默认拒绝，按 Session 动态下发最小 Tool Set；同名工具不同版本/Server 需绑定签名和来源。','参数策略限制文件根目录、域名、SQL 类型、命令 argv 和最大影响行数，凭证使用短期 scoped token。','读/建议、可撤销写、不可逆高风险动作分级；权限升级需要用户或策略批准，完成后立即回收。'],['Allowlist 与 RBAC/ABAC 如何结合？','MCP Tool 发现后能直接调用吗？','Coding Agent 的 Shell 怎么白名单？'],'Workflow-Harness 必须从 OS/容器层限制完整 Runner，不能只依赖 Agent Prompt 中的工具清单。','困难',['Tool Allowlist','Least Privilege','ABAC'],'高压'),
  X('agent','安全','Agent 的分级权限控制和审批链应怎样落地？','把用户身份、Agent 服务身份和委派范围同时传到工具端，按风险级别实施自动执行、二次确认、双人审批或禁止，并记录不可抵赖审计。',['工具端重新校验 subject/action/resource，不能因为请求来自“可信 Agent”就使用万能 Service Account。','低风险只读自动执行；外发、部署、删除、资金和权限变更需要预览影响与批准，状态变化后旧批准失效。','审批内容绑定确切参数、资源版本和幂等键；批准后仍在沙箱执行并验证结果。'],['Human-in-the-loop 为什么不是万能安全层？','Confused Deputy 怎样形成？','审批疲劳怎么缓解？'],'可用于解释 Controller、Investigator、Reviewer 是认知权限边界而不是三个拥有同等写权限的聊天角色。','困难',['Permission Tier','Delegation','Approval'],'高压'),

  // ── RAG 评测、性能与缓存并行 ────────────────────────────────────
  X('agent','RAG评测','怎样快速判断问题出在检索层还是生成层？','先看标准证据是否进入候选和最终上下文：证据没进来是检索失败；已进入但答案错误、无引用或误用条件才主要是生成失败。',['检索层拆 Recall@K、过滤、融合、Rerank、父块扩展和截断；逐阶段保存候选，定位证据在哪一步丢失。','生成层测 Faithfulness、Correctness、Citation、Abstention 和格式；固定上下文对不同 Prompt/模型做对照。','还有数据层错误：文档解析、权限、版本和答案标注本身可能有问题，不要把所有错误归给两层之一。'],['证据进了上下文为什么模型仍忽略？','检索正确但引用错误算哪层？','端到端指标为何不够？'],'这是回答“RAG全链路优化”的开场诊断框架。','中等',['Retrieval Failure','Generation Failure','Diagnosis'],'必背'),
  X('agent','LLMOps','RAG 全链路性能优化应该按什么顺序做？','先用 Trace 分解解析、Query 改写、各路召回、融合、Rerank、上下文组装、Prefill 和 Decode，再优先优化 p95 关键路径而非平均耗时。',['检索层做索引分片/副本、过滤下推、批量 Embedding、ANN 参数、候选控制和 Rerank 小模型/量化。','生成层减少无效上下文、使用 Prefix Cache/模型路由/流式输出，分别观察 TTFT、TPOT 和输出长度。','设置质量护栏后再优化：减少 K、换小模型或压缩可能降低 Recall/Faithfulness，必须做等质量比较。'],['HNSW efSearch 如何影响延迟？','TTFT 高通常看哪里？','流式输出会降低总延迟吗？'],'面试应给出“指标→瓶颈→改动→对照数据”，没有数据就说明如何补埋点和压测。','困难',['RAG Performance','TTFT','p95'],'高压'),
  X('agent','LLMOps','RAG 中哪些环节可以缓存，缓存键怎样避免错误复用？','可缓存文档解析、Embedding、Query Rewrite、召回、Rerank、稳定前缀甚至最终答案，但 Key 必须包含租户权限、数据/索引/模型/Prompt 版本和关键参数。',['Embedding Cache 以规范化内容 hash+模型版本为键；检索缓存还带 tenant、ACL version、index snapshot、topK/filter。','语义答案缓存风险最高，需要相似阈值、时效和权限校验，不用于强时效或个性化高风险答案。','更新/删除通过版本键自然失效或事件驱动清理，监控 hit rate、stale read、节省延迟和质量回归。'],['为什么不能只用 Query 文本作 Key？','缓存击穿如何处理？','权限变更后怎样失效？'],'知识库和 Agent Memory 都必须避免跨租户缓存泄漏。','困难',['RAG Cache','Cache Key','Invalidation'],'深挖'),
  X('agent','LLMOps','RAG 哪些步骤适合并行，怎样控制尾延迟？','无依赖的 BM25、向量、图谱和多个数据源召回可并行；融合后才能 Rerank，生成依赖最终上下文，不能把有依赖步骤强行并行。',['为各路设置独立超时和最小成功条件，可用 hedged request/快速路先返回，但记录缺失来源和降级状态。','并发受连接池、向量库 QPS、Reranker batch 和 Provider 配额限制，需要背压而不是无限 fan-out。','总 deadline 向下传播，取消迟到任务；观察最大分支而非耗时之和，并优化最慢稳定分支。'],['并行为什么可能更慢？','某一路超时是否还能回答？','如何做结果增量融合？'],'可联系 Planner-Actor 的工具并行与 Harness 的 operational timeout；方法内部科学终止规则需单独说明。','困难',['Parallel Retrieval','Tail Latency','Deadline'],'深挖'),

  // ── 后端算法、Redis 限流与 MySQL ────────────────────────────────
  X('backend','限流','分布式令牌桶怎样用 Redis 原子实现？','每个限流键保存剩余 Token 和上次补充时间；请求到来按时间差补充并尝试扣减，整个过程用 Lua/Function 原子执行并设置过期。',['`tokens=min(capacity,tokens+(now-last)*rate)`，足够则扣 cost；首次初始化、浮点/整数精度和时钟回退必须定义。','Redis TIME 或可信网关时间避免各应用节点时钟差；Key 维度可组合 tenant/user/API，TTL 约为桶回满所需时间。','Redis 故障需明确 fail-open/fail-closed、本地兜底和热点 Key；脚本返回剩余额度与 retry_after，便于响应 429。'],['令牌桶如何支持不同请求成本？','Lua 会不会阻塞 Redis？','Cluster 下多 Key 怎么办？'],'用于模型 TPM/RPM、Agent 并发和昂贵工具的全局配额。','困难',['Redis','Token Bucket','Lua'],'高压'),
  X('backend','限流','滑动窗口限流用 Redis ZSET 怎样实现，有什么成本？','以时间戳/唯一请求 ID 为 score/member，Lua 中删除窗口外记录、统计当前数量并添加新请求，实现较精确窗口计数。',['同一毫秒多请求需要唯一 member；`ZREMRANGEBYSCORE→ZCARD→ZADD→EXPIRE` 在脚本中原子执行。','精确日志窗口内每个请求都占元素，高 QPS 内存和 O(logN) 操作昂贵；可用分桶计数近似降低成本。','热点用户可本地令牌桶预限+Redis 全局配额；过期和脚本最大执行时间必须监控。'],['固定窗口边界突刺如何形成？','分桶滑窗怎样加权？','ZSET 方案能做百万 QPS 吗？'],'面试时与令牌桶、漏桶按“突发、公平、精度、内存、分布式原子性”比较。','困难',['Sliding Window','Redis ZSET','Rate Limit'],'高压'),
  X('backend','限流','漏桶在工程上怎样实现，为什么它和令牌桶不是一回事？','漏桶通常用有界队列接收请求并按固定速率出队，平滑下游流量；令牌桶限制长期平均但允许积累令牌后的突发。',['队列满时拒绝或丢弃，并返回预计等待；消费者以稳定速率处理，适合保护不能承受突发的下游。','分布式实现需要队列/Stream、消费者租约、可见性超时、重试和幂等，已不只是一个计数器。','漏桶增加排队延迟，交互 API 常结合最大等待时间；任务系统则需处理积压监控和死信。'],['排队是否等于限流？','如何保证固定出队速率？','下游恢复后能否加速清空？'],'适用于 Agent Task Queue 和外部 Provider 的平滑调用。','中等',['Leaky Bucket','Queue','Backpressure'],'必背'),
  X('backend','概率结构','布隆过滤器误判率怎样计算和优化？','插入 n 个元素、位数组 m、哈希数 k 时，误判率近似 `(1-e^{-kn/m})^k`；给定 m/n 时最优 `k≈(m/n)ln2`。',['降低误判可以增加位数、控制装载量并使用接近最优 k；不是无限增加哈希，过多会更快把位图填满且增加 CPU。','普通 Bloom 无假阴性只成立于正确实现且不删除；需要删除可用 Counting/Cuckoo Filter 或重建。','容量超预期时采用 Scalable Bloom 分层扩容，监控 fill ratio 并用真实负例估计 FPR。'],['如何由目标 FPR 反推 m？','RedisBloom 怎样扩容？','误判后业务如何处理？'],'可用于防缓存穿透、去重和百万级任务预过滤，但阳性仍需查权威数据库。','困难',['Bloom Filter','FPR','Scalable Bloom'],'高压'),
  X('backend','索引','联合索引失效和优化器不选索引时，怎样系统排查？','先用 EXPLAIN/EXPLAIN ANALYZE 看访问路径与估算偏差，再检查最左前缀、范围截断、函数/类型转换、选择性、覆盖性和统计信息。',['索引 `(a,b,c)` 中 a 等值后可继续利用 b/c；某列成为范围后，其右侧通常难继续用于定位，但可能用于 ICP/覆盖。','`OR`、`IN`、`!=`、IS NULL 并非绝对失效，是否使用取决于成本、索引合并、回表次数和数据分布。','对比 rows estimated/actual，更新统计或直方图；强制索引只作诊断/临时方案，最终修 SQL、索引或数据模型。'],['ICP 是什么？','范围条件后还能用排序吗？','索引存在为什么全表扫更快？'],'比背“六种索引失效”更像真实线上问题定位。','困难',['Composite Index','EXPLAIN ANALYZE','Optimizer'],'高压'),
  X('backend','索引','LIKE 查询在什么情况下能命中 B+ 树索引？','常量前缀 `LIKE \'abc%\'` 通常可转成有界范围扫描；前导通配符 `%abc` 无法确定起点，普通 B+ 树通常不能定位。',['列上函数、隐式类型/字符集转换、不同 collation 或参数化估算也可能改变计划；使用 EXPLAIN 验证而非只看写法。','`_` 与 `%` 是通配符，搜索字面量需正确 ESCAPE；用户输入直接拼 Pattern 还会造成语义注入和性能 DoS。','包含/分词搜索考虑全文倒排、ngram 或搜索引擎；生成反转列可支持固定后缀但增加写入和维护成本。'],['`LIKE \'%\'` 会怎样？','覆盖索引能否缓解前导模糊？','MySQL Fulltext 适合中文吗？'],'适用于日志、Artifact 和任务搜索接口的性能设计。','中等',['LIKE','Prefix Search','Fulltext'],'必背'),

  // ── 百万级数据与数据库系统设计 ──────────────────────────────────
  X('backend','系统设计','如何从零设计一个百万级数据处理系统？','先量化数据量、到达速率、处理 SLA、准确性和重放要求，再设计接入、持久队列、幂等 Worker、结果存储、回压、监控和故障恢复。',['入口生成稳定 job/item ID，原始文件进对象存储，元数据进数据库，队列只传引用；批量生产/消费并按下游容量限流。','Worker 租约领取任务，幂等键/唯一约束防重复，失败按类型重试并进入 DLQ；Checkpoint 支持从分片位置恢复。','按峰值 QPS、平均单条耗时和 Worker 并发做容量估算，压测 p95、积压清空时间、数据库写放大和故障恢复。'],['至少需要多少 Worker？','Exactly-once 如何理解？','大文件怎样切分又保证顺序？'],'可以联系文本规整数据处理实习：说明批处理、正则优化和准确率验证，但不要声称当时使用了未实际采用的分布式组件。','困难',['Million Scale','Pipeline','Backpressure'],'高压'),
  X('backend','系统设计','百万级任务表怎样分页、领取和避免重复处理？','避免深 OFFSET；按有序唯一游标做 Keyset Pagination，领取使用状态条件更新、租约或 `FOR UPDATE SKIP LOCKED`，最终用幂等约束兜底。',['游标如 `(created_at,id)` 必须唯一稳定并建立匹配索引；查询 `WHERE (created_at,id)>(?,?) ORDER BY... LIMIT...`。','Worker 原子把 pending→running 并写 owner/lease_until/version；Crash 后由 Reaper 回收过期租约。','业务结果表以 task_id+版本做唯一键，状态更新 CAS，迟到旧 Worker 的 fencing/version 被拒绝。'],['为什么 OFFSET 越深越慢？','SKIP LOCKED 会饿死任务吗？','租约多久合适？'],'与 Harness Run、任务租约、stale rejection 和 exactly-once 有直接工程联系。','困难',['Keyset Pagination','Lease','Idempotency'],'高压'),
  X('backend','数据库设计','怎样从需求到表结构完整设计一个 Agent Run 系统？','从实体、生命周期、查询模式和不变量出发，将 Run、Step、Session、Artifact、State Version 和 Event 分离，用主外键、唯一约束和版本控制保证一致性。',['先列访问模式：按用户/状态/时间查 Run，按 run_id 查步骤和 Artifact，按 version 原子提交；据此设计联合索引而非先建一堆字段。','大日志和文件进对象存储，表中保存 hash、URI、size、media_type；事件表追加写，当前状态表保存投影与 version。','Run/Step 状态迁移用条件更新，idempotency_key 唯一；多租户每张关键表带 tenant_id 并在存储层强制过滤。'],['Event Sourcing 是否必要？','Artifact 为什么不直接存 BLOB？','怎样清理历史数据？'],'这可直接作为 Workflow-Harness 的数据库系统设计题。','困难',['Schema Design','Run State','Artifact'],'高压'),
  X('backend','数据库设计','Agent 运行数据怎样做冷热分层、归档和删除？','热库保存近期可查询状态和索引，冷存储保存压缩事件、日志与 Artifact；按租户、时间和合规策略归档，并保持可验证引用和删除传播。',['高频 Run/Step 状态在 OLTP，Trace 明细可进列存/日志系统，原始文件进对象存储；数据库只保留定位元数据。','按时间分区便于裁剪和归档，但 tenant 查询还需合适联合索引；冷热迁移使用 manifest/hash 校验完整性。','删除覆盖状态、事件、向量索引、缓存和对象，审计类数据按合法保留期做不可变/脱敏而非无限保存。'],['分库分表什么时候需要？','时间分区有什么坑？','归档后如何支持复盘查询？'],'适用于长期积累的 Agent Trace、漏洞 Artifact 和实验数据。','困难',['Hot Cold Storage','Partition','Retention'],'深挖'),
  X('backend','系统设计','端到端性能优化为什么必须同时考虑缓存、批处理、并行和背压？','缓存消除重复，批处理摊薄固定成本，并行隐藏独立等待，背压保护下游；四者必须基于瓶颈和一致性要求组合，而不是全部拉满。',['先画关键路径并测 CPU、I/O、锁、队列、外部 RPC 和数据库；使用 Little定律估算并发与等待，不凭感觉加线程。','批量数据库写、Embedding/Rerank batch 提升吞吐，但增加等待和失败粒度；并行受连接池和下游 QPS 限制。','缓存键含版本/权限，队列设上限和拒绝策略；观察吞吐、p95/p99、积压、错误率与单位成本的联合变化。'],['Little 定律是什么？','批次多大合适？','为什么并发提高后 p99 恶化？'],'可同时回答 RAG 性能和百万级数据系统，不要把“用了 Redis/异步”直接等同于优化结果。','困难',['Performance','Batching','Backpressure'],'高压')
);
;
/* 寒武纪 AI Agent 三面面经补充：按原题意重新组织答案，突出国产算力、工程权衡、bad-case 与可验证证据。 */
QUESTIONS.push(
  // ── 一面：基础、项目、RAG、框架 ──────────────────────────────────
  X('agent','Agent范式','讲一个落地过的 Agent 项目时，怎样讲链路而不是堆名词？','按业务目标→输入→状态→决策→工具→反馈→异常恢复→指标讲一条真实请求，并明确自己负责的模块、失败案例和可验证结果。',['先用一句话说明用户、问题和成功标准，再画在线链路与离线数据/配置链路。','每个框架名后都回答“解决了什么约束、输入输出是什么、失败如何恢复”；只说 LangGraph/MCP/RAG 不构成项目经历。','最后给真实口径：验收、任务成功率、延迟、成本或案例；不可公开或未测的数据明确边界。'],['为什么不用更简单的工作流？','你亲手写了哪些代码？','最严重的 bad-case 是什么？'],'可分别准备国防项目 Planner-Actor 和 Workflow-Harness 两个 90 秒版本，事实以简历与最新 `av.md` 为准。','中等',['寒武纪','Agent面经','项目表达'],'必背'),
  X('agent','Agent范式','产线意图识别为什么不能只依赖大模型分类，规则、轻量模型和 LLM 怎样混合？','高频稳定意图应由规则/轻量分类器低成本处理，LLM覆盖长尾和复杂语义；路由器依据置信度、风险和资源选择路径并允许升级。',['精确关键词、协议字段和黑白名单先走确定性规则；轻量模型承接大部分已知分类，LLM处理组合意图、开放文本和解释。','校准每路置信度并按场景设阈值：低风险可取 top1，高风险要求 margin、二次确认或转人工。','Shadow 记录路由决策、真实标签、误路由成本和 LLM 调用率，优化目标是质量、延迟、算力和可维护性的联合函数。'],['规则冲突如何处理？','轻量模型和 LLM 结果不一致怎么办？','新意图如何冷启动？'],'国产算力受限时先让便宜路径过滤大多数请求，把强模型预算留给真正不确定样本。','困难',['寒武纪','Agent面经','Intent Router'],'高压'),
  X('agent','Agent范式','意图歧义或置信度低时怎样兜底，bad-case 应怎样回答？','不要强行选类；先识别缺少的槽位并澄清，或保守路由到只读/人工路径，同时把错误样本回流到评测与训练。',['阈值不仅看 top1，还看 top1-top2 margin、OOD 分数、关键实体是否齐全和动作风险。','例如“把昨天那个处理一下”同时可能是重跑、删除或提交：系统应询问对象和动作，不能让模型根据聊天猜测执行。','记录 query、候选意图、置信、最终人工标签和影响；按误拒绝/误执行代价分别调阈值。'],['澄清会不会降低转化？','OOD 怎样检测？','低置信都转人工是否可行？'],'面试前从自己的项目恢复一个真实 Error Log 或误规划案例，不要虚构线上 bad-case。','中等',['寒武纪','Agent面经','Confidence','Fallback'],'必背'),
  X('agent','RAG切分','Chunk 大小、Overlap、语义切分和结构切分怎样选？','先按标题、段落、函数、表格等天然结构保语义，再对过大单元做 Token/语义二次切分；大小和重叠度用召回、完整性、Token 与延迟实验确定。',['固定切分快且稳定但会截断语义；语义切分更灵活却增加离线成本和版本不确定性；代码/规范优先结构切分。','Overlap 用于跨边界关系，过大会造成索引膨胀、重复召回和上下文浪费；父子索引或邻块扩展常比盲目大 overlap 更可控。','按短事实、长解释、表格、代码、多跳查询切片评测 Recall@K、引用完整性和冗余率。'],['为什么 512 Token 不一定合适？','中文和代码如何计 Token？','文档更新怎样增量切分？'],'国防知识库应给出实际文档类型和选型过程；没有保存参数则说明如何重做实验。','困难',['寒武纪','Agent面经','Chunking'],'高压'),
  X('agent','Advanced RAG','Agentic RAG 与传统 RAG 的差别是什么，怎样控制检索次数？','传统 RAG 通常一次检索后生成；Agentic RAG 可判断缺口、选择数据源、改写/分解 Query 并迭代，但必须用证据增益和停止条件限制循环。',['每轮保存已查 Query、文档 ID、证据覆盖和残余问题；只在缺少决定性信息且新 Query 与历史不重复时继续。','Query Rewrite 保留原问题、实体和约束，过度改写时回退原 Query/Hybrid Search；多跳问题按子问题分别取证再汇总。','停止可依据答案充分、边际新增证据低、重复指纹、数据源耗尽或外部运行边界；不能只靠模型说“完成”。'],['怎样检测 Query 漂移？','最多检索几次怎么定？','Agentic RAG 一定更好吗？'],'可联系 AV 的 Evidence Obligation，但不要把一般 RAG 循环和安全调查协议混为一谈。','困难',['寒武纪','Agent面经','Agentic RAG'],'高压'),
  X('agent','框架生态','LangChain Chain 与 LangGraph 状态机的本质区别是什么？','Chain 更偏按组合关系执行一次数据流；LangGraph 把跨步 State、循环、条件路由、Checkpoint 和 Interrupt 作为一等对象，适合可恢复的长期流程。',['LCEL/Runnable 也能分支并行，但复杂循环和持久状态若全靠嵌套 Chain/回调会难以观察与恢复。','LangGraph Node 读取 State 并返回增量，Conditional Edge 根据状态选下一步，Checkpointer按 thread 保存可恢复快照。','简单问答/固定 ETL 用 Chain 即可；异常重规划、工具循环和 HITL 用状态图更清晰，但领域不变量仍需自己实现。'],['纯 Python if/while 与 LangGraph 怎么选？','图是不是固定 DAG？','Checkpoint 会自动保证幂等吗？'],'应继续区分 LangGraph 的模型级 Agent 编排与 Workflow-Harness 对完整 Coding Agent Runner 的编排。','中等',['寒武纪','Agent面经','LangChain','LangGraph'],'必背'),
  X('agent','框架生态','LangGraph 的 State、Node 和 Conditional Edge 怎样配合实现循环决策？','State 保存当前可恢复事实，Node 执行一次确定职责并返回状态更新，Conditional Edge 只根据新 State 选择合法后继，从而形成观察—行动—反馈循环。',['State 使用 TypedDict/Pydantic 定义字段与 Reducer；消息可 append，但业务状态不能让节点任意覆盖。','Node 尽量幂等并记录 attempt/tool result；路由函数返回枚举化下一节点，不把任意字符串当控制流。','设置 completed/blocked/error、重复指纹和最大 operational guard，循环每轮都要产生可观察状态变化。'],['并行节点怎样合并 State？','路由函数可以调用模型吗？','如何测试条件边覆盖？'],'可用国防项目“状态机监控执行流→Error Log→重规划”举例。','困难',['寒武纪','Agent面经','StateGraph'],'必背'),
  X('agent','Workflow Pattern','Checkpoint 断点恢复怎样实现，国产算力受限时状态存储怎么选？','保存恢复所需的最小结构化 State、版本和外部 Artifact 引用，而不是重复存完整 Prompt/文件；本地开发可 SQLite，生产按并发和可靠性选 Postgres/Redis+持久库。',['Checkpoint 绑定 thread/run、node、state schema version 和幂等 attempt；大日志、代码和模型输出进对象存储，只在状态中存 hash/URI。','Redis 适合热状态和锁但不宜成为唯一长期真值；Postgres 适合事务、查询和恢复，定期快照+事件可平衡体积与审计。','算力紧张主要减少重复推理：恢复时复用已完成 Tool Result/Artifact，只重新执行不确定或非持久步骤。'],['Checkpoint 多久一次？','恢复后副作用会不会重复？','状态库故障怎么处理？'],'Workflow-Harness 的 Manifest、Session Handle、Artifact 和 Canonical State 可以构成比聊天快照更强的恢复层。','困难',['寒武纪','Agent面经','Checkpoint','国产算力'],'高压'),
  X('agent','Coding Agent','AI Coding 场景中，大仓库上下文应怎样喂给模型？','不能全量塞仓库；先用文件树/构建信息形成 Repository Map，再按符号、文本、调用关系和变更范围分层检索，最终引用原始代码和测试。',['第一层是目录、语言、依赖和入口；第二层是 LSP/AST/ctags 符号与调用者；第三层才读取目标函数、相邻实现、测试和配置。','精确 grep/符号检索优先，Embedding 补充自然语言与未知命名；索引绑定 commit 并在修改后增量失效。','Session 保存局部导航经验，Canonical/Artifact 保存权威引用；上下文压缩不能丢行号、版本、失败命令和未决问题。'],['何时需要全文件而不是函数块？','调用图不完整怎么办？','生成文件和子模块怎么处理？'],'这是你们使用完整 Coding Agent Runner 的直接优势：Runner 已具备仓库导航，Harness 管理跨会话状态和证据。','困难',['寒武纪','Agent面经','Repository Map'],'高压'),
  X('agent','Coding Agent','AGENTS.md、CLAUDE.md 一类仓库指令和 Agent Skills 应怎样使用？','仓库指令提供作用域内的构建、风格和流程约束；Skill 封装可复用领域步骤与资源，二者都应版本化、按需加载，并受宿主权限约束。',['从仓库根到目标文件逐层解析适用指令，子目录规则可覆盖更高层；冲突和来源要可观察，不能把任意 README 当高权限规则。','Skill 使用触发描述按任务加载，正文可引用脚本/模板；工具权限不因 Skill 声明自动获得，脚本仍在沙箱执行。','不可信仓库可以植入恶意指令，因此 Coding Agent Host 需区分用户/系统规则与仓库数据并限制外联和 Secret。'],['AGENTS.md 与 Prompt 有何区别？','Skill 何时会导致上下文膨胀？','如何测试 Skill 没有过时？'],'可用你们 Harness 对不同 Runner 的指令适配、Workspace 和安全边界回答。','中等',['寒武纪','Agent面经','AGENTS.md','Skill'],'必背'),
  X('agent','Memory工程','Redis 在 Agent 系统中适合存什么，怎样限制对话历史长度？','Redis 适合短期 Session、Checkpoint 热缓存、限流、锁和临时 Tool Result；长期权威状态进持久库，大 Artifact 进对象存储。',['历史按最近消息+任务相关召回+有来源摘要分层，而不是固定保留全部；系统规则、当前目标、未决状态和关键 Tool Result优先。','摘要绑定覆盖消息区间和版本，原始历史可冷存；窗口接近上限时先删无关重复和大工具输出，再做目标相关压缩。','使用 tenant/thread 隔离、TTL 和内存上限，防大 Value、热 Key 和跨用户串话。'],['摘要错了怎么恢复？','Redis 淘汰会不会导致会话丢失？','完整历史何时必须保留？'],'可联系 Sticky Session 与会话外 Canonical State 的区别。','中等',['寒武纪','Agent面经','Redis','Chat History'],'必背'),
  X('agent','可靠性','模型失败、工具超时或返回脏数据时，Agent 循环怎样熔断？','把错误按模型、工具、环境和数据质量分类；仅对可重试幂等错误退避，连续失败、重复状态或无进展时打开熔断并降级、重规划或人工接管。',['每个依赖维护 closed/open/half-open 状态、失败率/连续失败阈值和恢复探针；全局循环还看状态指纹和新增证据。','Tool Result 先过 Schema、范围、来源和业务不变量，脏数据不能作为新状态；保留原始输出供审计。','超时不代表工具未产生副作用，重试携带 idempotency key并先查询执行状态。'],['模型返回半截 JSON 怎么办？','熔断和重试谁在外层？','降级模型能力不足怎么办？'],'国防项目的异常自愈与 Harness 的 Agent/Runner/Environment Failure 分类都能展开。','困难',['寒武纪','Agent面经','Circuit Breaker'],'高压'),

  // ── 二面：架构、多 Agent、安全、评测、国产算力 ────────────────
  X('agent','Workflow Pattern','如何画企业级研发助手 Agent 的分层架构？','从上到下画接入与身份、领域服务、编排/状态、模型与检索、工具执行、存储、可观测和安全治理，并标出同步调用、事件流和权威写入点。',['接入层负责 API/UI、认证、租户和限流；编排层管理 Run/Graph/Session、路由、Checkpoint、HITL 和恢复。','工具层含代码检索、Git、CI、终端和 MCP，必须有 Registry、Policy、Sandbox；存储层分 OLTP、向量/搜索、对象和缓存。','横切层记录 Trace/Eval/成本/告警，Guardrail 和权限覆盖输入、检索、调用、输出；模型网关隔离 Provider/国产推理后端。'],['哪个层拥有最终状态？','如何避免编排层成为单点？','哪些接口必须异步？'],'Workflow-Harness 可落在编排/运行层，完整 Coding Agent 位于 Runner 执行层，AdaptiveVuls 是其上的领域控制协议。','困难',['寒武纪','Agent面经','Enterprise Architecture'],'高压'),
  X('agent','反思','Planner 与 Critic 怎样分工，Critic 如何识别幻觉和不可信工具结果？','Planner 提出可执行计划和预期证据，Critic 依据独立状态、原始 Tool Result、约束和反例检查覆盖范围；Critic 不应只评价文风或重复同一叙事。',['计划节点含前置条件、输出契约和完成判据；Critic 对 Claim逐项检查来源、目标保真度、矛盾、遗漏条件和是否越权。','工具输出先做机器校验和 provenance；Critic 可请求对照、重放或另一数据源，但“另一个 LLM 同意”不是证据。','为减少相关偏差，Critic 使用 Fresh/最小必要上下文并无直接写权，合法 Delta 再由 Runtime 提交。'],['Critic 会不会无限挑错？','同一个模型做 Critic 有意义吗？','如何评价 Tool Result 的真实性？'],'可直接用 AV 的 Sticky Investigator、Fresh Reviewer、Artifact 和 Reviewed Delta 回答，但严格依据最新 `av.md`。','困难',['寒武纪','Agent面经','Planner','Critic'],'高压'),
  X('agent','Workflow Pattern','LangGraph State 怎样序列化和做版本兼容，图定义变更后旧会话如何迁移？','持久 State 使用稳定 Schema、显式 version 和可迁移的业务字段，不序列化函数/客户端对象；加载旧 Checkpoint 时先迁移再进入兼容节点或有界终止。',['JSON/数据库列保存标量、枚举和 Artifact 引用；Pydantic/TypedDict 只用于校验，Secrets 和非确定性对象不进入快照。','维护 `v1→v2` 纯迁移函数、默认值和回滚测试；节点重命名/删除时设置 alias或 migration gate，不能让旧 next_node 指向不存在节点。','图热更新采用版本路由：已有 thread 固定旧图完成，新 thread 进新图；必须强迁移时先 Shadow 重放和备份。'],['Reducer 变化怎么迁移？','Tool Schema 升级怎么办？','如何测试旧 Checkpoint？'],'同样适用于 Harness Manifest 和 AV Canonical State 的协议升级。','困难',['寒武纪','Agent面经','State Migration'],'高压'),
  X('agent','Human-in-the-loop','LangGraph 如何实现 HITL，人工长时间无响应怎样超时降级？','在高风险节点前 interrupt 并持久化 State，生成绑定动作参数和版本的审批任务；恢复时验证批准者、状态版本与有效期，再执行或走超时分支。',['审批不是阻塞进程等待，任务进入 suspended/pending_approval，Worker 释放资源，Webhook/队列触发 resume。','超时按风险选择取消、只读降级、转交其他审批人或保留人工队列；不可逆操作不能因超时自动放行。','提醒、升级和 SLA 由外部调度器管理，审批决策、修改参数和恢复节点进入审计 Trace。'],['批准后底层数据变化怎么办？','如何避免重复 Resume？','批量审批如何防疲劳？'],'可联系安全报告/外部提交的审批，但 AV Fresh Review 不是普通人工确认。','困难',['寒武纪','Agent面经','HITL','Timeout'],'高压'),
  X('agent','多Agent','Supervisor、群聊、流水线和层级多 Agent 拓扑分别适合什么场景？','按任务依赖、共享上下文、专业权限和裁决方式选：流水线适合稳定阶段，Supervisor适合可分派任务，群聊适合低风险探索，层级适合大规模领域分治。',['流水线易审计但前序错误会传播；Supervisor 有全局视图但会成瓶颈；群聊灵活却最易上下文爆炸和停止不清。','层级架构通过中间协调者压缩范围，但增加信息损失和责任链；并行价值仅在任务真正独立时成立。','每个 Agent 定义输入、权限、产物和最终写入者，先证明单 Agent 基线不足再引入多 Agent。'],['什么时候 Router 比 Supervisor 更合适？','群聊怎样终止？','多 Agent 一致是否代表正确？'],'AV 的主体是权限/视角边界，不应被描述成自由群聊或默认并行流水线。','困难',['寒武纪','Agent面经','Multi-Agent Topology'],'深挖'),
  X('agent','多Agent','多 Agent 上下文爆炸怎样治理，Agent 间应该传全文还是结论？','默认传结构化任务、必要状态和 Artifact 引用，不传全部聊天；结论必须带来源、置信和未决项，需要时接收方按权限取原文。',['共享黑板保存权威状态，Handoff Package 包含 goal、scope、inputs、attempts、outputs、unknowns 和 next contract。','摘要按接收角色定制并限制 Token，重复对话和工具日志外置；跨 Agent 不继承无关 Secrets 与全部权限。','只传结论会放大摘要错误，因此关键决策可追溯原始 Artifact；全文广播则造成成本、注入和隐私问题。'],['Shared Memory 会不会成为污染源？','如何判断最小必要上下文？','跨组织 Agent 能取原文吗？'],'Workflow-Harness 的会话外状态与 Artifact 引用正适合回答。','困难',['寒武纪','Agent面经','Handoff','Context Explosion'],'高压'),
  X('agent','协议','A2A 与 MCP 有什么区别，为什么企业系统可能同时使用？','MCP 更偏 Host 连接工具、资源和 Prompt；A2A 更偏独立 Agent 的能力发现、任务生命周期、进度和 Artifact 协作，两者处于不同集成边界。',['MCP Client/Server 通常由一个 Host 管理工具权限；A2A 需要远端 Agent 身份、任务 ID、状态、取消和异步结果。','一个研发助手可通过 MCP 调 Git/CI/数据库，又通过 A2A 把安全审查任务委派给独立服务。','两者都不自动提供信任：仍需认证、scope token、租户隔离、输入输出 Schema 和 Prompt Injection 防护。'],['A2A 能否直接调用 MCP Tool？','什么时候普通 HTTP API 足够？','远端 Agent 结果如何验证？'],'回答时避免把协议名当能力，重点说明谁拥有任务循环和权限。','中等',['寒武纪','Agent面经','A2A','MCP'],'必背'),
  X('agent','安全','Tool Calling 怎样做参数校验，并防命令注入与 Agent 场景 SSRF？','模型参数视为不可信：Schema只做类型形状，宿主还要做语义 allowlist、对象授权、规范化和执行层隔离；Shell 用 argv，URL 用解析后策略和受限网络。',['命令工具不要拼 shell 字符串，固定 executable/子命令、分离 argv、限制 cwd/env/文件根并在非 root 沙箱运行。','URL 解析后只允许 HTTPS/域名/端口，解析与连接阶段防 DNS Rebinding，阻断 loopback、私网、link-local、云元数据和重定向逃逸。','Tool Registry绑定风险级别和权限；结果大小、Content-Type 与来源校验，所有拒绝/执行进入审计。'],['只做正则 URL 校验为什么不够？','需要访问内网 API 怎么办？','Schema 校验能防路径穿越吗？'],'这是安全背景优势题，可按 Source→Control→Sink→Boundary→Impact 展开。','困难',['寒武纪','Agent面经','Command Injection','SSRF'],'高压'),
  X('agent','Guardrails','Guardrail 在输入侧和输出侧分别拦什么，为什么仍不能单独依赖？','输入侧识别注入、越权意图、敏感数据和恶意文件；输出侧校验泄密、事实引用、结构与危险内容，但真正副作用必须在工具调用前由权限策略阻断。',['输入层做身份/租户、内容风险、长度/压缩炸弹和不可信来源标记；RAG 文档也属于输入。','输出层做 DLP、Schema、引用和业务不变量；生成的 SQL/Shell/HTML 进入对应安全 Sink 前再校验。','分类器存在误报漏报和对抗绕过，Guardrail只提供信号；最小权限、沙箱、审批、审计和可撤销设计才是硬边界。'],['流式输出怎样实时拦截？','输入安全就无需输出检查吗？','Guardrail 失败时 fail-open 还是 closed？'],'可联系 Agent 读取恶意仓库和 Tool Output Injection。','困难',['寒武纪','Agent面经','Input Guardrail','Output Guardrail'],'必背'),
  X('agent','LLMOps','Eval、Trace、Guardrail 这套 Harness 三件套分别解决什么？','Eval 判断系统在代表性任务上是否有效，Trace 解释一次运行发生了什么，Guardrail 在运行时限制不可接受行为；三者分别对应质量、可观测和安全控制。',['Eval 包含离线金标、轨迹指标、安全红队和线上切片；不能只用单次 Demo。','Trace 关联 run/node/model/prompt/tool/artifact/state/token/latency，让失败可复现并支撑评测。','Guardrail 在输入、检索、工具前后和输出实施策略；Prompt 既不可强制 OS 权限，也不能保证模型始终遵守。'],['没有 Trace 能否做 Eval？','Guardrail 是否属于评测？','三者如何进入 CI/CD？'],'Workflow-Harness 还负责 Runner Adapter、Session、Workspace、恢复和 Artifact，不能把 Harness 缩减成三项能力。','中等',['寒武纪','Agent面经','Eval','Trace','Guardrail'],'必背'),
  X('agent','评测','LLM-as-Judge 怎样缓解位置偏见和长度偏见？','随机交换候选顺序并做双向评判，用明确 rubric、隐藏无关长度/身份，校准人工样本并统计一致性；必要时改成逐项打分而非直接二选一。',['同一对 A/B 与 B/A 都评，顺序翻转则标不稳定；多次采样/多 Judge 只能降低方差，不能自动消除相关偏差。','限制或归一化回答长度，rubric按 correctness、faithfulness、citation 等独立维度评分，并提供无偏参考证据。','计算与专家标签的相关/一致率，关注不同长度、语言、立场切片；高风险样本仍人工复核。'],['Judge 与被评模型同源有什么问题？','Tie 怎样处理？','为什么长答案容易得高分？'],'AV 的证据裁决不应退化成一个 LLM 总分，Judge 只可作为实验辅助。','困难',['寒武纪','Agent面经','LLM-as-Judge','Bias'],'高压'),
  X('agent','Workflow Pattern','AI Workflow 与 Agent 的边界是什么，固定 DAG 和状态图怎样选？','Workflow 由开发者预定义主要步骤和迁移；Agent 在不确定环境中根据 Observation 自主选动作。稳定可枚举流程用 DAG，存在循环、事件等待和动态重规划时用状态图。',['固定审核、ETL、发布链适合 DAG；工具反馈决定下一步、HITL/重试/补偿和长期任务适合带持久 State 的图。','状态图仍可完全确定，不自动等于 Agent；某个 Node 内让模型从合法动作中选择，才引入 Agentic 决策。','开放任务也应保留确定性权限、Gate 和终态，不能把“自主”理解为模型任意生成流程。'],['LangGraph 项目一定是 Agent 吗？','Agent 能否运行在 DAG Node 中？','Harness 与 Workflow 有什么区别？'],'高频抠字眼：Harness 是运行与编排底座，Workflow 是一次业务控制定义，Coding Agent 是被调度的完整执行体。','困难',['寒武纪','Agent面经','Workflow Boundary'],'高压'),
  X('agent','LLMOps','MLU 国产芯片运行 Agent 推理与 CUDA 栈的工程差异有哪些？','Agent上层语义不变，但模型导出、算子覆盖、图编译、量化、动态 Shape、运行时 API、性能分析和部署生态需要适配，不能默认 CUDA Kernel 与库直接可用。',['先盘点模型结构、精度、Tokenizer和自定义算子，经过框架/ONNX等路径转换到 MagicMind/对应 Runtime，并做逐层/端到端精度对齐。','关注编译缓存、Host↔Device 拷贝、显存、batch/sequence shape、并发和算子 fallback；用真实 Prefill/Decode 负载测 TTFT/TPOT。','编排层通过 Model Gateway 隔离后端能力，维护 capability/shape profile；不支持特性时路由、填充/分桶或降级模型。'],['哪些 CUDA 优化不能直接迁移？','如何定位算子不支持？','国产卡适配先测精度还是性能？'],'这是岗位专项知识；如果没有实际 MLU 经验要明确没有，并给出可执行的迁移验证步骤。','困难',['寒武纪','Agent面经','MLU','CUDA'],'高压'),
  X('agent','LLMOps','MagicMind 动态 Shape 会给 Agent 编排层带来什么约束？','不同输入长度、batch 和输出配置可能触发不同 Shape Profile、图编译或性能路径；编排层要分桶、限制范围、缓存 Engine 并避免每个请求产生新 Shape。',['按 Context Length/Batch 建 profile，如短中长队列；超范围请求截断、压缩、拆分或路由到支持动态范围的后端。','预热常用 Shape 并缓存编译产物，记录 model+precision+profile+runtime version；热更新避免编译风暴。','Batcher 只合并兼容 Shape，Padding 会浪费算力；调度同时优化吞吐、TTFT 和显存，不能只追求大 batch。'],['动态 Shape 与静态图谁更快？','Profile 数量越多越好吗？','长短请求如何避免互相阻塞？'],'可把这层封装进 Model Gateway/Runner Capability，不让业务 Workflow 写满硬件 if/else。','困难',['寒武纪','Agent面经','MagicMind','Dynamic Shape'],'深挖'),

  // ── 三面：权衡、责任、热更新、AI Coding、源码判断 ─────────────
  X('agent','多Agent','主导 Agent 项目时怎样拆分子 Agent 职责，并处理与开发模块的边界冲突？','按不可混淆的职责、权限、状态所有权和可验收产物拆分，而不是按角色名称拆；冲突通过接口契约、RACI和最终真值写入者解决。',['只有需要不同工具权限、独立上下文或可并行产物时才拆 Agent；普通确定性逻辑留给代码服务。','为每个 Agent 写 input/output Schema、allowed tools、SLA、failure owner 和 acceptance tests；共享状态由一个服务/API提交。','与开发冲突时回到业务不变量和数据所有权，记录 ADR；先做纵向最小链路再拆团队和服务。'],['Planner 与业务后端谁拥有状态？','子 Agent 太多怎么合并？','如何证明拆分有效？'],'可说明你在国防项目负责的真实模块；“主导”必须有需求、设计、实现或协调证据，不要扩大个人职责。','困难',['寒武纪','Agent面经','Ownership','RACI'],'高压'),
  X('agent','成本','算法同学希望增加 LLM 调用提升效果，工程上怎样核算是否值得？','比较增量质量收益与每请求新增 Token、延迟、失败面和峰值容量，用离线消融、Shadow和小流量A/B决定，而不是只看最好案例。',['先定义目标切片和业务价值，如成功率提升1个百分点减少多少人工；计算月调用量×输入/输出Token/硬件时和重试放大。','增加一次调用还会增加 p95、Provider/国产卡队列、故障概率和上下文传播错误；可用小模型/规则/并行或只对低置信样本调用。','设质量下限和成本/延迟预算，报告置信区间与 break-even；无显著收益就保持简单链路。'],['两次独立调用成功率怎样估？','并行调用会降低延迟吗？','如何计算自建芯片成本？'],'回答要用“边际收益”，不要默认更多推理等于更强 Agent。','困难',['寒武纪','Agent面经','Cost Model'],'高压'),
  X('agent','可靠性','Agent 线上无限循环、步数爆炸、成本过高时优先调整哪三个开关？','优先收紧停止/无进展判定、工具与规划动作空间、上下文和模型路由；外部最大步数只是最后保险，不能替代根因治理。',['第一看 Trace 建重复状态/Action 指纹、完成判据和 Evidence增量，连续无进展立即重规划或停止。','第二缩小每状态可选工具与分支，限制递归/并发 fan-out，对昂贵动作做策略审批。','第三压缩历史和 Tool Result、缓存稳定结果、低复杂任务路由小模型；同时设置外部 steps/token/time/cost operational guard。'],['为什么只降低 max_steps 不够？','循环检测用什么指纹？','工具成功但状态不变怎么办？'],'注意区分一般生产 Agent 的资源限制与 AV 最新方法内部是否暴露科学预算，后者以最新 `av.md` 为准。','困难',['寒武纪','Agent面经','Loop Control','Cost'],'高压'),
  X('agent','RAG评测','知识库过期导致召回全部错误，Agent 仍编造答案时怎样治理？','数据层建立版本、时效和失效传播，检索层过滤过期并检测证据不足，生成层只基于带时间来源回答和拒答，监控层用时效切片持续回归。',['每文档保存 valid_from/to、source、updated_at和索引版本；CDC/事件驱动更新并删除旧向量、缓存、摘要和图谱边。','Query 带 as_of/业务时间，冲突时优先权威新源并向模型展示时间；没有有效证据就澄清/拒答而非调用参数记忆。','建立 stale-answer、temporal QA 和已删除事实测试，线上追踪引用版本、过期命中率与数据更新 SLA。'],['双索引切换如何零停机？','缓存怎样同步失效？','旧文档能否用于历史查询？'],'可以联系安全目标版本/Scope：结论必须绑定确切版本，旧证据不能自动外推。','困难',['寒武纪','Agent面经','Freshness','Temporal RAG'],'高压'),
  X('agent','可观测性','多 Agent 错误回答怎样定位到具体节点、模型和工具调用？','建立统一 run_id、trace_id、agent/node/attempt span 和 Artifact lineage，记录每次状态版本与输入输出引用，再从最终 Claim 反向追踪首次引入错误的位置。',['消息/Handoff带 parent span、source agent、schema version 和 input hashes；Tool Call记录参数、权限决策、原始结果与重试。','状态写入记录 before/after version、writer和因果事件；最终回答的引用映射到检索候选和索引版本。','用 failure taxonomy 区分检索、模型、工具、编排、数据和权限问题，支持确定性 replay或最小重现。'],['全量 Prompt 能否都记录？','跨服务 Trace 怎样关联？','并行分支错误如何归因？'],'AV 的 Action Lineage、Artifact Basis 和 exact Revision binding 是更强的领域责任链。','困难',['寒武纪','Agent面经','Responsibility Trace'],'必背'),
  X('agent','框架生态','LangGraph 子图复用、动态子 Agent 注册和图热更新怎样设计？','子图以稳定输入输出 State 契约封装；动态 Agent 通过版本化 Registry 解析为允许的子图/工具；热更新使用图版本路由和旧会话固定版本，不在运行中替换半条图。',['子图 namespace 避免 State 字段冲突，入口/出口做 Schema adapter；复用前明确是否共享 Checkpointer和消息 Reducer。','Registry保存 capability、version、owner、permissions、health和artifact digest，动态注册先通过测试与策略签名。','新请求灰度到新图，旧 thread留在旧版本或显式迁移；预加载/预编译并支持一键回滚，配置中心只发布不可变版本。'],['动态注册会不会造成任意代码执行？','子图 Checkpoint 如何嵌套？','如何做跨版本 replay？'],'如果没有真实 LangGraph 源码经验，应说明设计思路并通过最小 PoC 验证 API 细节。','困难',['寒武纪','Agent面经','Subgraph','Hot Reload'],'深挖'),
  X('agent','Coding Agent','AI Coding 从单测生成到补丁上线的完整工程链是什么，哪一步最危险？','在隔离 Worktree 建立失败复现→生成/审核测试→最小 Patch→静态检查/测试→安全扫描→人工/策略审批→Canary→可观测回滚；最危险通常是把未充分验证的补丁或测试在高权限真实环境执行。',['生成测试要防只复述实现和过拟合，隐藏测试/属性测试验证；Patch不覆盖用户改动并检查依赖/锁文件。','沙箱限制网络、Secret、Docker Socket和资源，构建产物签名；测试通过只证明覆盖路径，不等于业务/安全正确。','部署采用 feature flag/canary、数据库兼容和自动回滚阈值，关联 patch、CI、镜像和线上 Trace。'],['单测由同一个模型生成可靠吗？','回滚遇到数据库迁移怎么办？','补丁应用冲突如何处理？'],'Workflow-Harness 当前重点在调查和 Artifact，不要声称已经实现完整自动上线链路。','困难',['寒武纪','Agent面经','Patch Pipeline','Sandbox'],'高压'),
  X('agent','框架生态','LangGraph+自研 Harness、AutoGen 和 CrewAI 怎样做技术选型？','先按所需控制模型、持久恢复、完整 Coding Agent 接入、权限、Trace和团队维护能力做最小原型，而不是比较 star 或示例数量。',['LangGraph适合显式 State/循环/Checkpoint；AutoGen适合对话式多 Agent实验；CrewAI上手快偏角色/任务编排；自研 Harness负责现成 Runner的进程、Session和Workspace。','建立场景矩阵测试：流式、HITL、Crash Resume、Tool/MCP、并发、Schema迁移、沙箱、观测、国产模型/芯片适配和升级破坏。','核心领域状态与接口外置，框架通过 Adapter隔离；如果简单代码足够就不引入重框架。'],['为什么不全自研？','框架锁定怎么降低？','两周 PoC 看哪些指标？'],'你们路线不是与 LangGraph 二选一：可由图编排业务节点，同时把完整 Coding Agent 作为 Runner Node。','困难',['寒武纪','Agent面经','Framework Selection'],'高压'),
  X('agent','框架生态','没有实际使用过一个 Agent 框架时，如何判断是否值得引入？','从维护活跃度、核心抽象、失败语义、扩展点、可观测、恢复、安全和迁移成本收集证据，再用代表性最小 PoC，而不是把文档功能列表当结论。',['读 quickstart 之外的 State/Executor/Checkpoint/Tool 核心源码、Issue/Release与破坏性变更，确认谁拥有模型循环和权威状态。','实现真实切片：一个工具失败、一次中断恢复、一次并行合并和一次版本升级，测代码量、可调试性、延迟与锁定。','给出 ADR：需求、候选、权重、证据、风险、退出方案和复审日期；明确“未使用过”的事实。'],['GitHub Star 有多少价值？','怎样判断抽象泄漏？','什么时候 fork 框架？'],'这是三面判断力题，诚实的证据化评估优于假装有生产经验。','中等',['寒武纪','Agent面经','Framework Evaluation'],'必背'),
  X('agent','评测','评价一个硬核 Agent 开源项目或源码时，应从哪些方面指出优缺点？','先复现其核心路径，再从状态模型、工具权限、恢复、观测、评测、扩展和失败边界评价；缺陷必须绑定代码/实验而非个人偏好。',['读入口、Agent Loop、State/Memory、Tool Executor、Checkpoint和测试，画出谁拥有控制与状态；运行一个正常和两个失败案例。','检查是否只提供 Demo、是否把聊天当真值、是否缺幂等/沙箱/版本迁移、评测是否数据泄漏，以及并发/长上下文成本。','提出最小可验证改进和 trade-off；例如加入持久化可能提高可靠性但增加Schema迁移与存储复杂度。'],['如何避免只看 README？','最大缺陷怎样排序？','源码与论文不一致怎么办？'],'可以选择你真正读过的 LangGraph、MCP SDK、Coding Agent或安全工具；准备确切文件/类和卡点。','困难',['寒武纪','Agent面经','Open Source Review'],'深挖'),
  X('agent','LLMOps','可用算力只有 A100 方案的 60% 时，Agent 系统优先裁剪什么？','先保主链路正确性和安全：减少非必要反思/多 Agent/重复检索，路由小模型、限制上下文与候选、缓存和批处理；不裁权限校验、关键证据和恢复能力。',['用 Trace找 Token、Prefill、Decode、Rerank和工具等待占比；高频简单意图走规则/轻量模型，复杂任务才用强模型。','降低 Agent fan-out/反思轮次，Hybrid首召回后只对困难Query Rerank，父子索引减少注入Token；量化/分桶/continuous batching提高芯片利用率。','保留 Guardrail、Tool Policy、Checkpoint和核心评测；按质量降级曲线选择方案并对 p95/成功率/成本重新做容量规划。'],['为什么先裁多 Agent？','小模型路由错了怎么办？','量化与减少上下文谁先做？'],'回答要明确 60% 是吞吐、显存还是单卡算力约束，不同瓶颈的裁剪顺序不同。','困难',['寒武纪','Agent面经','Resource Constraint','国产算力'],'高压'),
  X('agent','评测','近半年读过最难的论文或源码，应怎样讲出真正的理解过程？','用问题背景→核心抽象→关键算法/代码路径→卡点→验证方法→对项目判断的改变组织，至少给一个自己纠正过的误解。',['论文说明假设、方法、实验与威胁有效性；源码说明入口、核心数据结构、控制流、测试和一次调试/修改。','卡点要具体到公式、状态迁移、异步语义或文件/类，解决可通过最小实验、断点、Trace、对照实现和Issue。','最后讲未解决问题和为什么没有照搬；不能只复述摘要或README。'],['你如何确认自己理解正确？','复现结果不一致怎么办？','这次阅读改变了哪个设计？'],'可优先准备最新 `av.md` 相关方法来源、LangGraph Checkpoint/Reducer或实际 Coding Agent Runner Adapter源码。','中等',['寒武纪','Agent面经','Paper Reading','Source Code'],'必背'),

  // ── 算法变形题 ───────────────────────────────────────────────────
  X('algorithm','字符串','日志流中提取意图标签并去重保序，和 LeetCode 316 有什么区别？','若只要求首次出现顺序，用 HashSet+列表一次扫描；若要求删除重复后字典序最小，则使用单调栈、剩余计数和 inStack，属于 316。',['先澄清“保序”是保留首次出现，还是可删除字符后取字典序最小；两者算法完全不同。','普通去重：解析每条日志标签，未见过则加入 Set 和结果，时间 O(n)；大流可分区但全局顺序需 offset/单写聚合。','316：当前字符更小且栈顶后面还会出现时弹栈；字符已在栈中则跳过。'],['标签解析失败怎么办？','流数据不能全存内存怎么办？','为什么 316 需要 last/remaining？'],'可联系意图识别日志，但面试先澄清题意，不要看到“去重保序”就机械套单调栈。','中等',['寒武纪','算法面经','HashSet','单调栈'],'必背'),
  X('algorithm','状态机','如何实现最简 ReAct 循环模拟器并检测循环？','把 `(state, pending_action, relevant_observation)` 规范化后做指纹集合；每步执行 action、更新状态，遇到终态返回，指纹重复则报告循环，类似 LeetCode 202。',['定义输入、Tool函数和 completed/error 状态；循环检测不能只看自然语言原文，应去除时间戳等噪声并保留影响决策字段。','Set检测简单 O(n) 空间；若状态转移完全确定可用快慢指针 O(1)，但真实Agent含外部非确定输入通常更适合Set。','再加无进展计数、最大外部步骤保险和完整轨迹，区分真正循环与相同动作处理不同对象。'],['哈希碰撞怎么办？','工具结果非确定时能用 Floyd 吗？','重复状态是否一定应该停止？'],'可联系 Agent 无限循环和 Action fingerprint。','中等',['寒武纪','算法面经','Cycle Detection','ReAct'],'必背'),
  X('algorithm','图','工具调用 DAG 怎样求合法执行顺序和最长关键路径？','先用 Kahn/DFS拓扑排序检测环；在拓扑序上做 DAG 动态规划，`dist[v]=max(dist[v],dist[u]+duration[v])`，最大值即关键路径长度。',['由依赖 `u→v` 建邻接表和入度，Kahn弹出入度0节点即合法顺序；处理节点数不足说明有环。','若节点耗时，初始化源点 dist为自身耗时并保存 predecessor重建关键路径；多个合法顺序可按优先队列稳定输出。','并行总时长由关键路径决定，但还需考虑资源容量、工具互斥和失败重试，DAG算法只覆盖理想依赖。'],['怎样输出具体关键路径？','有环时如何报告环？','资源受限后还是关键路径吗？'],'对应 Tool DAG 调度和国产算力下的并行规划。','困难',['寒武纪','算法面经','Topological Sort','Critical Path'],'高压'),

  // ── HR 与岗位动机：不编造个人事实，使用回答框架 ────────────────
  X('agent','求职表达','为什么选择寒武纪 Agent 岗位，而不是互联网大厂大模型团队？','从岗位问题、国产软硬件协同和自身安全×Agent工程经历的匹配回答，而不是贬低其他公司；说明希望在受约束真实系统中做可验证落地。',['岗位吸引点可落在 MLU/MagicMind、推理效率、企业Agent和软硬件协同，但面试前核对真实JD与团队方向。','自身匹配：Coding Agent Harness、RAG/MCP、异常恢复和安全权限；同时坦诚国产芯片实操短板及学习计划。','选择标准包括问题所有权、工程深度、成长和长期价值，避免空喊情怀或只谈股票。'],['为什么不是模型算法岗？','国产生态短板是否担心？','还有哪些Offer？'],'最终答案必须由你自己的真实动机构成，本题只提供组织框架。','中等',['寒武纪','HR面经','求职动机'],'必背'),
  X('agent','求职表达','Agent 工程中哪项能力最容易被低估？','可选择“状态与失败工程”：Demo关注模型能否完成一次，生产更依赖可恢复状态、幂等、权限、Trace和异常归因。',['用一个真实失败说明：模型聪明但Tool超时/Session丢失/状态重复提交仍会让系统不可用。','说明采取的结构化状态、Artifact、Retry分类、Workspace隔离或评测措施，以及可观察结果。','不要泛泛说“沟通很重要”，要把被低估能力连接到业务风险和自己做过的工作。'],['为什么模型能力不能解决？','你在哪次项目中学到？','如何衡量这项能力？'],'Workflow-Harness 和 AV 都适合回答，但不要混写两者职责。','中等',['寒武纪','HR面经','工程判断'],'必背'),
  X('agent','求职表达','怎样回答与算法同学合作的最大冲突案例？','使用 STAR：共同目标和约束→具体分歧与证据→怎样做实验/决策→结果与复盘，避免把对方描述成不懂工程。',['可选“增加LLM调用 vs 成本/可靠性”类真实案例，量化质量收益、延迟、失败率和算力。','说明自己先复述对方目标，再提出最小对照、决策规则和可回滚方案；若最终采纳对方方案也要坦诚。','复盘接口、职责或指标为什么一开始不清楚，以及以后怎样提前对齐。'],['如果仍无法达成一致怎么办？','谁最终拍板？','你做错了什么？'],'必须使用真实经历，不要照抄假案例。','中等',['寒武纪','HR面经','协作'],'必背'),
  X('agent','求职表达','怎样看待国产算力，工程落地最痛苦的点是什么？','价值在供应链自主和软硬件共同优化，困难通常是算子/工具生态、转换精度、动态Shape、调试与性能可观测，需要以迁移测试而非口号回答。',['先承认自己实际使用边界；无MLU经验时不要假装调过算子，可类比CUDA/模型部署并给学习验证计划。','工程痛点分兼容、精度、性能和运维：每层建立golden输入、逐层误差、profile和回归。','强调国产适配不是简单替换device字符串，需要模型、编译器、runtime、batcher和编排共同设计。'],['你愿意处理生态不成熟问题吗？','两周怎样上手MLU？','如何评价国产与CUDA差距？'],'保持客观、具体和尊重事实。','中等',['寒武纪','HR面经','国产算力'],'常规'),
  X('agent','求职表达','薪资和股票预期怎样回答更稳妥？','先了解岗位级别、现金、奖金、股票归属、行权/流动性、福利和工作地点的总包结构，再给基于市场与职责的合理区间并表达可综合讨论。',['没有当前薪资就明确应届，不虚构；期望可参考同岗位市场、其他机会和最低可接受约束。','“降现金换股票”要看公司阶段、授予数量/价值口径、vesting、离职处理和风险承受，不只看宣传估值。','避免过早给单点底价，可先询问职级和薪酬结构；最后保持一致口径。'],['最低接受多少？','股票能否替代现金？','是否有其他Offer？'],'本题涉及个人决策，网站不替你设具体数字。','简单',['寒武纪','HR面经','薪资'],'常规'),
  X('agent','求职表达','入职前三个月优先打通哪条业务链路？','先选一个高价值、边界清晰、可评测的纵向最小链路，从真实请求到工具结果和反馈闭环，再补可靠性、评测与规模化，而不是先造通用平台。',['0–30天理解用户、现有架构、MLU推理链和指标，复现基线与主要失败；不急于重构。','30–60天打通一个意图→检索/规划→受限工具→结果的 E2E，用 Trace/Eval/Guardrail 建最小生产闭环。','60–90天针对最大瓶颈做灰度优化，补Checkpoint、成本、权限和Runbook，形成可复制模板与下一季度路线。'],['为什么选这条链？','前三个月如何衡量成功？','现有系统很乱怎么办？'],'结合真实JD修改，优先项不能脱离团队业务。','中等',['寒武纪','HR面经','90 Day Plan'],'必背')
);
;
/* 新投递岗位专项：AI 应用、AI for Code Security 与 AI 安全运营。 */
QUESTIONS.push(
  X('agent','AI应用工程','设计一个可上线的 Agent 应用，完整分层是什么？','从接入层、任务与编排层、模型/RAG层、Tool/MCP层、State/Memory层、执行沙箱和Eval/Trace/Guardrail层分开设计。',['接入层负责身份、租户、限流、SSE/WebSocket和请求幂等；长任务进队列，返回task/run id。','编排层维护State、路由、中断和预算；RAG提供有来源事实，Tool Gateway执行鉴权、Schema校验、超时和审计。','权威State进Postgres等持久库，热Session/租约可进Redis，大Artifact进对象存储；全链记录Trace并用离线Eval与线上SLO回归。'],['为什么不同步一次请求做完？','哪层拥有最终业务状态？','如何支持多模型降级？'],'OPPO/通用AI应用岗的系统设计主题；可用两个项目分别举Runner和MCP例子。','困难',['OPPO','AI应用','系统设计'],'高压'),
  X('backend','Agent后端','为什么 Agent 长任务通常需要异步队列？','模型与工具链路耗时、可暂停且易受外部故障影响，异步任务能解耦HTTP连接与执行生命周期，支持排队、恢复、取消和背压。',['API建立run并返回ID，Worker持有短期租约执行，客户端通过SSE/轮询获取进度。','队列常是至少一次投递，每个Action要有幂等键、可见性超时、心跳、重试上限和死信处理。','取消是持久化的desired state；Worker在安全点检查取消，向模型和子进程传播，并保留已发生副作用的记录。'],['队列中一条消息被消费两次怎么办？','客户端断开是否应取消任务？','如何避免长任务饿饿？'],'可连接Harness的Run ID、Resume、取消与accepted-but-uncommitted问题。','困难',['OPPO','Task Queue','Async Agent'],'必背'),
  X('backend','Agent后端','Redis、MySQL/Postgres、MQ 和对象存储在 Agent 系统中怎样分工？','Redis适合热Session、缓存、限流和短租约，关系库保存权威任务/State与审计索引，MQ解耦异步任务，对象存储保存大日志和Artifact。',['Redis快但不宜默认作长期唯一真值；淘汰、持久化和事务语义需结合业务要求。','关系库使用revision/CAS、事务与唯一约束防重复提交；向量索引是召回投影，不是业务权威状态。','MQ中只放任务ID和小型命令，大Prompt/文件通过有权限和hash的引用读取，避免消息膨胀与敏感数据扩散。'],['Kafka和RocketMQ什么时候需要？','Redis Stream可以替代MQ吗？','Artifact为什么要内容寻址？'],'泛AI应用岗必须会的存储边界题。','中等',['OPPO','Redis','MQ','Postgres'],'必背'),

  X('security','程序分析','AST、CFG、DFG、Call Graph 和 CPG 分别表示什么？','AST表示语法结构，CFG表示可能执行转移，DFG表示值与定义使用传播，Call Graph表示跨函数调用，CPG把多种程序图统一供关联查询。',['AST能找语法模式但不表示运行顺序；CFG加入分支、循环和异常边，是可达性/路径分析基础。','DFG/污点分析追踪Source到Sink之间的传播；Call Graph对虚调用、反射和动态语言常只能近似。','CPG方便表达“某调用参数来自外部且所在基本块受某条件支配”，但不自动解决框架建模和动态语义。'],['PDG是什么？','Call Graph越大越准吗？','CodeQL与Joern分别怎样使用这些表示？'],'字节AI for代码分析岗的底层基础题。','中等',['字节','SAST','AST','CFG','CPG'],'必背'),
  X('security','程序分析','Context-sensitive、Path-sensitive、Flow-sensitive 和 Alias Analysis 是什么？','它们分别区分调用上下文、分支路径条件、语句执行顺序和多个引用是否指向同一对象，用精度与成本换取更少误报。',['上下文不敏感会把不同调用者的信息合并；常用call-site、object-sensitive或有限k长上下文折中。','路径敏感能利用`if (isAdmin)`等约束排除不可行路径，但路径数会指数爆炸，需合并、剪枝或SMT。','Alias不准会使数据流既断链又污染过广；指针、容器、字段敏感和动态语言尤其难。'],['为什么不能全部做最强精度？','污点分析一定是flow-sensitive吗？','如何评估分析可扩展性？'],'用来回答SAST的Precision/Recall/Scalability三角权衡。','困难',['字节','Program Analysis','Context-sensitive','Alias Analysis'],'高压'),
  X('security','程序分析','SAST 为什么会误报和漏报？','误报常来自保守近似、缺少业务/框架约束；漏报常来自Source/Sink、传播步、语言前端、反射/动态特性或跨组件建模不完整。',['把所有调用都当可达、把自定义校验当未净化、忽略权限/默认配置会制造误报。','未识别ORM/Template的Sink、异步消息传播、隐式流或代码生成会漏报。','治理用可解释路径、框架模型、负例回归、分类严重度和动态验证；不应为了零误报把召回压没。'],['怎样构建SAST规则的测试集？','误报率和Precision什么关系？','开发人员点“误报”就是Ground Truth吗？'],'回答时主动说明静态分析结果是Candidate，不是完整漏洞结论。','中等',['字节','SAST','False Positive','False Negative'],'必背'),
  X('security','AI for Code','LLM/Coding Agent 为什么不能直接替代 SAST，两者如何结合？','SAST提供稳定、可规模化和可回归的程序关系搜索，LLM擅长理解上下文、生成假设、调用工具与构造验证；结合比互相替代更可靠。',['SAST可产生Source-Sink路径、库调用和规则命中，作为Agent可追溯的候选与定位索引。','LLM可辅助规则迁移/生成、路径语义解释、框架建模建议、误报分流、PoC/测试构造和修复草案。','必须保留规则回归集、原始路径、确定性验证和人工Gate；不能让模型的自然语言解释覆盖分析事实。'],['LLM生成CodeQL规则怎样测？','怎么评估AI误报分流？','用Embedding找漏洞是SAST吗？'],'与AdaptiveVuls关系：SAST/Fuzz是获取Artifact的能力，Coding Agent组织开放Investigation Space。','困难',['字节','AI for Code','SAST','Coding Agent'],'高压'),
  X('security','AI for Code','自动漏洞修复从 Finding 到合入需要哪些 Gate？','先确认Finding与失败复现，再生成最小Patch，通过安全回归、正常功能、静态/动态分析、Diff审核、沙箱CI和人工准入后才能合入。',['先保存修复前能触发的安全测试/证据，修复后要“攻击输入失败 + 合法输入继续成功”，并检查同类旁路。','防止模型同时生成Patch和唯一测试导致共同过拟合；使用隐藏测试、属性测试、已知负例和独立Reviewer。','检查API/数据兼容、性能、依赖/锁文件、日志与配置改动；高风险库采用人工批准和渐进灰度。'],['测试全过为什么还不够？','如何防止Patch只禁用功能？','修复失败怎样回退？'],'字节DevSecOps与自动Patch方向的高频系统题。','困难',['字节','Automated Repair','Patch Verification','DevSecOps'],'高压'),

  X('security','AI安全运营','安全告警研判 Agent 的完整链路怎样设计？','将告警标准化后补齐资产、身份、情报与历史，形成可验证假设，通过受限查询/检测工具求证，给出分级、证据和处置建议。',['输入日志、邮件、网页和情报都可被攻击者控制，只能当数据；不能让日志文本直接生成Shell/封禁动作。','工具使用每用户/任务短凭证，只读查询与有副作用处置分权；结论引用原始事件、查询结果和时间窗。','低风险可自动补上下文/去重，高风险封禁、隔离、删除或权限变更需Dry-run、人工审批、幂等与回滚。'],['怎样评估研判正确性？','恶意日志如何做Prompt Injection？','哪些动作可以自动化？'],'蚂蚁AI安全工程与Agentic SOC的典型场景。','困难',['蚂蚁','AI for Security','SOC','告警研判'],'高压'),
  X('security','AI安全运营','如何评测安全运营 Agent？','同时评测告警召回/精度、分级与根因、证据完整性、调查时间、人工接管、越权/误处置和恢复成本，不能只看最终自然语言结论。',['数据集包含真实事件、良性噪声、模糊告警、缺失数据、对抗日志和多阶段攻击，以时间/资产类型分层。','过程指标检查是否查对资产、时间窗、工具与参数，是否正确理解结果并避免重复/无进展循环。','处置指标区分“建议正确”和“实际副作用正确”；用Shadow/演练逐步放开自动权限。'],['Ground Truth不完整怎么办？','如何统计MTTD/MTTR？','安全Agent误杀率怎样计算？'],'可同时展示你在Agent Eval和安全两条线的交叉能力。','困难',['蚂蚁','Security Agent Eval','SOC'],'高压'),
  X('agent','求职表达','为什么你同时投AI应用、AI测开、AI for Code和AI安全，方向不散吗？','这些岗位共享Agent系统工程底座，只是对质量、代码分析或安全治理的业务纵深不同；我的定位是以Agent系统工程为横向能力，以漏洞与安全研究为领域纵深。',['共同底座包括Workflow/Harness、State/Context/Memory、Tool/MCP、RAG、Eval、异常恢复和后端工程。','OPPO偏应用架构，百度偏Eval/质量，字节是AI+Code+Security，阿里/蚂蚁偏Agent for Security与Security for Agent。','两个项目正好覆盖两种路线：一个从RAG、Planner、MCP和状态机搭领域Agent，一个把成熟Coding Agent作为Runner做长程Harness。'],['你最想去哪一类岗位？','如果做纯业务AI你的安全经验有什么用？','为什么不只投安全？'],'这是新投递图谱的统一口径，但面试某家公司时要将答案收束到对方业务。','简单',['投递定位','OPPO','字节','阿里','蚂蚁'],'必背')
);

/* 字节程序分析底层：避免只会背 AST/CFG/DFG 名词。 */
QUESTIONS.push(
  X('security','程序分析底层','Basic Block、Dominator、Post-Dominator 和 Control Dependence 是什么？','Basic Block 是只有单入口、单出口且内部顺序执行的最大语句序列，是 CFG 的基本节点；如果从入口到节点 B 的所有路径都经过 A，那么 A 支配 B，常用于判断某项检查是否必然发生在危险操作之前；Post-Dominator 方向相反，表示从节点到出口的所有路径都经过某节点；Control Dependence 描述一条语句是否因为某个分支结果才执行，通常可以结合 Post-Dominator 推导。漏洞分析中它们能回答“鉴权是否支配敏感操作”“某个 Sink 是否只在校验成功分支可达”，但异常边和提前返回必须进入 CFG，否则结论会失真。',[],['循环中的支配关系怎么计算？','异常处理为什么会改变Dominator？'],'程序分析底层高频概念，回答要连接鉴权与Sink。','困难',['字节','CFG','Dominator'],'高压'),
  X('security','程序分析底层','SSA、Phi 节点和 Def-Use Chain 有什么作用？','SSA 要求每个变量只被定义一次，分支汇合时用 Phi 节点表示值可能来自不同前驱，例如条件两侧分别给 x 赋值后，在合流点写成 x3=phi(x1,x2)。这样每次使用都能明确连接到定义，便于常量传播、污点分析、死代码消除和路径约束构建；Def-Use Chain 正是定义到使用之间的关系。SSA 通常建立在 IR 上，不代表源码变量真的只能赋值一次，内存、指针、对象字段和别名还需要 Memory SSA、Points-to 或保守建模。',[],['Phi 是运行时真实执行的指令吗？','内存对象怎样进入SSA？'],'用于讲清DFG和编译器IR，不停留在“值怎么流”。','困难',['字节','SSA','Def-Use'],'高压'),
  X('security','程序分析底层','数据流分析中的格、Transfer Function、Join、Worklist 和不动点是什么？','数据流分析会为每个程序点维护一个抽象状态，例如可能到达的定义或污点集合；这些状态按信息精度形成有限高度的偏序格，Transfer Function 根据当前语句更新状态，多个控制流前驱在 Join 处合并。算法把入口事实放入 Worklist，反复传播发生变化的节点，直到所有状态不再变化，也就是达到不动点。May Analysis 常用并集保召回，Must Analysis 常用交集表达所有路径都成立。单调性和有限高度保证终止，循环中的状态会经过多轮收敛；状态合并越粗，速度越快但误报通常越多。',[],['为什么循环需要迭代？','May和Must分析分别适合什么？'],'这是静态分析原理核心，能够明显区分会用工具和理解分析。','困难',['字节','Dataflow','Fixed Point','Worklist'],'高压'),
  X('security','程序分析底层','抽象解释是什么，为什么静态分析需要在精度和可扩展性之间取舍？','抽象解释把无法穷举的具体程序状态映射到可计算的抽象域，例如用区间表示整数可能范围、用符号集合表示对象类型，并通过抽象 Transfer Function 近似执行程序。为了保证 Sound 的 over-approximation，分析通常宁可包含不可能路径，也不漏掉可能行为，因此会产生误报；抽象域越细、路径和上下文区分越强，状态数和合并成本越高。遇到无限上升链还要使用 Widening 加速收敛，必要时用 Narrowing 恢复部分精度。工程上不会追求所有维度最强，而会按漏洞类型选择字段、上下文、路径和数值精度。',[],['Sound 是否等于没有漏报？','Widening 为什么会损失精度？'],'面试不必推公式，但必须讲清“具体状态→抽象域→保守近似”。','困难',['字节','Abstract Interpretation','Precision'],'高压'),
  X('security','程序分析底层','Points-to Analysis 与 Alias Analysis 有什么区别和价值？','Points-to Analysis 计算一个指针或引用可能指向哪些抽象对象，Alias Analysis 则回答两个表达式是否可能或必然引用同一对象，后者常由前者推导。它们决定字段写入、对象状态和污点能否正确传播：如果分析过粗，两个实际无关对象会被合并而产生误报；如果漏掉别名，数据流会断链而漏报。常见折中包括 flow-sensitive 或 flow-insensitive、context-sensitive、field-sensitive，以及 Andersen 的 inclusion-based 和 Steensgaard 的 unification-based 思路；动态语言、容器、反射、函数指针和并发会进一步增加难度。',[],['May-alias和Must-alias有什么区别？','为什么Points-to分析通常很贵？'],'虽然已有Sensitivity题，这道专门补全指针与对象传播机制。','困难',['字节','Points-to','Alias Analysis'],'高压'),
  X('security','程序分析底层','符号执行和传统数据流分析有什么区别？','符号执行用符号值代替具体输入，沿每条路径积累约束并交给 SMT Solver 判断可满足性，因此能够生成触发输入、排除不可行路径并验证具体漏洞条件；传统数据流分析更倾向在 CFG 上合并抽象事实，覆盖规模更大但路径精度更粗。符号执行的主要瓶颈是路径爆炸、复杂库和环境模型、循环以及 Solver 成本，常用路径合并、搜索策略、循环边界、Concolic Execution 和函数摘要折中。安全系统常让 SAST 先大范围召回，再用符号执行或动态实验验证少量高价值候选。',[],['Concolic Execution是什么？','SMT可满足是否等于漏洞可利用？'],'用于回答静态召回和路径验证怎样协同。','困难',['字节','Symbolic Execution','SMT'],'高压'),
  X('security','程序分析底层','一条 SAST 规则从设计到上线应该经历什么？','我会先把漏洞描述收敛成明确的代码语义：Source、Sink、传播、Sanitizer、路径和适用框架，再选择 AST 模式、局部数据流或跨过程污点规则实现。测试集必须包含最小正例、相似安全负例、不同语言特性、框架封装和历史真实样本，并对每个误报漏报标注根因。查询通过编译和性能检查后，在代表性仓库 Shadow 运行，比较 Recall、Precision、单仓耗时和结果稳定性；上线时绑定规则版本、严重度、Owner、Baseline 和豁免期限，先灰度再进入 Gate。后续根据开发处置、真实逃逸和框架升级持续回归，不能把“查询能运行”当成规则已经可生产。',[],['正例和负例最少要覆盖哪些变化？','规则升级后历史告警怎么处理？'],'把职位要求“规则或平台实际开发”整理成完整工程生命周期。','困难',['字节','SAST Rule Engineering','Regression'],'必背')
);

/* 2026-08-13 11:00 字节 AI for代码分析一面：按职位 A124030B 的三项职责补齐。 */
QUESTIONS.push(
  X('security','字节一面冲刺','为什么你适合字节的 AI for代码分析岗位？','我的匹配点是 AI for Code、真实漏洞和长程 Agent 工程三者已经形成闭环。AdaptiveVuls 复用 Codex、Claude Code 等强 Coding Agent，在完整仓库中组织代码阅读、程序分析、PoC、动态实验和独立复核；Hermes 等案例证明我能从信任边界和代码路径出发发现、复现并私下报告真实漏洞；国防项目则让我具备 Planner、RAG、MCP 和工具执行经验。这个岗位要把 AI 漏洞检测、自动修复和 DevSecOps 连起来，我能贡献的是让模型理解上下文、让 SAST/Fuzz 提供确定性关系和运行证据，再用 Artifact、测试和 Policy Gate 控制结果。当前我需要继续补的是大规模 SAST 规则与平台实操，但底层程序分析概念、漏洞验证和 Agent Runtime 能力是连贯的。',[],['你和做过多年CodeQL平台的人相比优势是什么？','入职第一个月准备补什么？'],'开场先贴职位三项职责，再诚实说明SAST平台差距。','简单',['字节','A124030B','岗位匹配'],'必背'),
  X('security','字节一面冲刺','你没有完整 SAST 平台开发经历，为什么仍然投这个岗位？','我不会把自己包装成已经主导过企业级 SAST 平台的人，但我具备这条岗位链路中相邻且可迁移的能力：能够阅读完整仓库、做控制流和数据流追踪、理解 Source、Sink、Sanitizer、跨函数调用与路径约束，并用 PoC、Sanitizer 和真实运行结果验证候选；同时我做过完整 Coding Agent 的 Runner、State、Artifact 和评测系统。对 CodeQL、Joern 和规则工程，我已经按“规则假设—正负样本—查询结果—动态验证—回归集”的方式补实操。我的价值不是回避差距，而是能把程序分析结果真正接入 Agent 调查、漏洞验证、自动修复和长期工程闭环。',[],['具体写过什么查询或规则？','怎么证明你不是只懂概念？'],'面试前必须准备一个亲手完成的CodeQL或Joern最小实操，不能只背本段。','中等',['字节','SAST经历','诚实边界'],'高压'),
  X('security','字节一面冲刺','如果让你在海量代码中建设 AI 漏洞检测能力，系统怎么设计？','我会采用“确定性程序分析召回 + AI 语义研判 + 动态证据验证”的分层架构。代码进入统一构建和语言前端后生成 AST、CFG、Call Graph、DFG 或 CPG，规则与污点分析先产生带 Source–Sink 路径、版本和代码位置的候选；增量分析只处理变更、受影响调用闭包和依赖更新。AI 层读取切片、调用上下文、框架模型和历史处置，对候选做漏洞条件补全、误报解释和验证计划，但不能修改原始程序关系。高价值候选进入隔离环境构造测试、PoC、Sanitizer 或差分验证，结果连同 Artifact 回写。平台用稳定规则集保召回，用模型提升 Precision 和处理长尾，并按语言、业务、漏洞类型和代码新旧分层评测，最后接入 PR Gate、告警与人工审核。',[],['模型直接扫整个仓库为什么不行？','增量调用闭包如何计算？'],'这是职位描述第一项的核心系统设计题。','困难',['字节','AI漏洞检测','海量代码'],'高压'),
  X('security','字节一面冲刺','AI 漏洞检测系统应该怎样评测？','我会把评测拆成数据、检测结果、过程和生产价值四层。数据集同时包含历史确认漏洞及修复版本、人工构造的规则正负例、真实业务误报、跨项目长尾和时间切分的新漏洞，避免同仓库相邻代码泄漏。检测层按漏洞类型和语言统计 Recall、Precision、PR-AUC、Top-K 命中与重复告警，不能只看总体 Accuracy；过程层检查 Source–Sink 路径、根因、可达性和证据是否正确；生产层看每千次提交新增告警、人工研判时间、开发接受率、漏洞逃逸率、扫描延迟和成本。模型非确定时要固定版本并多次运行；最终 Finding 由隐藏样本、动态复现或盲审确认，防止模型和 Judge 共享同一错误。',[],['Ground Truth不完整怎么办？','如何评估新型漏洞而非记住历史CVE？'],'明确区分候选召回、Finding正确和业务收益。','困难',['字节','Detection Eval','Benchmark'],'必背'),
  X('security','字节一面冲刺','LLM 生成或迁移 SAST 规则时，怎样保证规则质量？','我会把模型输出定义为 Rule Proposal，而不是可直接上线的规则。输入包括漏洞根因、目标语言/框架、Source、Sink、Sanitizer 和已知代码形状，模型生成查询后先通过语法与编译检查，再运行最小正例、相似安全负例、旁路样本和真实仓库回归；随后比较召回、误报、执行时间和重复结果，并由规则负责人审查数据流语义。规则必须绑定版本、测试集和适用范围，失败样本回到提示或框架模型更新。上线先 Shadow，再按语言与仓库灰度；任何自动修改只能提交 PR，不能让模型直接覆盖生产规则。',[],['测试集是否也是模型生成的？','规则误报很高但发现了一个严重漏洞怎么办？'],'对应职位要求中的规则或平台开发能力。','困难',['字节','SAST Rule','LLM Rule Generation'],'高压'),
  X('security','字节一面冲刺','自动漏洞修复系统怎样从告警生成高质量补丁？','我会先把告警收敛成可复现 Finding，保存触发输入、程序路径、根因、边界和失败测试，再让模型在最小代码上下文中生成一个或多个 Patch Candidate。补丁不是按表面 Sink 打补丁，而要匹配漏洞根因和项目既有修复模式，例如参数化查询、对象级授权、解析后精确校验或生命周期修复。每个候选都必须通过修复前失败修复后成功的安全回归、正常功能测试、同类旁路、静态/动态分析、构建、性能与兼容检查；再比较 Diff 大小、API变化和可维护性。模型生成和验证要隔离，隐藏测试与独立 Reviewer 防共同过拟合，最终以 PR 形式由代码 Owner 准入并支持回滚。',[],['如何避免补丁直接禁用功能？','没有现成PoC时怎样验证修复？'],'职位描述第二项的完整口述稿。','困难',['字节','Automated Repair','Patch Gate'],'必背'),
  X('security','字节一面冲刺','AI for Code 安全能力怎样接入海量业务 CI/CD？','我会把安全能力做成分级、增量和可回归的 DevSecOps 服务。PR 阶段读取 Diff、语言、依赖和受影响调用闭包，先运行低延迟确定性规则，对新增高置信问题阻断；复杂 AI 研判和动态验证异步执行，通过 Check Run 回写代码位置、证据、修复建议和状态。全量扫描、规则升级和模型升级在夜间或周期任务运行，结果用漏洞指纹去重并维护 baseline，避免历史存量淹没开发。Gate 按严重度、置信、代码所有者和业务风险分级，高风险强制处理，低置信进入 Review；平台还要支持缓存、任务队列、超时、降级、审计、SLO 和一键豁免到期。目标不是让 CI 永远不报错，而是在可接受延迟内稳定阻止新增高风险漏洞。',[],['AI分析太慢怎么办？','开发批量忽略告警怎么办？'],'职位描述第三项的核心系统题。','困难',['字节','DevSecOps','CI/CD'],'必背'),
  X('security','字节一面冲刺','超大 Monorepo 中怎样做增量静态分析？','核心是复用稳定中间结果并只重算受变更影响的部分。系统先为每个提交和构建配置生成可寻址的 AST、符号、调用图、数据流摘要与依赖图；收到 Diff 后识别修改函数、类型、配置和依赖，再沿反向调用、继承、数据流和构建依赖计算受影响闭包。未变化模块复用摘要，跨模块边界用函数 Summary 传播；公共库、接口 Schema 或分析规则变化时扩大失效范围。结果按规则、位置、调用上下文和根因指纹去重，并通过抽样全量扫描校准增量漏报。工程上还要处理生成代码、宏、反射、多语言 RPC 和构建失败，不能假设 Git Diff 就等于完整影响面。',[],['函数Summary保存什么？','怎么证明增量分析没有漏报？'],'海量业务落地很可能追问性能与增量。','困难',['字节','Monorepo','Incremental Analysis'],'高压'),
  X('security','字节一面冲刺','注入、越权、反序列化和内存安全在代码中分别怎么看？','我会统一按 Source、传播、Security Check、Sink、运行条件和影响分析，但每类重点不同。注入关注不可信数据是否跨越编码或参数化边界进入 SQL、Shell、模板等解释器；越权关注已认证主体对具体对象和动作是否重新做 Authorization，不能只看是否登录；反序列化关注攻击者是否控制可执行对象格式、是否存在可达 Gadget 和信任边界；内存安全关注长度、整数、生命周期和并发如何形成 OOB、UAF 等访问，再结合 ASan、布局可控性与缓解措施判断影响。SAST可以系统搜索这些关系，Agent补业务语义和验证，但任何一类都不能看到危险 API 就直接宣告漏洞。',[],['每一类最常见的误报来源是什么？','授权问题为什么难做纯静态分析？'],'直接贴职位要求第四项。','中等',['字节','漏洞代码场景','Source Sink'],'必背'),
  X('adaptivevuls','字节一面冲刺','AdaptiveVuls 与字节 AI for代码分析岗位怎么结合？','AdaptiveVuls 不替代字节已有的 SAST 平台，而是可以作为其上的调查和验证层。SAST 在海量仓库中稳定计算 Source–Sink、调用链和规则候选；Coding Agent 读取项目上下文，决定需要补哪些代码、配置、测试或动态实验；Workflow-Harness 保存 Direction、Artifact、Evidence、Session 和预算，让长任务能够恢复并避免结论只存在聊天记录里；Fresh Reviewer 再限制正式 Finding 和 Patch 的证据边界。进入 CI/CD 后，这套能力应收缩为风险分级的异步任务：高置信新增漏洞阻断，复杂候选进入 Agent 验证，修复候选走隐藏测试和 Owner Review。我的项目价值在于组织 Investigation Space，而不是声称取代 Program Relation Space。',[],['为什么不直接让每条SAST告警启动Agent？','Harness会不会让扫描成本不可控？'],'把个人项目准确贴到岗位，不贬低字节现有SAST能力。','困难',['字节','AdaptiveVuls','岗位结合'],'必背')
);
;
/* 百度 AI 测试开发 + 阿里星 Agent 安全岗位冲刺题。复用已有基础题，仅新增缺失的测试、评测、隐私和研究高压题。 */
QUESTIONS.push(
  // ── 百度：测试方法与岗位转换 ─────────────────────────────────────
  X('backend','测试开发','安全研究背景为什么适合 AI 测试开发？','漏洞研究是高难度质量场景，核心积累是定义正确结果、构造正负用例、注入失败、记录轨迹、独立复核并用指标判断复杂 Agent 系统。',['将漏洞“是否成立”映射为测试 Oracle，将环境失败/真实阴性区分映射为失败归因，将 Evidence Review映射为质量 Gate。','强调可迁移能力：Workflow、Runner、状态、Artifact、自动化、故障恢复和评测，而不是只说会渗透。','同时承认需补齐移动端业务测试、Pytest平台和大规模质量运营，用具体学习/落地计划回答。'],['为什么不继续纯安全？','你做过传统测试吗？','安全结论和业务质量指标有何不同？'],'百度岗位表达应收束到“安全场景中的 Agent 质量工程”。','中等',['百度测开','岗位冲刺','岗位动机'],'必背'),
  X('backend','测试开发','测试开发与普通开发的核心区别是什么？','开发主要对功能交付负责；测试开发从质量风险出发，用代码、平台、数据、环境和监控提高缺陷发现与预防效率。',['测开同样需要工程能力，但需求来自风险模型、覆盖缺口、故障模式和质量反馈。','产物不只是脚本，还包括测试框架、数据平台、环境服务、故障注入、质量指标和准入 Gate。','优秀测开要理解业务实现并对测试自身的稳定性、误报、成本和维护负责。'],['测开是否只是写自动化？','测试代码需要单测吗？','质量最终由谁负责？'],'可联系 Harness：它把一次性 Agent 调用转为可恢复、可审计运行系统。','简单',['百度测开','岗位冲刺','质量工程'],'必背'),
  X('backend','软件测试','软件测试的完整流程是什么？','需求与风险分析后制定计划和策略，设计用例并准备环境数据，执行与跟踪缺陷，完成回归、质量报告、发布评估和复盘。',['需求阶段明确可测试验收标准、关键用户链路、非功能要求和不可接受风险。','执行阶段保留版本、环境、步骤、预期/实际、日志和证据；缺陷经过确认、修复、回归和关闭。','发布不是“用例全过”就结束，应报告覆盖、缺陷趋势、遗留风险、监控与回滚方案。'],['需求频繁变化怎么办？','什么时候停止测试？','测试计划包含什么？'],'将 Agent 的模型、Prompt、Tool、数据集和环境版本纳入同一流程。','简单',['百度测开','岗位冲刺','Test Lifecycle'],'必背'),
  X('backend','软件测试','等价类、边界值、判定表、状态迁移和场景法如何选择？','输入域可分组用等价类，数值/长度边缘用边界值，多条件组合用判定表，生命周期行为用状态迁移，端到端业务用场景法。',['先从风险和规则建模再选方法，不是每个功能机械套齐所有术语。','状态迁移需覆盖合法/非法迁移、重复事件、超时、并发和恢复；Agent Run尤其适合。','组合爆炸时用正交/Pairwise缩减，但高风险交互必须显式保留。'],['边界值为什么容易出错？','因果图与判定表关系？','Pairwise能保证没有缺陷吗？'],'可把 Case/Review/Disposition 或 Job 状态作为状态迁移示例。','中等',['百度测开','岗位冲刺','Black Box'],'必背'),
  X('backend','软件测试','如何系统测试登录功能？','从功能、输入、状态、权限、安全、并发、依赖、性能和可用性分层覆盖，而不是只测正确/错误密码。',['覆盖空值/长度/编码、锁定和验证码阈值、MFA、找回、Session轮换/过期、Remember Me及多端登录。','安全覆盖用户名枚举、暴力破解、注入、CSRF、重放、开放重定向、Cookie属性和权限提升。','依赖故障、弱网、时钟偏差、并发请求、限流、审计和可访问性也需用例；关键业务建立自动化回归。'],['登录成功但跳转失败算什么？','账号锁定怎样防DoS？','如何准备测试数据？'],'回答先画状态和风险，再列用例，避免无序枚举。','中等',['百度测开','岗位冲刺','Login Testing'],'必背'),
  X('backend','软件测试','如何测试搜索框和结果质量？','同时测试输入处理、召回排序、交互状态、故障恢复、安全、性能和移动端体验，结果相关性需要查询集与标注而非只检查有返回。',['输入覆盖空/超长/特殊字符/多语言/错别字/语音、联想词与历史；结果覆盖零结果、分页、过滤、时效和去重。','质量用真实Query分层，测Recall/nDCG/点击或人工相关性；功能检查权限、敏感词和不同用户个性化。','测试XSS/注入/资源消耗，网络失败、快速连续输入、防抖、取消旧请求、软键盘和无障碍。'],['搜索结果如何断言？','联想词异步竞态怎么测？','排序模型升级如何回归？'],'百度移动生态高频场景，可连接RAG检索测试但不要混为同一系统。','困难',['百度测开','岗位冲刺','Search Testing'],'高压'),
  X('backend','软件测试','单元、集成、系统和验收测试分别验证什么？','单元验证最小代码逻辑，集成验证组件契约与真实依赖，系统验证完整产品需求和非功能属性，验收由业务视角确认可交付。',['测试金字塔用大量快而稳定的单测、适量集成和少量关键E2E降低成本；具体比例依系统而定。','LLM应用单测可测Parser/Policy，集成测真实模型或受控Stub契约，系统测Agent任务，验收测业务成功。','Mock测试不能替代真实依赖兼容与线上Shadow，尤其是非确定模型和第三方Tool。'],['端到端测试为什么不能太多？','契约测试放在哪层？','安全测试属于哪层？'],'回答重点是测试边界和失败定位能力。','简单',['百度测开','岗位冲刺','Test Pyramid'],'必背'),
  X('backend','软件测试','回归测试范围怎样根据改动选择？','结合代码Diff、依赖图、数据/配置变化、历史缺陷、核心链路和风险等级做影响分析，再选择自动化、专项与探索性回归。',['直接修改模块、调用者/被调用者、共享Schema、缓存、权限和部署配置都进入影响面。','高频核心链路与历史逃逸缺陷保持常驻集；低风险长尾可按抽样、分层和灰度验证。','模型/Prompt/Embedding/索引升级也算变更，需绑定版本并跑质量、安全、延迟和成本回归。'],['如何证明没有漏选范围？','全量回归什么时候必要？','用例优先级怎样定？'],'可联系 Runner Adapter 或 AV 协议变更后的轨迹回归。','困难',['百度测开','岗位冲刺','Regression'],'必背'),
  X('backend','软件测试','测试左移和右移分别怎样落地？','左移在需求、设计、编码和CI阶段提前定义质量与自动检查；右移通过灰度、监控、真实流量、故障注入和用户反馈持续验证。',['左移包括可测试验收标准、威胁建模、静态分析、单元/契约测试、PR Gate和测试数据设计。','右移包括Canary、SLO、Trace、异常检测、Shadow、回滚演练和线上失败样本回流。','右移不是把测试推到生产，敏感副作用仍需隔离；两侧通过版本和同一指标体系闭环。'],['故障注入属于左移还是右移？','线上测试怎样保护用户？','Shift-left会不会拖慢开发？'],'Agent质量需要离线Eval CI和线上Trace/监控共同完成。','中等',['百度测开','岗位冲刺','Shift Left','Shift Right'],'必背'),
  X('backend','软件测试','缺陷严重程度与修复优先级有什么区别？','严重程度描述技术和业务影响，优先级描述何时修复；后者还受用户范围、版本窗口、替代方案、复现率和成本影响。',['高严重度但只在停用实验功能中可能优先级较低；低严重度但影响大促核心入口可能立即修。','建立定义和例子降低团队争议，安全问题还要区分可利用性、权限和数据范围。','Agent缺陷需记录错误副作用、可恢复性、发生概率和检测能力，而不只看回答文本。'],['谁决定优先级？','偶现崩溃如何定级？','安全严重度能直接用CVSS吗？'],'用“影响×概率×暴露×可恢复”说明质量风险。','简单',['百度测开','岗位冲刺','Severity','Priority'],'必背'),
  X('backend','软件测试','如何判断测试是否充分？','综合需求和风险覆盖、代码/状态/数据覆盖、缺陷趋势、核心场景、故障注入、历史回归与剩余风险，不能用单一覆盖率宣告充分。',['建立需求/风险→用例追踪矩阵，检查高风险路径、边界、非法迁移和非功能属性。','观察新缺陷发现率、重复缺陷、逃逸率、用例稳定性及变更影响；覆盖增长但缺陷不再增加只是信号。','最终给有条件发布建议和未覆盖清单，测试无法证明系统绝对无缺陷。'],['100%行覆盖够吗？','探索性测试怎样度量？','Agent无完整Oracle怎么办？'],'AV中的portfolio_converged同样不表示仓库安全，可作为边界意识类比。','困难',['百度测开','岗位冲刺','Test Sufficiency'],'高压'),
  X('backend','软件测试','行、分支、条件、路径和MC/DC覆盖有什么区别？','行覆盖执行语句，分支覆盖每个判定结果，条件覆盖每个原子条件真假，路径覆盖组合路径，MC/DC要求每个条件能独立改变判定结果。',['分支覆盖不一定满足条件覆盖，条件覆盖也不保证所有分支组合；路径数量遇循环会爆炸。','MC/DC常用于高完整性系统，在控制用例数量下证明条件独立影响决策。','覆盖率反映执行范围而非断言质量；无断言或错误Oracle的测试仍可高覆盖。'],['分支覆盖与判定覆盖一样吗？','短路逻辑怎样影响覆盖？','变异测试解决什么？'],'Agent Policy和状态路由可用分支/MC-DC思路设计确定性测试。','困难',['百度测开','岗位冲刺','Coverage','MC/DC'],'深挖'),

  // ── Pytest、接口与自动化 ─────────────────────────────────────────
  X('backend','Pytest','Pytest fixture 解决什么，scope、yield 和 conftest.py 怎样使用？','Fixture用依赖注入复用测试前置和清理；scope控制实例生命周期，yield前准备、后清理，conftest.py在目录作用域共享Fixture与Hook。',['scope包括function/class/module/package/session；资源越共享越快，但状态污染和并发冲突风险越高。','yield后的清理即使测试失败也应执行；多Fixture按依赖拓扑创建并逆序销毁。','数据库、临时Workspace和Mock Server使用唯一测试ID隔离，不依赖用例执行顺序。'],['autouse何时使用？','fixture参数化怎么做？','session scope连接断了怎么办？'],'可为每个Coding Agent测试创建隔离Workspace与临时Runner配置。','中等',['百度测开','岗位冲刺','pytest fixture'],'必背'),
  X('backend','Pytest','Pytest 参数化怎样支持数据驱动和边界用例？','使用`pytest.mark.parametrize`把输入、期望和case id分离，结合Fixture间接参数化和标记组织不同环境/风险切片。',['case id应可读并包含场景，失败报告直接定位；大数据集从版本化文件加载但仍校验Schema。','不要在一个参数化用例里堆多个逻辑分支；共享断言可封装，场景语义仍清晰。','非确定Agent需要每个样本多次运行和聚合统计，不能把采样次数简单当普通参数后逐个断言。'],['多参数如何做笛卡尔积？','如何只跑失败样本？','敏感测试数据怎么管理？'],'适用于Prompt/模型/Runner矩阵与攻击集回归。','中等',['百度测开','岗位冲刺','pytest parametrize'],'必背'),
  X('backend','Pytest','Mock 的价值和过度 Mock 的风险是什么？','Mock隔离昂贵或不稳定依赖、构造难触发错误并验证交互；过度Mock会复制实现细节，让测试在真实契约已变化时仍通过。',['Mock最适合网络、时间、随机、支付/邮件副作用和故障注入；纯逻辑优先直接测试。','断言重要输入输出和协议，不把每个内部调用顺序锁死；对第三方API增加契约/沙箱集成测试。','LLM Mock可稳定覆盖Parser与重试，但不能评估真实模型质量、Token、延迟和非确定行为。'],['Stub、Fake、Mock区别？','何时使用录制回放？','怎样Mock异步函数？'],'Harness Adapter需要Fake Runner单测，也需要真实Runner smoke。','中等',['百度测开','岗位冲刺','Mock'],'必背'),
  X('backend','自动化测试','如何测试依赖外部模型API的函数？','分层测试请求构造和解析、错误恢复、真实契约及质量；Mock覆盖正常/超时/429/5xx/截断/非法JSON，沙箱调用验证真实Provider差异。',['冻结模型/Prompt参数并用request id、idempotency key；验证Retry-After、指数退避、取消和总体deadline。','流式测试UTF-8分片、半条JSON、Tool Call增量、连接中断和用户取消；超时后检查副作用状态。','质量测试多次采样并看通过率分布，单元层不能断言自然语言逐字相等。'],['429和500都重试吗？','怎样测试流式断线？','Fallback模型输出Schema不同怎么办？'],'直接映射Model Gateway和Runner外部依赖测试。','困难',['百度测开','岗位冲刺','LLM API Test'],'高压'),
  X('backend','自动化测试','接口自动化框架应怎样分层？','用例层描述场景，Client封装协议，数据/环境层提供版本化输入，断言层验证业务不变量，横向提供日志、报告、Mock、重试和CI。',['Client只处理认证、序列化、超时和响应Envelope，不把业务断言埋进HTTP工具。','测试数据通过Builder/Fixture生成并隔离，Secrets来自环境/Secret Manager；报告关联请求、版本、Trace和清理结果。','并行执行需要唯一资源命名、配额和幂等清理；失败重跑只针对确认的环境抖动，不能掩盖产品缺陷。'],['怎样支持多环境？','用例依赖如何处理？','接口变更怎样做契约测试？'],'可以把完整Coding Agent Runner抽象成一种被测外部服务。','困难',['百度测开','岗位冲刺','API Automation'],'必背'),
  X('backend','自动化测试','UI 自动化为什么不稳定，怎样治理？','DOM/渲染异步、定位器脆弱、网络抖动、共享数据和环境差异会导致Flaky；治理靠稳定语义定位、显式条件等待、数据隔离和可观察失败。',['优先role/test-id等稳定定位，Page Object封装页面语义；避免CSS层级和固定sleep。','等待业务条件而非时间，测试独立创建/清理数据，固定时区/语言/动画并保存截图、DOM、网络和console。','统计Flaky率并隔离修复；重试只用于诊断和短期止血，不能把重试后成功直接算通过。'],['如何识别测试问题还是产品问题？','Page Object会不会过度封装？','移动WebView怎么测？'],'Agent生成UI用例也必须遵守这些确定性工程边界。','中等',['百度测开','岗位冲刺','UI Automation','Flaky'],'必背'),
  X('backend','自动化测试','自动化脚本自愈为什么可能掩盖缺陷，怎样限制？','自愈只能修复定位器等非语义变化，不能修改业务断言或绕过缺失控件；每次候选修复必须留差异、置信、证据和审批。',['用DOM属性、可访问树、历史定位和视觉相似产生候选，但先验证元素角色、业务文本、交互和页面状态。','高置信可Shadow执行并标记“healed”，低置信阻断；核心/安全链路要求人工Review后更新基线。','监控自愈率、误愈率和页面变更，原定位失败仍作为质量信号，不能静默吞掉。'],['元素移动算语义变化吗？','如何构建自愈评测集？','LLM能否直接改测试？'],'这是AI测试平台非常容易被高压追问的边界题。','困难',['百度测开','岗位冲刺','Test Self-Healing'],'高压'),

  // ── 大模型与 Agent 评测 ─────────────────────────────────────────
  X('agent','评测','大模型输出非确定时如何建立稳定测试？','冻结可控版本与参数，多次采样统计分布，用确定性规则、任务Oracle、校准Judge和人工抽检组合，并保存每次原始响应与Trace。',['对格式/权限/引用用确定性断言；对语义质量用rubric和成对比较；不同风险场景设置通过率与置信区间。','固定seed不等于跨后端完全复现，Provider可能静默更新；记录model snapshot、Prompt、Tool、数据和环境版本。','区分单样本偶然失败和场景显著回退，报告均值、方差、分位数及失败切片。'],['采样几次足够？','Temperature=0是否确定？','测试失败能否自动阻断发布？'],'百度大模型专项评测的核心起点。','困难',['百度测开','岗位冲刺','Non-deterministic Eval'],'高压'),
  X('agent','评测','大模型评测指标应怎样按任务分层？','分类看准确率/PR/F1，生成看正确、相关、完整和忠实，推理看最终正确与可验证步骤，对话看一致性，安全看攻击成功/误杀，系统看延迟吞吐成本稳定性。',['不要用一个总分掩盖关键切片；先定义业务失败成本和blocking metrics。','开放生成同时评内容与行为：引用、拒答、工具副作用、格式和用户任务完成。','线上指标如采纳/人工接管与离线Rubric结合，防止只优化Judge偏好。'],['BLEU适合开放问答吗？','成功率和用户满意度冲突怎么办？','安全拒答越多越好吗？'],'可将安全Finding正确性与Agent过程指标分开。','中等',['百度测开','岗位冲刺','LLM Metrics'],'必背'),
  X('agent','评测','如何建设可持续的大模型 Benchmark？','从能力/风险和真实业务分布定义场景，建立有来源、分层、去重、防污染的数据与Rubric，校准标注一致性并对版本持续维护。',['数据包含正常、边界、无答案、对抗、长尾和历史线上失败，保存license、source、time、tenant和难度。','Gold不是一条漂亮答案：结构化任务保存Oracle/关键点/允许变体；主观任务多人标注并测一致性。','Dataset、Evaluator、Prompt、Judge和模型全部版本化；发布后持续采样新失败但设置冻结测试窗防追着测试集调参。'],['合成数据占比多少？','如何处理答案过时？','Benchmark变难后历史分数怎么比？'],'可复用为Agent测试平台的数据层设计。','困难',['百度测开','岗位冲刺','Benchmark'],'高压'),
  X('agent','评测','如何评估模型幻觉而不是只让另一个模型打分？','先定义与来源冲突、无来源事实、虚构引用和工具结果误读，再使用可验证知识源、引用对齐和任务Oracle，Judge只作辅助。',['把回答拆成可验证Claim，检索/人工核对每项是否被给定来源支持，区分错误、无支持和不可判定。','无答案集检查是否拒答；时间敏感事实绑定as-of和版本；引用必须同时验证存在、蕴含与定位。','Judge在人工样本上校准并隐藏风格/长度，关键错误用规则或专家确认。'],['事实正确但无来源算幻觉吗？','如何评估长答案？','工具返回本身错误怎么办？'],'AV Evidence-bounded adjudication可作为安全任务中的更严格实例。','困难',['百度测开','岗位冲刺','Hallucination Eval'],'必背'),
  X('agent','评测','如何测试多轮对话的一致性和隔离？','覆盖指代、用户偏好、持续约束、事实更正、话题切换、重置、压缩恢复和跨用户隔离，并同时检查不应记住的内容。',['构造多轮状态机和关键事实表，在不同轮询问同一约束的直接/间接表达；更正后旧事实应失效但保留来源。','长对话触发摘要/窗口轮换，验证关键目标与权限不丢、无关历史不干扰。','并发多个tenant/thread交错执行，检查Session、Cache、向量过滤和日志均不串话。'],['用户自相矛盾怎么办？','摘要造成错误算模型还是系统？','如何做跨设备恢复？'],'直接覆盖Memory与Session工程。','困难',['百度测开','岗位冲刺','Multi-turn Eval'],'深挖'),
  X('agent','LLMOps','模型升级后怎样做配对回归和发布决策？','在相同请求、上下文和工具环境下运行新旧模型，比较质量、安全、延迟、成本和失败切片，用统计显著性与业务Gate决定灰度。',['固定黄金集、历史线上失败、安全攻击和无答案集；多次采样，按query/语言/长度/工具类型分层。','新旧输出使用确定性Oracle、盲人工或顺序随机Judge；关注win/tie/loss及严重回退，而非平均分。','先Shadow再Canary，记录路由版本并可回滚；Provider静默更新通过定期Canary与行为指纹发现。'],['同一预算怎样比较？','新模型更慢但更准怎么办？','Prompt需要同步修改吗？'],'也适用于Runner或Reviewer模型升级。','困难',['百度测开','岗位冲刺','Model Regression'],'高压'),
  X('agent','评测','如何降低 Benchmark 污染和过拟合？','使用私有保留集、时间切分、近重复检测、Canary和持续新样本；开发集与最终测试隔离，避免针对固定Judge和答案反复调参。',['对训练/公开语料做文本与语义去重，代码题使用新仓库/新commit和隐藏测试。','生成等价变体时验证难度和语义未变；只靠改写不能抵抗模型记忆原题。','限制完整答案访问，记录每次评测和调参；周期轮换保留集并保持锚点集用于纵向比较。'],['如何发现模型见过测试集？','私有集是否绝对安全？','动态集怎样保证可比？'],'百度评测平台的数据治理必答。','困难',['百度测开','岗位冲刺','Benchmark Contamination'],'深挖'),
  X('agent','评测','测试 Agent 与测试普通 LLM 有什么本质差异？','LLM测试主要看一次输出；Agent还要验证规划、工具选择/参数、状态、记忆、权限、副作用、失败恢复、终止和环境最终状态。',['同一最终答案可能由越权或偶然路径得到，因此必须采集Trajectory和真实环境Oracle。','测试对象包含模型、Prompt、Graph、Tool、Policy、Memory、Sandbox和外部依赖版本，需分层归因。','故障注入与对抗输入检查重试、补偿、人工确认和审计，而非只判文本相似。'],['Agent成功是否必须路径最优？','轨迹评分会限制探索吗？','Browser Agent如何定义Oracle？'],'这是百度Agent自主编排测试的核心定位题。','中等',['百度测开','岗位冲刺','Agent Eval'],'必背'),
  X('agent','评测','如何定义一个 Agent 任务是否成功？','最终目标与环境状态正确、没有越权副作用、关键约束满足且结果可验证；过程成本和路径合理性作为独立维度，不把漂亮文本当成功。',['为任务定义precondition、postcondition、不变量和禁止动作；尽量由测试环境/API读取真实状态。','允许多条合法路径，但工具调用必须有权限、幂等和必要确认；失败可有“正确拒绝/有界停止”。','报告success、unsafe success、partial、blocked、environment failure等，避免二元标签丢失原因。'],['测试超时算失败吗？','用户取消怎样计？','成本超预算但结果正确呢？'],'可映射AV中的科学处置与外部运行状态分离。','困难',['百度测开','岗位冲刺','Task Success','Oracle'],'高压'),
  X('agent','评测','如何系统评估 Agent 的工具调用质量？','分别统计工具选择、参数合法/正确、时机、重复、结果理解、失败恢复、权限与副作用，并用调用前后环境状态验证。',['建立Tool-specific Oracle和schema/fuzz用例；对相同意图测试无权主体、越界参数和危险组合。','Trajectory计算无效调用率、重复率、恢复成功和平均步骤，但不以“调用越少越好”压制必要探索。','Tool输出投毒、超时、部分成功和迟到结果进入故障集，检查Agent是否误读或重复执行。'],['模型选错工具算谁的缺陷？','如何测试并行调用？','Tool描述变化怎样回归？'],'适合结合MCP和完整Coding Agent工具链。','困难',['百度测开','岗位冲刺','Tool Eval'],'高压'),
  X('agent','评测','怎样用故障注入测试 Agent 的恢复能力？','在模型、网络、Tool、Session、Workspace、存储和返回数据层注入可控失败，验证错误分类、幂等重试、Checkpoint恢复、降级、补偿和审计。',['故障场景含超时/429/5xx、进程退出、非法/截断结果、磁盘满、只读Workspace、断网和已产生部分副作用。','每次实验固定注入点/持续时间/概率和seed，验证最终状态、重复副作用、恢复时间与人工接管。','Chaos平台先在沙箱/Shadow运行并限制blast radius，故障本身也有审批和kill switch。'],['怎样注入模型幻觉？','恢复成功如何定义？','故障组合会不会爆炸？'],'直接联系Harness的Agent/Runner/Environment Failure分类。','困难',['百度测开','岗位冲刺','Fault Injection'],'高压'),
  X('agent','评测','Fresh 与 Resume 应怎样设计公平对照？','使用同一任务、显式输入、模型、工具、外部资源边界和多随机种子，只改变是否继承Session，分别观察连续性、偏差延续、成功、成本和恢复。',['Resume可复用导航/构建经验但也带错误假设；Fresh只读统一结构化Package以保证输入可比较。','外部状态和Cache需重置或记录，否则Fresh仍可能间接继承；评测者盲于条件减少主观偏差。','按稳定任务与会演化任务分层，报告何时哪种策略更好，不能预设Fresh必胜。'],['怎样控制上下文Token相同？','Fresh是否等于独立模型？','Session丢失怎样算？'],'对应AV会话拓扑和Fresh Review消融。','困难',['百度测开','岗位冲刺','Fresh vs Resume'],'高压'),
  X('agent','LLMOps','Agent 线上质量监控应该有哪些指标和维度？','同时监控任务成功、人工接管、工具/模型失败、重试/循环、步骤、延迟、Token成本、越权阻断和用户反馈，并按版本、场景和租户切片。',['Trace关联model/prompt/graph/tool/index/policy版本，能从异常指标下钻到具体轨迹和Artifact。','设置SLO与告警：成功率、p95/p99、Loop率、unsafe action、fallback率、queue和错误预算。','抽样人工复核和失败聚类发现无标签问题，线上样本脱敏后进入回归集并防训练/测试污染。'],['成功率怎么在线获得？','高拒答率是安全还是退化？','告警风暴怎样治理？'],'可把Harness Action Lineage转化为通用Agent质量Trace。','困难',['百度测开','岗位冲刺','Online Quality'],'必背'),

  // ── 性能、移动端与平台系统设计 ──────────────────────────────────
  X('backend','性能测试','QPS、TPS、并发数和响应时间有什么区别？','QPS是单位时间请求数，TPS是单位时间完成业务事务数，并发是同时在系统内的请求/用户，响应时间是单请求从发出到完成的时长，四者通过服务时间和排队关联。',['一个Transaction可能含多个Request，所以TPS不等于QPS；并发用户也不等于同时请求数。','稳定系统近似Little定律 `L=λW`，吞吐到容量后增加并发主要增加排队和尾延迟。','明确统计窗口、成功口径和客户端/服务端观测点，同时报告错误率。'],['吞吐越高越好吗？','并发100如何产生？','SSE请求QPS怎样统计？'],'性能题先统一定义再谈工具。','简单',['百度测开','岗位冲刺','QPS','TPS'],'必背'),
  X('backend','性能测试','如何压测一个大模型接口？','构造符合线上输入/输出Token与到达分布的负载，分开测Prefill/Decode、TTFT、TPOT、端到端延迟、吞吐、排队、错误和单位成本。',['包含短/长Prompt、不同输出、流式/非流式、工具调用和多租户；区分open-loop到达率与closed-loop并发。','逐级升压找到饱和点，观察GPU/MLU利用率、显存、batch、KV Cache、队列、网络和429/5xx。','预热、固定模型版本并校验响应质量，客户端不能成为瓶颈；报告p50/p95/p99及稳定持续压测。'],['TTFT高看哪里？','流式降低总耗时吗？','怎样测最大稳定吞吐？'],'国产算力岗位还需按Shape/Batch Profile切片。','困难',['百度测开','岗位冲刺','LLM Load Test'],'高压'),
  X('backend','性能测试','怎样定位瓶颈在模型、网络还是业务服务？','用分段Trace拆DNS/连接/TLS/网关排队、检索/工具、模型queue/prefill/decode和响应传输，再结合资源指标与对照实验定位。',['同机/内网绕过网络、Mock模型、固定缓存、直接调用后端等对照隔离层次。','TTFT包含业务准备、排队和Prefill，TPOT更接近Decode；CPU/GPU、连接池、DB慢查询和下游RPC一起观察。','相关性不是因果，改动一个变量并复测；负载下才出现的锁/队列瓶颈需持续压测。'],['客户端时间和服务端时间不一致怎么办？','网络RTT怎样测？','缓存命中会掩盖什么？'],'可复用到RAG全链路性能诊断。','困难',['百度测开','岗位冲刺','Performance Diagnosis'],'高压'),
  X('backend','移动测试','弱网与移动端应覆盖哪些质量维度？','网络注入延迟、丢包、抖动、断网和切换，移动端覆盖系统/机型/分辨率/权限/前后台/电量/内存/安装升级/冷暖启动，并验证恢复与幂等。',['流式LLM响应测试中途断线、后台切换、重复提交和续传/重开；不能因重试重复产生副作用。','设备矩阵按用户占比和风险分层，真机覆盖关键兼容，模拟器用于大规模回归。','收集Crash/ANR、资源、电量、网络和业务Trace；权限拒绝、低存储和系统回收进程是重要场景。'],['弱网工具怎样选？','网络恢复后自动重试吗？','如何降低机型矩阵成本？'],'百度移动生态质量岗位需重点补齐。','中等',['百度测开','岗位冲刺','Weak Network','Mobile'],'必背'),
  X('backend','系统设计','设计一个企业 Agent 自动化测试平台。','平台围绕版本化任务与数据集，调度隔离环境执行不同Agent/模型，采集完整轨迹，由规则/Judge/环境Oracle评分，聚合指标、失败聚类并进入回归。',['控制面含Project/Dataset/Case/Run/Variant/Schedule，数据面用队列+Worker+Sandbox；幂等run key、租约和Checkpoint支持并发恢复。','Trace保存模型、Prompt、Graph、Tool、Policy、数据、环境版本和Artifact；原始大文件进对象存储，指标进分析库。','Evaluator分确定规则、业务Oracle、Judge和人工；权限按租户/数据集，成本配额、灰度、报告与CI Gate完整闭环。'],['怎样回放一次Run？','如何避免重复执行？','Judge升级后历史结果怎么办？'],'百度岗位最高优先级系统设计题。','困难',['百度测开','岗位冲刺','Agent Test Platform'],'高压'),
  X('backend','系统设计','设计一个大模型评测数据平台。','以不可变Dataset Version为核心管理样本、来源、权限、标签、Rubric和Split，支持去重/污染检测、标注一致性、评测任务、指标和完整lineage。',['样本含content hash、source/license、时间、场景、敏感等级与tenant；版本通过manifest引用，删除用tombstone和合规流程。','标注任务支持多人、盲审、冲突仲裁和一致性统计；Gold/Rubric版本不随意覆盖。','Evaluation Run绑定dataset/model/prompt/judge/code版本，结果可重算、对比和导出；敏感数据计算尽量靠近数据并做最小权限。'],['数据集如何增量更新又保持可比？','重复样本如何发现？','标注员能看到模型身份吗？'],'覆盖百度JD中的测试数据生成与质量指标。','困难',['百度测开','岗位冲刺','Eval Data Platform'],'高压'),
  X('backend','系统设计','设计一个面向Agent的自动故障注入系统。','通过代理、Fake依赖、容器/网络控制和状态Hook在模型、Tool、Session、存储与环境注入版本化故障，编排实验并用稳态假设和恢复Oracle判定。',['Fault定义target、type、trigger、duration/probability、scope和cleanup；支持超时、错误码、脏数据、进程Crash、磁盘/权限和网络故障。','Experiment先验证steady state，注入期间采集Trace/资源/副作用，具备blast radius、审批、kill switch和自动回滚。','结果统计恢复率、MTTR、重复副作用、数据一致性和人工接管；组合故障用风险/PW抽样避免爆炸。'],['如何注入只发生一次的部分成功？','生产能否故障注入？','故障平台本身挂了怎么办？'],'可直接承接Harness异常恢复能力。','困难',['百度测开','岗位冲刺','Chaos Engineering'],'高压'),

  // ── 阿里星：隐私、安全平台与研究高压 ───────────────────────────
  X('security','身份认证','Authentication、Authorization、Accounting 分别解决什么？','认证确认主体是谁，授权判断该主体能对哪个资源做什么，审计记录谁在何时基于什么委托执行了什么及结果。',['登录成功不代表可访问任意对象；对象级、功能级和字段级授权都应在服务端执行。','Agent调用工具时同时记录用户、Agent/Service、委托链、策略决策和实际副作用。','审计日志需完整、防篡改、最小敏感暴露和可关联，但不能替代实时阻断。'],['认证Token里有role就够吗？','Accounting与日志区别？','代理执行时谁是主体？'],'阿里Agent安全与多租户权限基础。','简单',['阿里星','岗位冲刺','AAA'],'必背'),
  X('security','隐私','差分隐私的基本定义与隐私预算是什么？','相邻数据集只差一个个体时，算法输出分布应足够接近；ε控制可区分程度，δ允许极小失败概率，组合查询会消耗累计隐私预算。',['ε越小通常隐私更强但噪声/效用损失更大；不能脱离机制、敏感度、δ和数据规模只比较ε。','先裁剪单个用户贡献，再按敏感度加入Laplace/Gaussian噪声；多次发布使用composition/accountant。','DP提供统计层保证，不替代访问控制、加密、数据最小化和删除。'],['中心DP与本地DP区别？','隐私预算用完怎么办？','训练LLM怎样做DP-SGD？'],'掌握基础定义即可，避免把脱敏等同差分隐私。','困难',['阿里星','岗位冲刺','Differential Privacy'],'深挖'),
  X('security','隐私','联邦学习为什么不会自动保护隐私？','原始数据不集中只能减少直接共享，梯度/更新仍可能泄露成员或样本特征，恶意参与方还能投毒和观察模型差异。',['安全聚合让Server只见聚合更新，DP限制单个用户影响，TLS/身份/TEE保护传输与执行，但各自有假设。','防投毒需鲁棒聚合、更新裁剪、异常检测和参与方信誉；非IID数据还会影响收敛与公平。','记录威胁模型：不诚实Server、恶意Client、串谋和掉线条件不同，不能笼统称“数据不出域所以安全”。'],['Secure Aggregation解决什么？','横向和纵向联邦区别？','模型发布后还有什么风险？'],'阿里数据与隐私安全可能深挖。','困难',['阿里星','岗位冲刺','Federated Learning'],'深挖'),
  X('security','隐私','成员推断、模型反演和梯度反演分别是什么？','成员推断判断样本是否在训练集，模型反演恢复敏感属性/代表性输入，梯度反演从共享梯度重建训练样本；攻击面和防御不同。',['过拟合、置信输出和重复查询可增强成员推断；限制输出、正则与DP可降低风险。','梯度反演在小batch、早期层或已知标签下更强，联邦场景需安全聚合、batch/裁剪和DP。','评估必须定义攻击者黑盒/白盒能力和基线，生成相似图像不一定证明精确个人泄露。'],['模型窃取与反演区别？','只返回Top1能否安全？','DP能彻底防御吗？'],'至少能区分概念与威胁模型。','困难',['阿里星','岗位冲刺','Privacy Attack'],'深挖'),
  X('security','Agent威胁建模','如何为企业Agent做全生命周期威胁建模？','从资产、主体、信任边界和数据流出发，覆盖输入、模型、RAG/Memory、Tool、身份委托、多Agent、Sandbox、监控和更新供应链，再映射控制与残余风险。',['画DFD并标用户、Host、Model Gateway、向量库、MCP/A2A、Tool Gateway和外部系统；每条跨界流说明身份和敏感度。','枚举注入、越权、数据泄漏、记忆投毒、工具/供应链、DoS和错误自动处置，按影响×可达×控制排序。','设计阶段建模，测试阶段转为攻击用例，运行阶段由Trace/告警/事件响应验证；模型升级和新Tool重新评审。'],['STRIDE能直接套Agent吗？','谁拥有风险？','如何验证控制有效？'],'结合OWASP Agentic风险和NIST生命周期思路，但最终以实际系统数据流为准。','困难',['阿里星','岗位冲刺','Agent Threat Model'],'高压'),
  X('security','安全评测','企业Agent安全评测指标怎样设计？','同时衡量攻击成功、越权/泄漏、副作用、防御误杀、人工接管、检测/恢复、审计完整和成本，并按攻击、身份、Tool和版本切片。',['ASR必须定义尝试次数和成功Oracle；阻断率不能掩盖正常任务可用性下降。','高风险动作测执行前拦截、Dry-run/审批、撤销和真实环境状态；多次采样给置信区间。','上线监控权限拒绝、异常Tool序列、数据外发和策略版本，失败样本进入私有自适应攻击回归。'],['拒答率高是否更安全？','怎样评估未知攻击？','Judge能判定越权吗？'],'安全平台要同时报告security与utility。','困难',['阿里星','岗位冲刺','Security Metrics'],'高压'),
  X('security','系统设计','设计一个企业级Agent安全防护平台。','以Agent Registry/Identity和Policy Engine为控制核心，经Tool Gateway强制权限与参数策略，结合Prompt/RAG/Memory安全、Sandbox、数据访问、Runtime Monitor、审计、红队评测和事件响应。',['注册表保存Agent/版本/owner/capability；身份使用用户on-behalf-of和短期scope token，策略在实际Tool/Data执行点强制而非只让模型拒绝。','Tool Gateway执行Schema、ABAC、审批、限流、凭证注入和结果过滤；Sandbox隔离代码，RAG/Memory按tenant和来源治理。','Trace流入检测与审计，离线攻击集/CI验证策略，事件响应支持kill switch、凭证回收、Session隔离、回滚和取证。'],['怎样降低Gateway延迟？','跨Agent委托如何传权限？','Policy服务挂了fail-open吗？'],'阿里最高优先级系统设计题。','困难',['阿里星','岗位冲刺','Agent Security Platform'],'高压'),
  X('security','系统设计','设计一个Agent Tool Gateway。','统一工具注册、Schema、身份、对象与参数级授权、短期凭证、审批、限流、执行隔离、结果过滤和审计，让模型只有Proposal权。',['调用请求包含user/agent/delegation/task/tool/version/args/idempotency，Gateway规范化参数后由Policy决策。','高风险工具支持dry-run/preview、绑定参数审批和双人复核；凭证在执行侧注入，不进Prompt或模型日志。','结果Envelope标来源、敏感度、截断和错误类型，防Tool Output Injection；Trace关联真实副作用与补偿。'],['MCP Server与Gateway关系？','Shell工具怎么做参数策略？','Gateway如何高可用？'],'可联系Harness Runner权限，但完整Shell Agent还需OS/容器强制。','困难',['阿里星','岗位冲刺','Tool Gateway'],'高压'),
  X('security','系统设计','设计一个Agent安全评测平台。','用版本化场景/攻击库驱动隔离Agent Sandbox多次运行，采集完整Trajectory，由确定性Oracle、Judge和人工评分攻击成功与正常任务可用性，并持续回归。',['Scenario定义主体、权限、资产、初态、攻击输入、允许/禁止动作和成功Oracle；Attack Generator产生多轮/间接/编码/工具链变体。','Runner矩阵覆盖模型/Prompt/Tool/Policy版本，控制seed与预算；Sandbox记录网络、文件、进程和副作用。','指标含ASR、越权/泄漏、误杀、成本和恢复；失败聚类后生成最小重现并进入CI/红队循环。'],['如何防攻击集污染？','真实外部Tool怎么隔离？','自适应攻击怎样自动化？'],'可与百度通用Agent测试平台对比：这里威胁模型和安全Oracle是中心。','困难',['阿里星','岗位冲刺','Security Eval Platform'],'高压'),
  X('security','系统设计','设计安全Agent的自动响应系统。','按动作可逆性、影响范围、置信和权限分级：低风险补充上下文/隔离建议自动，高风险封禁、删除或变更权限先Dry-run、审批并具备回滚。',['告警进入补充资产/历史→假设→受限查询/检测→风险评分；攻击者可控制的日志永远是数据。','Policy规定自动、单人、双人和禁止动作，执行使用幂等键、fencing和短期凭证；验证postcondition后才关闭事件。','失败或低置信转人工，所有模型、证据、工具和审批进入审计；用Shadow/桌面演练逐步扩大自治。'],['隔离主机可逆吗？','误封怎样快速恢复？','置信度由谁给？'],'Agentic SOC必须先控制自动处置风险。','困难',['阿里星','岗位冲刺','Automated Response'],'高压'),
  X('security','Harness安全','如何系统保护Workflow-Harness自身？','将恶意仓库、Runner、Adapter、Session、Workspace、Artifact和Canonical State分别建模，用最小权限Sandbox、来源/版本校验、原子提交和审计防止不可信执行污染控制面。',['每个Run独立非root环境，限制文件、网络、PID/CPU/内存、Docker Socket、云元数据和Secret；依赖下载经代理/allowlist。','Runner输出只是Proposal，Adapter严格解析长度/Schema/退出状态；Artifact内容寻址并绑定run/workspace/commit，Session不拥有真值。','Canonical更新校验exact identity/version/CAS/idempotency，拒绝迟到/重复结果；控制面与执行面凭证分离并支持kill/revoke/取证。'],['恶意AGENTS.md怎么办？','Adapter命令注入如何防？','Reviewer也被注入怎么办？'],'这是阿里岗位与个人项目结合的核心安全题。','困难',['阿里星','岗位冲刺','Workflow-Harness Security'],'高压'),

  // ── 阿里星研究与人才计划高压 ───────────────────────────────────
  X('adaptivevuls','研究方法','如何验证“调查状态—下一行动错配”不是主观构念？','在看最终结果前冻结可观察定义和标注协议，让多名标注者基于轨迹独立标状态、动作及是否存在高价值替代，并报告一致性与争议。',['给每类错配明确必要/排除条件和正反例，标注者只看当时可见信息，不用后验漏洞结果倒推。','抽样不同目标、模型和阶段，计算Cohen/Fleiss Kappa或分层一致性；低一致定义需要修订而非强行统计。','再检验错配标签是否预测无效成本、错误关闭/提升或覆盖损失，区分construct validity与方法效果。'],['谁来标注最可靠？','Outcome-blind怎样实现？','构念和指标有什么区别？'],'高压回答要承认当前证据边界，不把设计直觉写成已验证事实。','困难',['阿里星','岗位冲刺','Construct Validity'],'高压'),
  X('adaptivevuls','研究方法','为什么不能声称四类失败模式是完整分类？','它们是从有限运行轨迹归纳的代表性表现，不具备穷尽证明；需要更多目标、模型、标注和开放编码来验证饱和度与边界。',['保存无法归类样本和多标签情况，通过迭代codebook与新数据理论饱和检查完善分类。','不同失败可共享根因或因果相连，如环境失败引发过早停止；分类层级要明确。','论文表述为observed/representative taxonomy，并报告采样偏差和标注一致性。'],['如何发现新类别？','互斥分类是否必要？','失败表现与根因如何区分？'],'这比硬说“完整”更符合研究诚信。','困难',['阿里星','岗位冲刺','Failure Taxonomy'],'高压'),
  X('adaptivevuls','研究方法','AdaptiveVuls 是否过拟合漏洞调查，哪些部分能泛化？','Workflow-Harness的Runner/Session/Workspace/Artifact/恢复可通用；AV的目标认知、Evidence、Claim和安全处置是领域特化，泛化到其他研究任务必须单独映射与实验。',['可抽象的模式是开放探索、显式状态、证据改变行动与独立复核；不同领域的Evidence/Oracle/责任完全不同。','不能因结构像AutoResearch就声称有效；选择一个新领域定义对象、基线和真实Outcome后做迁移消融。','安全特化不是缺点，前提是论文贡献边界写清，不用“通用Agent框架”掩盖领域假设。'],['拿掉安全对象还剩什么？','哪个领域最适合验证泛化？','Harness贡献能单独发表吗？'],'用于区分方法、工程载体和应用。','困难',['阿里星','岗位冲刺','Generalization'],'高压'),
  X('adaptivevuls','研究方法','证据约束和显式控制可能降低Agent哪些能力？','可能限制自由探索与偶然发现，增加Review/状态开销，延迟其他方向，降低Token效率，并把错误Schema或Reviewer偏差固化进流程。',['过早要求结构化可能扼杀模糊但有价值方向；Sticky单链保连续性也可能传播路径依赖。','Fresh Review增加成本且可能丢隐式上下文；Portfolio选择可能反复打磨可报告Case造成覆盖损失。','实验同时测正确结果、覆盖、时间/Token、方向多样性和错误关闭，并允许低信号方向有界结束。'],['怎样减少流程税？','何时退化为Native Agent更好？','负面结果是否推翻方法？'],'最新av.md已明确AV不声称普遍优于广扫后验证。','困难',['阿里星','岗位冲刺','Trade-off'],'高压'),
  X('adaptivevuls','实验','如何证明Fresh Review收益不是单纯多花一次模型预算？','使用相同总模型/Token/墙钟资源比较Fresh、同Session Self-Review和把额外预算给Investigator等条件，多种子盲评正确结论与成本。',['控制模型、工具、输入Package和Reviewer输出权限；预算不足时按预注册规则分配，不能只给方法组更多调用。','指标看Claim膨胀、错误处置、决定性Artifact、正确Scope/Ownership和最终漏洞，不只看Reviewer说得更谨慎。','分析何种任务Fresh有收益或因丢上下文退化，并报告统计不确定性。'],['相同Token如何控制输出长度？','Fresh和模型多样性怎样分离？','Reviewer错误由谁判？'],'直接对应阿里研究高压追问。','困难',['阿里星','岗位冲刺','Fresh Review Ablation'],'高压'),
  X('adaptivevuls','实验','当前严格实验结果应该怎样诚实陈述？','分开陈述运行机制、开发性smoke、真实安全产出和方法因果证据；前两者证明可运行，21/11/CVE/CNVD证明外部价值信号，但相对基线普遍收益仍待正式前瞻实验。',['说明已有负面/混合实验促成V1.42收缩：OES字段和多Worker本身不再被视为科学收益。','V1.43真实OpenCode smoke只验证目标级Sticky Session拓扑与Fresh隔离，不计漏洞效果。','正式结论需Native、Batch-and-Confirm等公平基线，测正确根因、处置、错误关闭、覆盖和成本。'],['最失败的一次实验是什么？','哪些假设已被削弱？','论文当前能写什么？'],'以最新av.md为准，绝不再使用旧V1.36“已经验证H1-H4”的过时口径。','困难',['阿里星','岗位冲刺','Strict Result'],'高压'),
  X('adaptivevuls','研究方法','如果给六个月和一个团队，AdaptiveVuls 下一步怎样推进？','先冻结问题、协议和前瞻评测，建立公平基线与真实Outcome；并行补Agent安全威胁模型、Sandbox/权限、Runner覆盖和可复现实验，而不是继续堆状态字段。',['第1–2月整理目标/数据集、Outcome-blind标注、Native/Batch/Open方法基线和外部运行边界。','第3–4月多目标多种子运行与消融，重点验证目标认知、证据修订和Fresh的增量，同时完成攻击面/权限硬化。','第5–6月盲审结果、统计与失败分析，发布可复现Artifact/协议，选择最有证据的收缩版论文主张并接企业场景。'],['团队角色怎样分？','最大风险是什么？','先写论文还是先加功能？'],'回答应突出优先级和停止继续堆设计的纪律。','困难',['阿里星','岗位冲刺','Research Roadmap'],'高压'),
  X('agent','求职表达','为什么认为自己适合阿里星Agent安全方向？','核心匹配是安全与Coding Agent交叉：有完整Harness与领域方法、真实漏洞外部结果、失败分析和实验边界意识，同时不把尚未证明的方法包装成结论。',['方向稀缺性来自能同时讨论模型/工具/状态、传统漏洞、权限/Sandbox和研究设计。','准备一个最核心贡献：将开放调查组织为目标认知、持续取证、证据约束修订与Fresh裁决，而不是罗列十个模块。','坦诚不足：论文和严格对照仍在推进，MLU/大规模平台等经验按实际说明，并给六个月计划。'],['哪个贡献达到人才计划水平？','为什么没有顶会？','换强模型后还有价值吗？'],'最终口径要有自信但不夸大，阿里星会重点判断原创问题意识和上限。','困难',['阿里星','岗位冲刺','人才计划'],'高压')
);

QUESTIONS.push(
  X('adaptivevuls','V1.43当前口径','当前版本的 AdaptiveVuls 如何用一分钟准确介绍？','AdaptiveVuls 是面向开放式仓库的认知引导、证据约束的持续漏洞调查方法：目标认知与漏洞知识形成调查方向，目标级 Sticky Coding Agent持续定位、形成和验证假设，Fresh Review限定证据与后继，Runtime只做合法提交。',['它不重新赋予模型读代码或写PoC能力，也不把多Agent、字段或状态持久化本身当科学贡献；核心问题是证据能否改变漏洞问题、下一行动和正确结果。','V1.43让初始Survey、普通Case、Revision/Branch共享目标级Sticky Investigator工作链；Controller、Reviewer、Refresh Survey和Saturation Challenge保持Fresh，三个lane仍是权限/视角边界且顺序执行。','真实结果为9个系统、21个发现、11个厂商确认修复、1个CVE和3个CNVD；这些证明实际产出，不单独证明相对基线因果优势，严格结果以最新av.md和前瞻实验为准。'],['为什么目标级Sticky不会污染Case？','V1.42/43相对旧版收缩了什么？','当前已经证明与未证明的分别是什么？'],'百度侧强调过程评测与失败归因；阿里侧强调认知/证据控制、真实安全结果和研究边界。','困难',['百度测开','阿里星','V1.43'],'高压')
);

/* 2026-08 百度 AI 测开一面真实追问复盘：保留口语化回答主线，再给可继续深挖的工程细节。 */
QUESTIONS.push(
  X('adaptivevuls','百度一面复盘','不要堆术语，怎样用一分钟把主项目讲清楚？','按“任务与相关工作缺口→四项机制→真实结果→证据边界”展开；核心不是给Coding Agent补一个搜索循环，而是把长程调查状态外部化并让证据持续调整仓库级搜索。',['任务口径：传统静态分析/Fuzzing偏已知规则或稳定Oracle，很多LLM方法从给定代码单元、漏洞类型或候选出发；当类型、位置和候选路径均未知时，在线证据怎样持续改变多方向搜索研究相对不足。','方法口径：Multi-Runner & Thin Runtime管理Session、Workspace、Artifact、预算、权限和恢复，但保留Coding Agent原生搜索；Native Session + External State与Bootstrap/Delta Injection维持长程上下文；Evidence Savepoint改变Direction/Portfolio；Fresh Re-Survey与Fresh Reviewer分别负责搜索隔离和正式结论复核。','结果口径：9个系统、21个安全发现、11个获厂商确认修复、1个CVE和3个CNVD；说明真实产出，但不单独证明优于强原生Agent。'],['为什么Runtime叫Thin？','Bootstrap与Delta Injection分别是什么？','Fresh Re-Survey与Fresh Reviewer差在哪？'],'固定使用“相关工作→研究空缺→方法→结果→边界”主线；原生Agent可能出现的失败只作为出发点和评测对象，不作为唯一立项依据。','简单',['百度测开','最新简历','Thin Runtime','项目表达'],'必背'),
  X('harness','百度一面复盘','项目里遇到的一个真实问题，怎样按“发现—定位—修复—验证”回答？','选一个具体故障讲完整闭环：后续 Reviewer 没读到原始证据，只看到自然语言摘要，造成重复调查或过强结论；根因是状态交接不确定，而不只是 Prompt 不够好。',['发现：Trace显示前一阶段已经运行命令并生成文件，后续Agent却重复读同一代码，甚至引用了摘要中不存在的结论。','定位：Session隐式上下文无法保证跨Agent传递，自然语言摘要又丢失文件路径、命令输出、环境条件和失败信息。','修复与验证：每次执行输出结构化Result和Artifact引用，Reviewer只能基于允许访问的原始文件与运行结果判断；用回归任务检查证据可读率、重复动作、无证据升级和Fresh复核结果。'],['为什么不用更长的Prompt？','怎样证明Reviewer真的读取了Artifact？','修改后有什么可量化指标？'],'这是最适合映射百度质量岗位的故障案例：Agent测试不能只看最终文本，还要测试状态流转和证据交接。','中等',['百度测开','真实面经','Bad-case','证据交接'],'高压'),
  X('adaptivevuls','百度一面复盘','Agent 第一次 PoC 或工具执行失败，为什么不能直接判定漏洞不存在？','失败只说明这次尝试没有得到预期结果；必须先区分输入、环境、工具、前置条件、可达性和漏洞机制本身，只有决定性证据否定核心假设时才能关闭。',['输入失败：触发形态、编码或协议不匹配；环境失败：依赖、版本、配置、权限或服务未就绪；工具失败：超时、崩溃、脏输出或副作用状态未知。','路径失败还要区分当前入口不可达与所有合理入口都不可达；一次负例通常只能缩小Scope，不能自动证明整个项目安全。','系统应保存命令、退出码、日志、环境与Artifact，形成新的证据缺口；修复环境后重试，或设计正负对照与竞争解释来决定refute、narrow还是park。'],['超时应该算哪类失败？','什么证据足以Refute？','怎样避免无限重试？'],'这体现测开能力：区分被测系统缺陷、测试环境故障、测试工具故障和真实阴性。','中等',['百度测开','真实面经','失败归因','PoC'],'必背'),
  X('harness','百度一面复盘','Workflow-Harness 和 Agent Skill 的区别是什么？','Skill主要告诉一次Agent执行“可以怎样做”，Harness在Agent外部决定“调用谁、何时调用、给什么状态、怎样交接、失败后去哪以及何时结束”。',['Skill是可复用的领域手册，可包含步骤、示例、脚本和参考资料，改善单个Agent Turn的知识与操作方式，但不天然拥有工具权限或权威状态写入权。','Harness负责Runner Adapter、Fresh/Resume Session、Workspace、结构化上下文、分支循环、重试、Artifact、Evidence Gate和终止条件，这些由代码与运行时强制。','两者可以组合：Skill作为某次调用的知识输入，Harness作为整个长任务的调度、交接和验收系统；类比为“员工操作手册”和“项目管理与验收系统”。'],['Skill能否自己维护状态？','Harness是不是硬编码状态机？','只用LangGraph能否替代？'],'回答时先用一句对比和类比，再补项目中的Fresh Reviewer与证据Gate实例。','简单',['百度测开','真实面经','Harness','Skill'],'必背'),
  X('agent','百度一面复盘','怎样公平测试 Bare Agent、Skill 和 Harness 的效果？','设置 Bare、同模型加Skill、同知识加Harness三组，控制目标、模型、工具和总预算，多次重复；同时比较最终结果、过程错误和单位成本。',['T1只给任务目标；T2增加同一份领域Skill；T3使用相同知识，但由Harness管理显式状态、Session、Artifact、分支和复核，避免把更多知识误当成Harness收益。','匹配Token、墙钟或模型调用预算，固定目标版本、工具权限和环境快照；使用多随机种子与盲审，报告置信区间而非只挑最好一次。','最终看任务成功、验证后的发现、错误结论；过程看过早终止、重复动作、失败后错误关闭、证据交接；效率看Token、步骤、延迟，并对Fresh Review、显式状态、Resume做消融。'],['Harness多一次Reviewer是否天然不公平？','没有完整Ground Truth怎么办？','应该选Token还是墙钟做预算？'],'核心不是“谁找到漏洞多”，而是相同资源下谁更正确、可恢复、可复核。','困难',['百度测开','真实面经','Agent Eval','Ablation'],'高压'),
  X('agent','百度一面复盘','Agent 依赖人提供的经验，但经验本身是错的，系统怎么办？','经验只负责提出问题和调整调查优先级，当前目标的源码、配置和运行证据负责回答问题；错误经验不能直接改变事实状态、形成结论或触发高风险动作。',['每条经验保存来源、适用语言/版本、成立前提、已知反例、置信度和更新时间；例如“pickle可能RCE”还必须验证输入可控、路径可达、信任边界和真实影响。','证据优先级可设为当前目标运行结果与源码配置高于官方文档，高于历史案例与模型记忆；冲突时收窄、降权或否定经验在当前目标的适用性。','Fresh Reviewer检查竞争解释，经验库记录命中与失败案例并持续修订；工具侧仍执行最小权限、Sandbox和审批，防错误经验直接驱动危险命令。'],['谁有权修改经验库？','错误经验已经写入长期Memory怎么办？','Fresh Reviewer也相信同一经验怎么办？'],'记住一句话：经验负责提出问题，目标证据负责回答问题。','困难',['百度测开','真实面经','错误经验','Memory Poisoning'],'高压'),
  X('agent','百度一面复盘','面试中被问“怎么测试 Agent 效果”，怎样先给一个简单完整的回答？','先按最终效果、过程正确性、鲁棒性、效率和安全性五个维度回答，再补固定版本、多次运行和Trace归因，足以覆盖简单追问。',['最终效果：任务是否完成、答案和环境最终状态是否正确；过程正确性：工具、参数、结果理解、重复调用和终止是否合理。','鲁棒性：注入模型超时、429、工具失败、非法JSON、Session丢失和部分副作用，检查重试、恢复、降级或安全停止。','效率与安全：统计Token、步骤、延迟、成本、越权和敏感数据；冻结模型/Prompt/工具/数据版本，多次运行统计成功率并保存完整Trace。'],['非确定输出怎么断言？','最终结果对但过程越权算成功吗？','哪些故障最值得优先注入？'],'简单问题先回答五维框架，不必一上来展开完整评测平台。','简单',['百度测开','真实面经','Agent测试','五维评测'],'必背'),
  X('agent','百度一面复盘','怎样用四句话介绍基于 LightRAG 的知识图谱项目？','先说任务目标，再说 LightRAG 离线构图、向量与图混合检索，最后说明知识怎样交给 Planner；必须明确这里使用的是 LightRAG，不是 Microsoft GraphRAG。',['口述示例：系统面向复杂网络环境中的长链路漏洞利用任务，知识侧使用CWE、CVE等权威安全数据，并预先设计十类安全实体约束。','LightRAG将原始文档切成Chunk，由LLM抽取实体、属性和关系，经过实体去重、关系合并和描述更新后写入Neo4j；同时为原始文本块、实体描述和关系描述建立向量索引。','查询时融合语义检索与图关系查询，补充攻击者、攻击模式、先决条件、漏洞弱点、目标资产、利用工具、攻击技术和后置影响等关联知识，再作为可追溯上下文提供给Planner。'],['为什么不是Microsoft GraphRAG？','十类实体约束解决什么？','LLM抽错实体关系怎么办？'],'这是第二项目知识模块的推荐口径；不要再笼统称为Microsoft GraphRAG或只说“接了向量库”。','简单',['百度测开','真实面经','LightRAG','Neo4j','项目表达'],'必背'),
  X('agent','国防项目','请用一分钟介绍“基于知识图谱与 MCP 的自主漏洞利用智能体”。','这是面向复杂网络环境长链路漏洞利用任务的Planner–Actor智能体：用漏洞知识图谱辅助规划，用MCP统一异构工具，用状态机根据执行反馈持续推进或重规划。',['背景与目标：单个扫描器或脚本只能完成局部步骤，系统需要根据目标状态完成多阶段漏洞利用规划与执行，并在某一步失败后继续寻找可行路径。','完整链路：CWE/CVE知识经LightRAG与Neo4j形成知识图谱和混合索引→Planner结合目标状态与知识生成攻击路径→Actor通过MCP工具执行→结构化结果与Error Log回写状态机→继续、换工具、调参数或重规划。','结果口径：项目通过国防科研项目验收，在目标网络环境中完成无人工干预的多阶段漏洞利用规划与执行，长链路任务成功率和异常恢复能力达到验收要求；不公开未经授权的具体数字。'],['你个人负责哪些模块？','为什么不能只用一个大模型加工具？','一个真实失败是怎样恢复的？'],'面试先讲“目标—四段链路—结果”，再按知识、规划、工具、状态四层展开。','简单',['国防项目','项目介绍','Planner-Actor','MCP'],'必背'),
  X('agent','国防项目','漏洞链知识图谱从原始文档到 Neo4j 经历哪些步骤？','先约束实体Schema，再由LightRAG完成Chunk与LLM抽取，经过实体归一、关系合并和描述更新后写入Neo4j，同时保留原文来源与向量索引。',['数据源以CWE、CVE等权威安全材料为主；十类实体约束限定允许抽取的安全对象和字段，降低同一概念多种名称、关系方向混乱和无关实体膨胀。','文档切片后抽取实体、属性与关系；实体去重需要名称规范化、别名和上下文判断，关系合并要处理重复边、方向、属性和相互冲突的描述。','图节点和边应保留source/chunk等可追溯信息；原始Chunk、实体描述和关系描述分别建立向量索引，Neo4j承担结构化关系查询。'],['十类实体分别是什么？','实体去重只靠字符串相似度吗？','知识更新时旧描述怎样处理？'],'具体十类Schema若受项目限制，只列能够公开确认的类别，不临场补造剩余名称。','中等',['国防项目','LightRAG','Knowledge Graph','Neo4j'],'高压'),
  X('agent','国防项目','为什么要同时索引文本块、实体描述和关系描述？','三种索引覆盖不同检索粒度：文本块保留原始语境，实体描述定位安全对象，关系描述召回“对象之间怎样关联”，再用图查询扩展结构化邻域。',['只检索Chunk容易得到文字相似但关系不完整的段落；只检索实体会丢失原文条件和上下文；关系向量能匹配“利用什么弱点影响什么资产”这类自然语言意图。','在线查询可先做语义召回，再依据命中实体/关系进入Neo4j补充关联知识，最后去重、过滤和组织为Planner上下文。','每一路都要独立评测命中率与噪声，并保留来源；图谱抽取结果是索引材料而非绝对事实，关键条件仍回到原始文档核对。'],['三路召回怎样融合？','图查询和向量查询谁先执行？','关系描述由谁生成？'],'回答重点是“文本语境 + 对象定位 + 关系扩展”的互补性，不编造线上权重或TopK。','困难',['国防项目','Hybrid Retrieval','Vector Index','Neo4j'],'深挖'),
  X('agent','国防项目','Planner–Actor、MCP 与状态机在第二项目中分别负责什么？','Planner决定高层攻击路径，Actor执行具体步骤，MCP统一工具契约，状态机保存目标与任务进度并根据结构化反馈触发继续、调整或重规划。',['Planner读取任务目标、当前状态和检索知识，输出有前置条件、工具需求和预期结果的高层步骤；它不直接拼接Shell命令。','Actor选择并调用MCP化的扫描器、漏洞利用脚本和环境操作；Tool Schema统一参数、结果和错误，使高层规划不绑定底层脚本实现。','状态机接收成功结果和Error Log：参数不合适则调整，工具不可用则替换，路径前提不成立则让Planner重规划，从而避免单步失败直接中断整条链。'],['Planner和Actor能否由同一模型承担？','MCP是不是只做接口包装？','怎样避免无限重规划？'],'四者边界要讲清：知识提供依据，Planner做决策，Actor/MCP执行，状态机拥有可恢复进度。','中等',['国防项目','Planner-Actor','MCP','State Machine'],'必背'),
  X('algorithm','滑动窗口','滑动窗口最大值为什么使用单调双端队列，代码边界怎么处理？','队列保存下标并保持对应值单调递减：队首始终是当前窗口最大值；每个下标最多入队、出队一次，因此时间O(n)、空间O(k)。',['遍历下标i：先移除`deque[0] <= i-k`的过期元素；再从队尾移除所有`nums[deque[-1]] <= nums[i]`的元素；最后把i入队。','当`i >= k-1`时输出`nums[deque[0]]`；保存下标而不是值，才能判断最大值是否已滑出窗口。','明确处理空数组、k<=0、k>len(nums)、k=1、重复最大值；若题目保证1<=k<=n，可说明前置条件后省去异常分支。'],['为什么队尾可以删除比当前值小的元素？','相等元素保留哪个下标？','如何改成滑动窗口最小值？'],'百度AI测开一面真实手撕题；建议独立写出Python版本并手动走`[1,3,-1,-3,5,3,6,7], k=3`。','中等',['百度测开','真实面经','单调队列','Deque'],'必背')
);

